const COURSES = [{"slug": "mechanics", "title": "Mechanics and Heat", "scope": "Motion, vectors, forces, work, energy, temperature and heat. New merged lectures are the main mechanics source; the older heat lecture supplies thermal topics.", "source": "1-FxWftel94cEQ9LPiUPpzLy1OYMKhGVg", "lessons": [{"title": "Choose units and describe motion", "concept": "Position tells you where an object is. Displacement is final position minus initial position; distance counts the entire path. Average velocity uses displacement, while average speed uses distance. A negative velocity gives direction, not a negative speed.", "formula": "\\bar v=\\Delta x/\\Delta t,\\qquad \\text{average speed}=\\text{distance}/\\Delta t", "steps": "Draw a number line and choose the positive direction. Record start and finish separately from the route. Convert minutes to seconds before calculating.", "example": "A student walks 30 m east and 10 m west in 20 s. Distance is 40 m, displacement is 20 m east, average speed is 2 m/s, and average velocity is 1 m/s east.", "trap": "Do not replace displacement with distance in a velocity question.", "q": "A runner completes one lap and returns to the start. Average velocity is:", "options": ["Always positive", "Impossible to define", "Zero", "Equal to average speed"], "answer": 2, "why": "The net displacement is zero even though the distance travelled is not.", "problem": "A cart travels 12 m right then 4 m left in 4 s. Find distance, displacement, average speed and average velocity.", "solution": "Distance = 16 m; displacement = +8 m; speed = 16/4 = 4 m/s; velocity = 8/4 = +2 m/s. Award one mark for each quantity.", "id": "mechanics-1", "teaching": {"objectives": ["Distinguish distance from signed displacement.", "Calculate average speed and average velocity from a route."], "prerequisites": "Add and subtract lengths; divide by elapsed time; convert minutes to seconds.", "symbols": [{"symbol": "\\Delta x", "meaning": "final position minus initial position", "unit": "m"}, {"symbol": "\\Delta t", "meaning": "elapsed time", "unit": "s"}, {"symbol": "\\bar v", "meaning": "average velocity", "unit": "m/s"}], "method": ["Choose east or right as positive and sketch the route.", "Add every path length for distance; subtract start position from finish for displacement.", "Divide distance and displacement separately by the same total time.", "Attach a direction to velocity and a unit to every result."], "worked": ["Take east as positive: the two legs are +30 m and -10 m.", "Distance counts both legs: 30 + 10 = 40 m; displacement is 30 - 10 = +20 m.", "Over 20 s, average speed is 40/20 = 2 m/s and average velocity is +20/20 = +1 m/s, east."], "selfCheck": {"question": "Can average speed be nonzero while average velocity is zero?", "answer": "Yes. A return trip has zero displacement but a positive total distance."}, "examTip": "Write the two numerators before dividing: distance for speed, displacement for velocity. This earns method marks even if arithmetic slips."}, "references": []}, {"title": "Constant acceleration and graphs", "concept": "Acceleration measures the change of velocity per second. On a position-time graph, slope is velocity. On a velocity-time graph, slope is acceleration and signed area is displacement. The constant-acceleration equations require acceleration to remain constant.", "formula": "v=u+at,\\quad s=ut+\\tfrac12at^2,\\quad v^2=u^2+2as", "steps": "List u, v, a, s and t. Select an equation containing the required unknown and only known quantities. Keep a negative sign for a quantity opposite your chosen direction.", "example": "A car starts from rest and accelerates at 3 \\(\\mathrm{m/s^2}\\) for 4 s. Its speed is 12 m/s and displacement is 24 m. The triangular area under its velocity-time graph gives the same displacement.", "trap": "A straight horizontal velocity-time graph means zero acceleration, not zero velocity.", "q": "The area under a velocity-time graph gives:", "options": ["Displacement", "Force", "Speed at the final instant", "Acceleration"], "answer": 0, "why": "Area has units (m/s) times s = m and includes the sign of velocity.", "problem": "A car slows from 20 to 8 m/s in 4 s with constant acceleration. Find acceleration and displacement.", "solution": "a = (8-20)/4 = -3 \\(\\mathrm{m/s^2}\\). s = [(20+8)/2] times 4 = 56 m. Two marks for each calculation, including the sign and unit.", "id": "mechanics-2", "teaching": {"objectives": ["Select a constant-acceleration equation from the known quantities.", "Interpret slope and area on a velocity-time graph."], "prerequisites": "Signed velocity; rectangle and triangle areas; rearranging a simple equation.", "symbols": [{"symbol": "u", "meaning": "initial velocity", "unit": "m/s"}, {"symbol": "v", "meaning": "final velocity", "unit": "m/s"}, {"symbol": "a", "meaning": "constant acceleration", "unit": "m/s²"}, {"symbol": "s", "meaning": "displacement", "unit": "m"}, {"symbol": "t", "meaning": "elapsed time", "unit": "s"}], "method": ["List the known quantities with signs and identify the unknown.", "Check that the acceleration is constant before using the equations.", "Choose an equation without an extra unknown, then substitute with units.", "Use graph slope or area as an independent interpretation of the result."], "worked": ["Starts from rest means u = 0; the example gives a = 3 m/s² and t = 4 s.", "The velocity gain is at = 12 m/s, so v = 12 m/s.", "The displacement is one half times 3 times 4² = 24 m.", "On the velocity-time graph the triangle has base 4 s and height 12 m/s; its area is also 24 m."], "selfCheck": {"question": "A car has velocity +8 m/s and acceleration -2 m/s². Is it initially speeding up?", "answer": "No. Acceleration opposes its current velocity, so its speed initially decreases."}, "examTip": "For a graph, state which axes you used before calculating slope or area; their units identify acceleration or displacement.", "assumptions": "The equations in this lesson assume constant acceleration throughout the stated interval."}, "references": []}, {"title": "Resolve vectors before adding", "concept": "A vector has size and direction. Two vectors must be added through their signed components, not by simply adding magnitudes. The resultant points from the initial tail to the final head in a head-to-tail drawing.", "formula": "A_x=A\\cos\\theta,\\quad A_y=A\\sin\\theta,\\quad R=\\sqrt{R_x^2+R_y^2}", "steps": "In the displayed component formulas, theta is measured counterclockwise from positive x. If the question measures from another axis, draw the triangle and choose sine or cosine from that triangle. Add signed horizontal and vertical components separately. Check the quadrant before giving the resultant angle.", "example": "A 3 N force east and a 4 N force north produce a 5 N resultant, 53.1 degrees north of east. The balancing force is 5 N in the opposite direction.", "trap": "The inverse tangent alone can return the wrong quadrant.", "q": "Two perpendicular forces of 6 N and 8 N have resultant magnitude:", "options": ["10 N", "48 N", "2 N", "14 N"], "answer": 0, "why": "The Pythagorean calculation gives the square root of 36+64 = 10 N.", "problem": "Find the magnitude and direction of a vector with components -3 m and +4 m.", "solution": "Magnitude = 5 m. The vector is in quadrant II: 126.9 degrees counterclockwise from positive x, or 53.1 degrees north of west. Two marks for magnitude and two for a correct direction.", "id": "mechanics-3", "teaching": {"objectives": ["Add perpendicular vectors using signed components.", "Give a resultant direction in the correct quadrant."], "prerequisites": "Right-triangle trigonometry; Pythagoras; compass directions.", "symbols": [{"symbol": "A_x", "meaning": "horizontal vector component", "unit": "same as vector"}, {"symbol": "A_y", "meaning": "vertical vector component", "unit": "same as vector"}, {"symbol": "R", "meaning": "resultant magnitude", "unit": "same as vector"}, {"symbol": "\\theta", "meaning": "angle from the stated axis", "unit": "degrees or radians"}], "method": ["Draw axes and identify the reference axis for each angle.", "Resolve each vector and assign signs to its components.", "Add horizontal components and vertical components separately.", "Calculate magnitude and use component signs to choose the direction."], "worked": ["East and north are perpendicular, so the example has Rx = 3 N and Ry = 4 N.", "The magnitude is the square root of 3² + 4², giving 5 N.", "The angle satisfies tan θ = 4/3, so θ = 53.1° north of east.", "A balancing force reverses both components: 3 N west and 4 N south, with the same 5 N magnitude."], "selfCheck": {"question": "Does a vector with negative horizontal and positive vertical components point northeast?", "answer": "No. It points northwest, in quadrant II."}, "examTip": "Report both an angle and its reference direction; an angle alone can leave the quadrant ambiguous."}, "references": []}, {"title": "Projectiles: one time, two directions", "concept": "Ignoring air resistance, horizontal acceleration is zero and vertical acceleration is downward. Horizontal and vertical motion share the same time. At the top, only the vertical velocity becomes zero; horizontal velocity continues.", "formula": "v_x=u\\cos\\theta,\\quad v_y=u\\sin\\theta-gt,\\quad y=u\\sin\\theta\\,t-\\tfrac12gt^2", "steps": "Resolve the launch velocity. Solve the vertical equation for the flight time, then use that time horizontally. Use the same-height range formula only when launch and landing heights match.", "example": "A ball leaves a horizontal table at 3 m/s and takes 0.4 s to land. Range = 1.2 m and drop = 0.5 times 9.8 times 0.4 squared = 0.784 m.", "trap": "Do not set the total velocity to zero at the highest point.", "q": "At the top of a projectile path, acceleration is:", "options": ["Zero", "Horizontal", "Upward", "Downward with magnitude g"], "answer": 3, "why": "Gravity continues to act at the top.", "problem": "A ball is projected horizontally at 5 m/s from a height of 4.9 m. Ignore air resistance and use g = 9.8 \\(\\mathrm{m/s^2}\\). Find flight time and horizontal range.", "solution": "4.9 = 0.5 times 9.8 times \\(t^2\\), so t = 1 s. Range = 5 times 1 = 5 m. Two marks per result with the equation shown.", "id": "mechanics-4", "teaching": {"objectives": ["Separate a projectile into horizontal and vertical motions.", "Use the shared flight time to calculate horizontal range."], "prerequisites": "Constant-acceleration motion; squaring and square roots; horizontal and vertical directions.", "symbols": [{"symbol": "u_x", "meaning": "initial horizontal velocity", "unit": "m/s"}, {"symbol": "u_y", "meaning": "initial vertical velocity", "unit": "m/s"}, {"symbol": "g", "meaning": "gravitational acceleration magnitude", "unit": "m/s²"}, {"symbol": "t", "meaning": "flight time", "unit": "s"}], "method": ["Draw the launch point and select a positive vertical direction.", "Write horizontal motion with zero acceleration and vertical motion with gravity.", "Use the height information to find the positive physical flight time.", "Use this same time in the horizontal displacement equation."], "worked": ["A horizontal launch has initial vertical velocity zero; its horizontal velocity remains 3 m/s.", "The stated time is 0.4 s, so horizontal range is 3 times 0.4 = 1.2 m.", "The vertical drop is one half times 9.8 times 0.4² = 0.784 m.", "The unequal range and drop are consistent because the two directions obey different motion equations."], "selfCheck": {"question": "At the highest point of an angled projectile, which velocity component is zero?", "answer": "Only the vertical component; horizontal velocity remains constant in this model."}, "examTip": "If you choose upward positive, the downward displacement and acceleration must both carry negative signs.", "assumptions": "Ignore air resistance and take gravity as uniform; launch and landing heights need not match."}, "references": []}, {"title": "Newton laws and friction", "concept": "A free-body diagram shows only forces acting on the selected object. Net force causes acceleration. Action-reaction forces act on different objects and therefore do not cancel on one free-body diagram. Static friction adjusts up to its maximum; kinetic friction applies during sliding.", "formula": "\\sum F=ma,\\quad W=mg,\\quad f_k=\\mu_kN,\\quad f_s\\leq\\mu_sN", "steps": "Choose one object, draw its forces, select axes, then write one force equation per axis. On an incline, resolve weight parallel and perpendicular to the plane.", "example": "A 2 kg block on a horizontal surface is pulled with 10 N. With kinetic friction 4 N, the net force is 6 N and acceleration is 3 \\(\\mathrm{m/s^2}\\).", "trap": "The normal force is not always mg: angled pulls and inclines change it.", "q": "An object moving at constant velocity has:", "options": ["A forward net force", "Increasing acceleration", "Zero net force", "No forces acting at all"], "answer": 2, "why": "Constant velocity means zero acceleration, so forces balance.", "problem": "A 5 kg block slides to the right on a horizontal floor with coefficient of kinetic friction 0.2. It is pulled horizontally to the right with 20 N. Use g = 10 \\(\\mathrm{m/s^2}\\). Find normal force, friction and acceleration.", "solution": "N = 50 N, friction = 0.2 times 50 = 10 N, net force = 10 N, a = 1\\(\\frac05\\) = 2 \\(\\mathrm{m/s^2}\\). One mark for each step.", "id": "mechanics-5", "teaching": {"objectives": ["Construct a free-body diagram for one selected object.", "Use net force and friction to find acceleration."], "prerequisites": "Signed addition; mass and weight; perpendicular directions.", "symbols": [{"symbol": "m", "meaning": "object mass", "unit": "kg"}, {"symbol": "N", "meaning": "normal contact force", "unit": "N"}, {"symbol": "\\mu_k", "meaning": "coefficient of kinetic friction", "unit": "dimensionless"}, {"symbol": "a", "meaning": "acceleration", "unit": "m/s²"}], "method": ["Isolate one object and draw only the forces acting on it.", "Choose axes and use the perpendicular force balance to obtain the normal force if needed.", "Choose static or kinetic friction from the stated motion.", "Add signed forces along the motion and divide the net force by mass."], "worked": ["Choose the 10 N pull as positive; the 4 N sliding friction acts in the opposite direction.", "The horizontal net force is 10 - 4 = 6 N.", "For the 2 kg block, a = 6/2 = 3 m/s² in the direction of the pull.", "Weight and normal force balance vertically under the horizontal-surface assumptions, so they do not enter the horizontal sum."], "selfCheck": {"question": "A sliding block has a 7 N pull and 7 N friction. Must it be at rest?", "answer": "No. Zero net force gives zero acceleration; it may continue moving at constant velocity."}, "examTip": "Show the signed force equation before substitution; do not write the applied force alone as ma.", "assumptions": "The example treats the block as sliding and the given 4 N as kinetic friction."}, "references": []}, {"title": "Circular motion and connected objects", "concept": "Changing direction is acceleration even at constant speed. Centripetal means inward; it names the required net force, not an extra physical force. In an ideal taut string over a massless frictionless pulley, connected objects share acceleration magnitude.", "formula": "a_r=v^2/r,\\qquad \\sum F_{\\rm inward}=mv^2/r", "steps": "Identify which real forces can point inward. For connected objects draw separate diagrams, use consistent motion directions and eliminate the common tension.", "example": "A 2 kg object moves at 3 m/s in a circle of radius 1.5 m. Inward acceleration = 6 \\(\\mathrm{m/s^2}\\) and inward net force = 12 N.", "trap": "Do not add a separate centripetal force to tension or gravity.", "q": "Doubling speed at fixed radius changes centripetal acceleration by a factor of:", "options": ["Two", "Four", "Eight", "One half"], "answer": 1, "why": "The speed is squared.", "problem": "An ideal Atwood machine has masses 2 kg and 3 kg. Use g = 10 \\(\\mathrm{m/s^2}\\). Find acceleration and tension.", "solution": "Net driving force on the two-mass system is (3-2) times 10 = 10 N. Total mass = 5 kg, so a = 2 \\(\\mathrm{m/s^2}\\). For the rising 2 kg mass, T-20 = 2 times 2, hence T = 24 N. Two marks per result.", "id": "mechanics-6", "teaching": {"objectives": ["Identify the real forces that supply inward acceleration.", "Set up separate force equations for connected masses."], "prerequisites": "Newton second law; force diagrams; uniform circular motion directions.", "symbols": [{"symbol": "v", "meaning": "speed along the circle", "unit": "m/s"}, {"symbol": "r", "meaning": "circle radius", "unit": "m"}, {"symbol": "a_r", "meaning": "inward acceleration", "unit": "m/s²"}, {"symbol": "T", "meaning": "string tension", "unit": "N"}], "method": ["For circular motion mark the centre and select inward as a positive radial direction.", "Sum the actual radial force components and equate them to mv²/r.", "For connected objects draw a diagram for each mass and use compatible acceleration directions.", "Use the ideal string constraint to share acceleration magnitude, then solve for acceleration and tension."], "worked": ["In the circular example, v = 3 m/s and r = 1.5 m.", "Squaring speed first gives ar = 9/1.5 = 6 m/s², directed toward the centre.", "Multiplying by the 2 kg mass gives 12 N inward net force.", "The problem would need a physical setup to decide whether tension, gravity or another force provides those 12 N."], "selfCheck": {"question": "If the speed remains fixed and radius doubles, what happens to inward acceleration?", "answer": "It halves because v²/r is inversely proportional to radius at fixed speed."}, "examTip": "Do not put tension and an extra centripetal force on the same diagram; centripetal describes the inward net force.", "assumptions": "Connected-object formulas assume a taut massless string and an ideal frictionless pulley when stated."}, "references": []}, {"title": "Work and kinetic energy", "concept": "Work transfers energy when a force has a component along displacement. A perpendicular force does no work. Net work equals the change in kinetic energy. For a varying force along a line, work is the signed area under the force-position graph.", "formula": "W=Fd\\cos\\theta,\\quad K=\\tfrac12mv^2,\\quad W_{\\rm net}=K_f-K_i", "steps": "Identify the angle between force and displacement. Calculate work by each relevant force or use net work directly. Check whether a negative work should reduce the speed.", "example": "A 10 N force pulls through 3 m at 60 degrees to displacement. Work = 10 times 3 times 0.5 = 15 J.", "trap": "Use the force-displacement angle, not an unrelated angle in the drawing.", "q": "A force perpendicular to displacement does work equal to:", "options": ["Fd", "Zero", "-Fd", "Half of Fd"], "answer": 1, "why": "The cosine of 90 degrees is zero.", "problem": "A 2 kg object speeds up from 3 to 5 m/s. Find the net work done.", "solution": "Net work = 0.5 times 2 times (25-9) = 16 J. Give marks for the energy theorem, both squared speeds, substitution and unit.", "id": "mechanics-7", "teaching": {"objectives": ["Determine the sign of work from force and displacement directions.", "Calculate net work from a change in kinetic energy."], "prerequisites": "Cosine of common angles; squaring speed; positive and negative energy transfers.", "symbols": [{"symbol": "W", "meaning": "work transferred by a force", "unit": "J"}, {"symbol": "F", "meaning": "force magnitude", "unit": "N"}, {"symbol": "d", "meaning": "displacement magnitude", "unit": "m"}, {"symbol": "K", "meaning": "kinetic energy", "unit": "J"}], "method": ["Identify the displacement and the angle between it and the force.", "Use only the force component along displacement to calculate work.", "Add work from all forces for net work, or use the kinetic-energy change.", "Check that positive net work corresponds to an increase in speed."], "worked": ["The example states an angle of 60° between the 10 N force and 3 m displacement.", "Only 10 cos 60° = 5 N acts along the displacement.", "Work by this force is 5 times 3 = 15 J.", "The remaining perpendicular component contributes zero work; 15 J is not automatically net work if other forces also do work."], "selfCheck": {"question": "Can a nonzero force do zero work during a displacement?", "answer": "Yes. A force perpendicular to the displacement does zero work."}, "examTip": "When using the energy theorem, square each speed before subtracting; (vf - vi)² is not vf² - vi²."}, "references": []}, {"title": "Energy conservation and springs", "concept": "Energy can move between kinetic, gravitational and elastic stores. Mechanical energy stays constant only when the model excludes losses or other transfers. Choose a height reference; only height changes affect the result.", "formula": "K_i+U_i+W_{\\rm other}=K_f+U_f,\\quad U_g=mgh,\\quad U_s=\\tfrac12kx^2", "steps": "State the system and the initial and final positions. Cross out zero terms. Include friction as an energy transfer rather than silently ignoring it.", "example": "A mass drops 5 m from rest without losses. With g = 10 \\(\\mathrm{m/s^2}\\), its final speed follows v squared = 2gh = 100, giving 10 m/s independent of mass.", "trap": "Spring extension is measured from natural length, not total length.", "q": "If the extension of a Hooke-law spring doubles while k stays constant, its stored energy becomes:", "options": ["Four times as large", "Twice as large", "Unchanged", "Half as large"], "answer": 0, "why": "Spring energy is proportional to extension squared.", "problem": "A spring of constant 200 N/m is compressed by 0.10 m and releases a 0.50 kg block on a frictionless horizontal surface. Find its speed when the spring returns to natural length.", "solution": "Spring energy = 0.5 times 200 times 0.10 squared = 1 J. Set 1 = 0.5 times 0.50 times v squared to get v = 2 m/s. Two marks for each stage.", "id": "mechanics-8", "teaching": {"objectives": ["Track kinetic, gravitational and spring energy between two states.", "Identify when a loss term is required in an energy balance."], "prerequisites": "Work and kinetic energy; choosing a height reference; spring compression or extension.", "symbols": [{"symbol": "U_g", "meaning": "gravitational potential energy", "unit": "J"}, {"symbol": "U_s", "meaning": "elastic potential energy", "unit": "J"}, {"symbol": "k", "meaning": "spring stiffness", "unit": "N/m"}, {"symbol": "x", "meaning": "spring deformation from natural length", "unit": "m"}], "method": ["Name initial and final states and choose a zero-height level.", "Write the energy balance before removing terms that are zero.", "Include friction or other transfers if the model contains them.", "Solve for the unknown and check the physical sign and units."], "worked": ["Set the final height to zero; the initial height is then 5 m.", "The object starts from rest, so its initial energy is gravitational: mg times 5.", "With no losses, mg times 5 equals one half mv²; dividing by mass shows why mass cancels.", "Using g = 10 m/s² gives v² = 100 and speed v = 10 m/s."], "selfCheck": {"question": "Would the same loss-free 5 m fall give a heavier object a larger final speed?", "answer": "No. Mass cancels from mgh = one half mv²."}, "examTip": "For spring energy convert centimetres to metres before squaring the deformation.", "assumptions": "The falling-mass example neglects air resistance and other energy transfers; spring-energy formulas require the proportional linear range."}, "references": []}, {"title": "Temperature, calorimetry and phase changes", "concept": "Temperature describes thermal state; heat is energy transferred because of a temperature difference. During a phase change of a pure substance at fixed pressure, energy can transfer without a temperature change. In an insulated mixing model, heat lost equals heat gained.", "formula": "Q=mc\\Delta T,\\quad Q=mL,\\quad T_K=T_C+273.15", "steps": "Separate warming and phase-change stages. Use mass in kg when c and L use SI units. For mixing, use positive temperature drops and rises on opposite sides of the energy balance.", "example": "Heating 0.20 kg of water by 10 degrees C needs Q = 0.20 times 4200 times 10 = 8400 J. Melting ice requires a separate latent-heat term.", "trap": "A temperature difference of 10 degrees C equals 10 K; an absolute temperature does not.", "q": "During melting at fixed pressure, added heat mainly:", "options": ["Raises temperature continuously", "Changes phase", "Decreases mass", "Disappears"], "answer": 1, "why": "Energy changes the phase while temperature remains at the melting point.", "problem": "How much energy heats 0.50 kg of water from 20 to 30 degrees C? Use c = 4200 J/(kg K).", "solution": "Temperature rise = 10 K. Q = mc times temperature rise = 0.50 times 4200 times 10 = 21000 J. Four marks: model, temperature difference, substitution, result/unit.", "id": "mechanics-9", "teaching": {"objectives": ["Separate temperature change from phase change in a heating problem.", "Apply an energy balance with consistent mass and temperature units."], "prerequisites": "Energy in joules; mass conversion; subtraction of temperatures.", "symbols": [{"symbol": "Q", "meaning": "energy transferred as heat", "unit": "J"}, {"symbol": "c", "meaning": "specific heat capacity", "unit": "J/(kg K)"}, {"symbol": "L", "meaning": "specific latent heat", "unit": "J/kg"}, {"symbol": "\\Delta T", "meaning": "temperature change", "unit": "K or °C difference"}], "method": ["Identify the initial and final phase and temperature.", "Split the process into warming, phase-change and further-warming stages where needed.", "Use mcΔT for each warming stage and mL for each phase change.", "Add the energy requirements or balance heat gained and lost in an insulated mixture."], "worked": ["The water remains liquid while warming, so the relevant relation is Q = mcΔT.", "A rise of 10°C is a temperature difference of 10 K.", "For 0.20 kg and c = 4200 J/(kg K), Q = 0.20 times 4200 times 10 = 8400 J.", "If the process also melts ice, that extra stage needs mL; it is not included in the 8400 J."], "selfCheck": {"question": "Does liquid water warming from 20°C to 30°C have ΔT = 283.15 K?", "answer": "No. ΔT = 10 K. The Celsius-to-kelvin offset cancels when subtracting two temperatures."}, "examTip": "On a heating curve label sloping segments mcΔT and horizontal phase-change segments mL."}, "references": []}, {"title": "Heat transfer and thermal expansion", "concept": "Conduction transfers energy through matter without bulk transport; convection uses fluid motion; radiation uses electromagnetic waves and can cross vacuum. Most solids expand on warming. A thermal insulator reduces transfer but does not create cold.", "formula": "\\Delta L=\\alpha L_0\\Delta T,\\quad P_{\\rm cond}=kA\\Delta T/L,\\quad P_{\\rm rad}=\\epsilon\\sigma A(T^4-T_s^4)", "steps": "Identify the physical mechanism first. In conduction compare area, thickness and temperature difference. In radiation always use absolute temperatures in kelvin.", "example": "Doubling the thickness of an otherwise unchanged wall halves its conductive heat-transfer rate. Doubling the area doubles that rate.", "trap": "Use kelvin in fourth-power radiation equations; Celsius produces incorrect results.", "q": "Which heat-transfer mechanism can operate through a vacuum?", "options": ["Fluid mixing", "Convection", "Conduction through air", "Radiation"], "answer": 3, "why": "Electromagnetic radiation needs no material medium.", "problem": "A rod is 2 m long and has expansion coefficient 0.000012 per K. It warms by 50 K. Find the increase in length in metres and millimetres.", "solution": "Increase = 0.000012 times 2 times 50 = 0.0012 m = 1.2 mm. Award marks for formula, substitution, metres and conversion.", "id": "mechanics-10", "teaching": {"objectives": ["Classify heat transfer as conduction, convection or radiation.", "Predict rate changes and calculate small linear expansion."], "prerequisites": "Direct and inverse proportionality; temperature differences; metres and millimetres.", "symbols": [{"symbol": "P", "meaning": "heat-transfer rate", "unit": "W"}, {"symbol": "k", "meaning": "thermal conductivity", "unit": "W/(m K)"}, {"symbol": "A", "meaning": "transfer surface area", "unit": "m²"}, {"symbol": "L", "meaning": "wall thickness", "unit": "m"}, {"symbol": "\\alpha", "meaning": "linear expansion coefficient", "unit": "K⁻¹"}], "method": ["Identify the physical mechanism and select the matching relation.", "For a comparison, hold every unstated quantity fixed and change only the named factor.", "For expansion use the original length and the temperature rise.", "Use kelvin for absolute temperatures in radiation and convert the final length if requested."], "worked": ["For conduction, the same wall material and temperature difference give P proportional to A/L.", "Doubling thickness replaces L by 2L, so P becomes P/2.", "Doubling area instead gives 2P.", "If both area and thickness double together, the factors cancel and the rate is unchanged."], "selfCheck": {"question": "A wall is made three times thicker with all other quantities unchanged. What is its new conduction rate?", "answer": "One third of the original rate."}, "examTip": "For a ratio question explicitly state what stays constant; otherwise the proportionality is incomplete.", "assumptions": "The wall comparison uses steady one-dimensional conduction with unchanged material and temperature difference."}, "references": []}], "tests": [{"name": "A", "indices": [0, 1, 2, 3, 4]}, {"name": "B", "indices": [5, 6, 7, 8, 9]}], "figure": {"src": "assets/mechanics.svg", "lessonId": "mechanics-3", "caption": "Perpendicular forces add as vectors. A 3 N east component and 4 N north component give a 5 N resultant; the balancing force points the other way."}}, {"slug": "electricity", "title": "Electricity and Magnetism", "scope": "Concept-first coverage of the course plan. Chapters 23-31 have lecture support; inductance, AC and EM waves are course-plan extensions without separate lecture files in this folder. Advanced field integrals are recognition topics, not worked derivations.", "source": "1-MQIsBh0VU5tceb9COmhxqOKTgIaTZ_g", "lessons": [{"title": "Charges, conductors and Coulomb force", "concept": "Charge is conserved and occurs in integer multiples of the elementary charge. Ordinary charging transfers electrons. Like charges repel and unlike charges attract. Conductors let charge move readily; insulators restrict it. A neutral object can still be attracted by polarization.", "formula": "F=k|q_1q_2|/r^2,\\qquad k=8.99\\times10^9\\ {\\rm N\\,m^2/C^2}", "steps": "Convert microcoulombs to coulombs and centimetres to metres. Calculate force magnitude, then use charge signs to describe direction.", "example": "Two charges at distance r exert force F. Doubling their separation gives \\(\\frac{F}{4}\\). Doubling one charge doubles the force.", "trap": "A negative charge does not mean a negative force magnitude.", "q": "A neutral object loses electrons. It becomes:", "options": ["Negative", "Positive", "Uncharged forever", "Magnetic only"], "answer": 1, "why": "Removing negative charge leaves a positive net charge.", "problem": "Two charges exert 12 N at separation r. What is the force at separation 2r, and at r if one charge is tripled?", "solution": "At 2r: 12/4 = 3 N. Tripling one charge at r: 36 N. Two marks for each ratio and result.", "id": "electricity-1", "teaching": {"objectives": ["Predict attraction or repulsion from charge signs.", "Use simple Coulomb-force ratios without unnecessary arithmetic."], "prerequisites": "Positive and negative charge; squares; micro means one millionth.", "symbols": [{"symbol": "F", "meaning": "electrostatic force magnitude", "unit": "N"}, {"symbol": "q_1,q_2", "meaning": "source charges", "unit": "C"}, {"symbol": "r", "meaning": "separation of charges", "unit": "m"}], "method": ["Mark the signs and positions of both charges.", "Predict attraction or repulsion before calculating magnitude.", "For a ratio, compare the charge product and the square of the separation.", "For a numerical force, convert charges and lengths to SI units first."], "worked": ["Keep both charges fixed and replace the separation r by 2r.", "The denominator becomes (2r)² = 4r², so the force becomes F/4.", "If instead one charge doubles at the original separation, its product with the other charge doubles, so force becomes 2F.", "Changing separation or charge magnitude alone does not change attraction into repulsion."], "selfCheck": {"question": "Tripling separation with fixed charges changes the force by what factor?", "answer": "It becomes one ninth as large."}, "examTip": "A magnitude answer is positive; state attraction or repulsion separately to communicate direction.", "assumptions": "Coulomb calculations here use point charges, or a stated model equivalent to point charges."}, "references": []}, {"title": "Electric field and superposition", "concept": "The electric field gives force per unit positive test charge. Field arrows point away from positive sources and toward negative sources. The field exists whether or not a test charge is present. Add fields as vectors, so equal magnitudes can cancel.", "formula": "E=F/q_{\\rm test},\\quad E=k|Q|/r^2,\\quad \\vec F=q\\vec E", "steps": "Draw the field from each source at the observation point. Combine directions before inserting a test charge. Reverse the force direction for a negative test charge.", "example": "At the midpoint between equal positive charges, the two electric fields oppose and cancel. Between equal opposite charges they reinforce toward the negative charge.", "trap": "Zero net field at a point does not mean each source field is zero.", "q": "A negative test charge in a field directed right feels force:", "options": ["Left", "Zero", "Right", "Up"], "answer": 0, "why": "The negative charge reverses the field direction in \\(F=qE\\).", "problem": "A field of 200 N/C points east. Find the force on a charge of -0.003 C.", "solution": "Magnitude = 0.003 times 200 = 0.60 N. Direction is west because the charge is negative. Two marks for magnitude and two for direction with reasoning.", "id": "electricity-2", "teaching": {"objectives": ["Combine electric fields by their directions at an observation point.", "Explain why a negative test charge feels force opposite the field."], "prerequisites": "Vector addition; positive and negative charges; multiplication.", "symbols": [{"symbol": "E", "meaning": "electric field magnitude", "unit": "N/C"}, {"symbol": "q", "meaning": "charge experiencing the force", "unit": "C"}, {"symbol": "F", "meaning": "force magnitude", "unit": "N"}], "method": ["Choose the observation point and draw the field arrow from each source there.", "Point away from a positive source and toward a negative source.", "Add signed collinear fields or use vector components when needed.", "Only after finding the net field, use the test-charge sign to obtain force direction."], "worked": ["At the midpoint between equal positive charges, both source distances are the same, so field magnitudes match.", "The left positive charge points the field right; the right positive charge points it left. The net field is zero.", "Replace the right source by an equal negative charge: its field now points toward it, also to the right.", "The two fields therefore reinforce, pointing from the positive source toward the negative source."], "selfCheck": {"question": "If the net field is zero at a point, is a charge placed there forced in either direction by that field?", "answer": "No. The electric force qE is zero there in the stated source-field model."}, "examTip": "Draw field arrows before multiplying by a test charge; otherwise a negative test charge can lead to two direction reversals."}, "references": []}, {"title": "Flux and Gauss law", "concept": "Electric flux measures the field passing through an oriented surface. The angle is measured from the surface normal, not the surface itself. Net flux through a closed surface depends on enclosed charge. An outside charge can affect the field at the surface but contributes zero net closed-surface flux.", "formula": "\\Phi=EA\\cos\\theta,\\quad \\Phi_{\\rm closed}=Q_{\\rm enclosed}/\\epsilon_0", "steps": "Decide whether the surface is open or closed. For a uniform field and flat area use the normal angle. For a closed surface count only enclosed charge.", "example": "A cube enclosing +q has net outward flux \\(\\frac{q}{\\varepsilon_0}\\). Moving q off-centre changes local field values but not the total flux.", "trap": "Zero net closed-surface flux does not imply zero field everywhere.", "q": "A charge outside a closed empty box gives net flux through the box of:", "options": ["\\(\\frac{q}{\\varepsilon_0}\\)", "Always positive", "Always negative", "Zero"], "answer": 3, "why": "No charge is enclosed, so total entering and leaving flux cancels.", "problem": "A uniform field of 50 N/C passes through a flat area of 0.20 square metres. The chosen surface normal points in the same direction as the field. Find flux. What if the normal is perpendicular to the field?", "solution": "Parallel normal: flux = 50 times 0.20 = 10 N m squared/C. Perpendicular normal: cosine 90 degrees = 0, so flux = 0. Two marks per case.", "id": "electricity-3", "teaching": {"objectives": ["Use the surface normal to determine electric flux.", "Distinguish enclosed charge from outside charge in Gauss law."], "prerequisites": "Surface area; normal means perpendicular; cosine at 0° and 90°.", "symbols": [{"symbol": "\\Phi", "meaning": "electric flux", "unit": "N m²/C"}, {"symbol": "E", "meaning": "electric field magnitude", "unit": "N/C"}, {"symbol": "A", "meaning": "surface area", "unit": "m²"}, {"symbol": "Q_{\\rm enclosed}", "meaning": "net charge inside a closed surface", "unit": "C"}], "method": ["Decide whether the question concerns one flat surface or a complete closed surface.", "For a flat surface, draw the normal and identify its angle to the field.", "For a closed surface, add only the enclosed charges with signs.", "Interpret positive closed flux as net outward flux and negative as net inward flux."], "worked": ["The cube is a closed surface enclosing net charge +q.", "Gauss law fixes its total outward flux as q divided by ε0.", "Moving q off-centre leaves enclosed charge unchanged, so total flux is unchanged.", "The nearby faces can now have stronger local fields; Gauss law does not say each face receives an equal share after the move."], "selfCheck": {"question": "Can an external charge produce a nonzero field on a box while contributing zero net flux through it?", "answer": "Yes. Field enters and leaves; the total closed-surface flux from that external charge cancels."}, "examTip": "The angle in EA cos θ is to the normal; a field parallel to the surface gives zero flux."}, "references": []}, {"title": "Symmetry and conductors", "concept": "Gauss law is always valid, but it easily gives field magnitude only when symmetry makes the surface calculation simple. In electrostatic equilibrium the field inside conducting material is zero and excess charge lies on its surface. A conductor is an equipotential. For the outside-sphere inverse-square rule, assume an isolated conducting sphere with no external fields.", "formula": "E_{\\rm outside\\ sphere}=k|Q|/r^2\\quad(r>R)", "steps": "Recognize spherical, cylindrical or planar symmetry before choosing a Gaussian surface. Distinguish the metal itself from an internal cavity or the space outside.", "example": "A charged conducting sphere behaves outside like a point charge at its centre. At twice the outside radius the field is one quarter as large.", "trap": "Do not extend the zero-field-in-metal statement to every cavity containing a charge.", "q": "Inside the material of a conductor in electrostatic equilibrium, the electric field is:", "options": ["Equal to its surface value", "Infinite", "Zero", "Always outward"], "answer": 2, "why": "Free charges redistribute until the internal field is cancelled.", "problem": "An isolated charged conducting sphere, with no external fields, has field magnitude 80 N/C at r = 0.20 m. Find the field at r = 0.40 m. Both distances are from the centre and outside the sphere.", "solution": "Inverse-square scaling gives 80 times (0.2\\(\\frac00\\).40) squared = 20 N/C. Credit the outside-sphere condition and inverse-square reasoning.", "id": "electricity-4", "teaching": {"objectives": ["State the electrostatic properties of conducting material.", "Use the inverse-square field rule outside a spherical conductor."], "prerequisites": "Electric field; conductor versus insulator; inverse-square ratios.", "symbols": [{"symbol": "Q", "meaning": "net sphere charge", "unit": "C"}, {"symbol": "R", "meaning": "sphere radius", "unit": "m"}, {"symbol": "r", "meaning": "distance from sphere centre", "unit": "m"}, {"symbol": "E", "meaning": "electric field magnitude", "unit": "N/C"}], "method": ["Check that the conductor is in electrostatic equilibrium.", "Distinguish a point in the conducting material from a point outside the sphere.", "For an outside point measure distance from the centre, not from the surface.", "Use the point-charge field or a simple ratio, then describe the radial direction."], "worked": ["Outside a spherically symmetric charged conducting sphere, the field has the same form as a charge at its centre.", "Compare two outside distances r and 2r.", "The square of the distance grows by a factor of four, so the field magnitude becomes E/4.", "This comparison uses centre distances; doubling the gap from the surface would generally give a different ratio."], "selfCheck": {"question": "A field is 80 N/C at 0.20 m from the centre. What is it at 0.40 m if both points are outside?", "answer": "20 N/C: the centre distance doubles and the field is divided by four."}, "examTip": "Write r > R beside the outside-sphere formula to show that its domain has been checked.", "assumptions": "The sphere is isolated with spherical symmetry and is in electrostatic equilibrium."}, "references": []}, {"title": "Potential is not field", "concept": "Electric potential is energy per unit charge, a scalar. Electric field is a vector. Add potentials with charge signs, but add fields with directions. Work by the electric field equals the decrease in electric potential energy.", "formula": "V=kQ/r\\ \\text{(zero at infinity)},\\quad \\Delta U=q\\Delta V,\\quad W_{\\rm field}=-\\Delta U", "steps": "Identify whether the question asks for energy, potential or field. Specify the reference for potential. Use the sign of q when finding energy changes.", "example": "Equal positive charges can give zero field at their midpoint but positive potential there. Cancellation rules differ for scalars and vectors.", "trap": "A charge moving to lower potential does not always lose potential energy; a negative charge does the opposite.", "q": "For equal and opposite point charges, take potential as zero at infinity. At their midpoint the potential is:", "options": ["Zero", "Undefined", "Positive", "Negative"], "answer": 0, "why": "The signed scalar potentials cancel when distances and charge magnitudes match.", "problem": "A +2 C charge moves through a potential difference of +3 V. Find its potential-energy change and the work done by the field.", "solution": "Energy change = 2 times 3 = +6 J. Work by field = -6 J. Two marks each; the signs are essential.", "id": "electricity-5", "teaching": {"objectives": ["Add scalar potentials with their charge signs.", "Relate potential difference to energy change and field work."], "prerequisites": "Scalar versus vector; signed energy changes; potential energy.", "symbols": [{"symbol": "V", "meaning": "electric potential", "unit": "V = J/C"}, {"symbol": "\\Delta V", "meaning": "final minus initial potential", "unit": "V"}, {"symbol": "\\Delta U", "meaning": "change in potential energy", "unit": "J"}, {"symbol": "q", "meaning": "moving charge", "unit": "C"}], "method": ["Separate a field question, requiring direction, from a potential question, requiring signed scalar addition.", "Choose the potential reference supplied by the problem.", "Calculate energy change from charge times final-minus-initial potential.", "Reverse the sign of that energy change to obtain work by the electric field."], "worked": ["At the midpoint of two equal positive charges, equal field arrows point in opposite directions and cancel.", "Each positive charge contributes a positive potential at that point when zero potential is chosen at infinity.", "The two potentials add rather than cancel because potential has no directional arrow.", "Thus zero net field and positive potential can occur at the same point without contradiction."], "selfCheck": {"question": "A +2 C charge moves through ΔV = +3 V. What are ΔU and work by the field?", "answer": "ΔU = +6 J and work by the field = -6 J."}, "examTip": "Write ΔV = Vfinal - Vinitial before calculating; swapping the endpoints reverses both energy and work signs."}, "references": []}, {"title": "Capacitors and dielectrics", "concept": "A capacitor stores separated charge and electric-field energy. Capacitance describes charge stored per volt. Parallel capacitors share voltage and their capacitances add. Series capacitors carry equal charge magnitude and have a smaller equivalent capacitance.", "formula": "Q=CV,\\quad U=\\tfrac12CV^2,\\quad C_{\\parallel}=C_1+C_2,\\quad 1/C_s=1/C_1+1/C_2", "steps": "Identify the connection and whether the battery remains attached. Battery connected means fixed voltage; an isolated charged capacitor has fixed charge.", "example": "Two 6 \\(\\mu\\mathrm{F}\\) capacitors give 12 \\(\\mu\\mathrm{F}\\) in parallel and 3 \\(\\mu\\mathrm{F}\\) in series. Inserting a dielectric increases capacitance.", "trap": "Do not use resistor series/parallel rules for capacitors.", "q": "Adding a dielectric to an isolated charged capacitor increases C. Its voltage:", "options": ["Decreases", "Increases", "Must stay fixed", "Becomes infinite"], "answer": 0, "why": "Charge remains fixed and \\(V=\\frac{Q}{C}\\).", "problem": "A 4 \\(\\mu\\mathrm{F}\\) capacitor is connected to 12 V. Find the charge in microcoulombs.", "solution": "Q = CV = 4 times 12 = 48 microcoulombs. In SI this is 0.000048 C. Credit formula, substitution, prefix and result.", "id": "electricity-6", "teaching": {"objectives": ["Distinguish series and parallel capacitor connections.", "Calculate stored charge and identify the effect of a dielectric."], "prerequisites": "Potential difference; charge; reciprocals and addition.", "symbols": [{"symbol": "C", "meaning": "capacitance", "unit": "F"}, {"symbol": "Q", "meaning": "stored charge magnitude on either plate", "unit": "C"}, {"symbol": "V", "meaning": "potential difference between plates", "unit": "V"}, {"symbol": "U", "meaning": "stored electric energy", "unit": "J"}], "method": ["Identify shared nodes: parallel capacitors share voltage, while ideal series capacitors carry equal charge magnitudes.", "Add capacitances for parallel or add their reciprocals for series.", "Use Q = CV with compatible prefixes such as µF times V giving µC.", "For dielectric questions first check whether voltage or charge is held fixed."], "worked": ["For two 6 µF capacitors in parallel, capacitances add: 6 + 6 = 12 µF.", "For series, 1/Cs = 1/6 + 1/6 = 1/3 in reciprocal µF, so Cs = 3 µF.", "The series result is smaller than either individual capacitor, providing a quick plausibility check.", "Inserting a suitable dielectric increases capacitance; the resulting charge or voltage change depends on the connection to a battery."], "selfCheck": {"question": "What charge magnitude is stored by 4 µF at 12 V?", "answer": "48 µC, from Q = CV."}, "examTip": "For series, invert the reciprocal sum at the end; stopping at 1/C is a common lost result mark."}, "references": [{"title": "What changes a capacitor's capacitance?", "why_it_matters": "These simple comparisons cover the geometry and dielectric ideas in the lecture without a derivation.", "formulas": ["\\(C=\\dfrac{\\varepsilon A}{d}\\)", "\\(Q=CV\\)"], "method": ["Use the first formula for parallel plates with a small gap compared with plate size, so edge effects can be ignored.", "Here \\(A\\) is overlapping plate area, \\(d\\) is separation, and \\(\\varepsilon\\) describes the material filling the gap.", "Doubling area doubles capacitance. Doubling separation halves it.", "A dielectric filling the gap increases capacitance. Battery attached: voltage stays fixed. Disconnected and isolated: charge stays fixed."], "check": {"question": "An isolated charged capacitor has capacitance \\(2\\,\\mu\\mathrm F\\) and voltage \\(12\\,\\mathrm V\\). A dielectric triples its capacitance. Find the new charge and voltage.", "steps": ["Initial charge: \\(Q=CV=2\\times12=24\\,\\mu\\mathrm C\\).", "Isolation keeps the charge at \\(24\\,\\mu\\mathrm C\\).", "New capacitance: \\(6\\,\\mu\\mathrm F\\); new voltage: \\(V=24/6=4\\,\\mathrm V\\)."], "answer": "Charge stays \\(24\\,\\mu\\mathrm C\\); voltage falls to \\(4\\,\\mathrm V\\)."}, "sources": [{"title": "Capacitance and Dielectrics lecture", "url": "https://docs.google.com/presentation/d/1jS3J5XFHXVQSUHjiQnbkzNOmktFaz-JY/edit"}]}]}, {"title": "Current, resistance and electrical power", "concept": "Current is the rate of charge flow. Conventional current follows positive-charge flow, opposite electron drift in a metal. Resistance depends on material and geometry. Ohm law describes an \\(\\Omega\\)ic element under fixed physical conditions.", "formula": "I=\\Delta Q/\\Delta t,\\quad V=IR,\\quad R=\\rho L/A,\\quad P=VI", "steps": "Use volts, amperes and \\(\\Omega\\). Choose P = VI, \\(I^2R\\) or \\(V^2\\)/R according to what is held fixed.", "example": "A 6 \\(\\Omega\\) resistor across 12 V carries 2 A and dissipates 24 W. A longer wire of the same material and area has greater resistance.", "trap": "More resistance lowers power at fixed voltage but raises power at fixed current.", "q": "At fixed voltage, doubling resistance makes power:", "options": ["Unchanged", "Double", "Half", "Four times"], "answer": 2, "why": "\\(P=\\frac{V^2}{R}\\), so doubling the denominator halves it.", "problem": "A 3 \\(\\Omega\\) resistor carries 2 A. Find voltage and power.", "solution": "V = IR = 6 V. P = VI = 12 W (or \\(I^2R\\)). Two marks per result.", "id": "electricity-7", "teaching": {"objectives": ["Find current, voltage and power for an ohmic resistor.", "Predict how wire length and area change resistance."], "prerequisites": "Charge flow; multiplication and division; circuit voltage.", "symbols": [{"symbol": "I", "meaning": "conventional current", "unit": "A"}, {"symbol": "R", "meaning": "resistance", "unit": "Ω"}, {"symbol": "V", "meaning": "potential difference", "unit": "V"}, {"symbol": "P", "meaning": "electrical power", "unit": "W"}, {"symbol": "\\rho", "meaning": "resistivity", "unit": "Ω m"}], "method": ["Label voltage across the resistor and current through it.", "Use V = IR to find the missing electrical quantity.", "Calculate power using VI or an equivalent resistor relation.", "For wire comparisons hold material and temperature fixed before changing length or area."], "worked": ["The 6 Ω resistor has 12 V across it, so I = 12/6 = 2 A.", "Its electrical power is VI = 12 times 2 = 24 W.", "Power of 24 W means 24 joules of energy are transferred each second.", "A longer wire with unchanged material, area and temperature has larger resistance because R is proportional to length."], "selfCheck": {"question": "What happens to resistance if a wire length doubles but material, area and temperature stay fixed?", "answer": "Resistance doubles."}, "examTip": "Do not confuse power in watts with energy in joules; multiply power by time when energy is requested.", "assumptions": "Ohm law is used for an ohmic resistor under unchanged physical conditions."}, "references": []}, {"title": "DC networks, Kirchhoff rules and RC behaviour", "concept": "Series resistors share current; parallel resistors share voltage. Kirchhoff junction rules express charge conservation, and loop rules express energy conservation. An initially uncharged capacitor charges gradually through a resistor and eventually blocks steady DC in the ideal model.", "formula": "R_s=R_1+R_2,\\quad 1/R_p=1/R_1+1/R_2,\\quad \\tau=RC", "steps": "Redraw nodes before deciding series or parallel. Simplify the network, find total current, then work backwards. For RC questions distinguish just after switching from long after switching.", "example": "Two 6 \\(\\Omega\\) resistors in parallel give 3 \\(\\Omega\\). Across 12 V the total current is 4 A, split equally into 2 A in each branch.", "trap": "Adjacent components in a drawing are not necessarily in series.", "q": "After a long time in an ideal DC charging circuit, capacitor current is:", "options": ["Maximum", "Negative forever", "Zero", "Equal to the battery voltage divided by the resistor resistance"], "answer": 2, "why": "After a long time, the capacitor voltage equals the battery voltage. The resistor voltage and circuit current are zero. During charging, charge moves in the wires onto and off the plates; it does not cross the ideal dielectric.", "problem": "A 4 \\(\\Omega\\) and 8 \\(\\Omega\\) resistor are in series across 24 V. Find total current and each voltage drop.", "solution": "Total resistance = 12 \\(\\Omega\\); current = 2 A; drops are 8 V and 16 V. One mark each; the drops must sum to 24 V.", "id": "electricity-8", "teaching": {"objectives": ["Reduce simple resistor networks and recover branch currents.", "Describe the initial and final behaviour of an RC charging circuit."], "prerequisites": "Ohm law; series and parallel connections; charge and energy conservation.", "symbols": [{"symbol": "R_{\\rm eq}", "meaning": "equivalent resistance", "unit": "Ω"}, {"symbol": "I", "meaning": "current", "unit": "A"}, {"symbol": "V", "meaning": "voltage", "unit": "V"}, {"symbol": "\\tau", "meaning": "RC time constant", "unit": "s"}], "method": ["Identify series elements by shared current and parallel elements by shared voltage.", "Reduce the network and calculate total source current.", "Return to the original circuit to calculate branch currents or voltage drops.", "Check junction current sums and loop voltage sums; for RC questions distinguish transient from long-time behaviour."], "worked": ["Both 6 Ω resistors are connected across the same two nodes, so they are parallel.", "Their equal-resistor equivalent is 6/2 = 3 Ω.", "The 12 V source therefore supplies 12/3 = 4 A total.", "Each branch still has 12 V and carries 12/6 = 2 A; the branch currents sum to the 4 A source current."], "selfCheck": {"question": "After a long time, does an ideal capacitor in a DC series RC circuit carry a steady current?", "answer": "No. Once charged, it blocks steady DC in the ideal model."}, "examTip": "After finding an equivalent resistance, redraw or relabel the original circuit before assigning individual voltage drops."}, "references": [{"title": "One time constant: the 63% and 37% rules", "why_it_matters": "Recognize how quickly a capacitor charges or discharges without deriving an exponential.", "formulas": ["\\(\\tau=RC\\)", "\\(1-e^{-1}\\approx0.632\\)", "\\(e^{-1}\\approx0.368\\)"], "method": ["Use an ideal series resistor-capacitor circuit with constant \\(R\\) and \\(C\\). The time constant \\(\\tau\\) is measured in seconds.", "Charging from zero: after one time constant, capacitor voltage and charge reach about 63% of their final values.", "Discharging: after one time constant, about 37% of the starting voltage and charge remain.", "A larger resistance or capacitance makes the change slower."], "check": {"question": "A capacitor charges from zero toward \\(10\\,\\mathrm V\\). Its time constant is \\(2\\,\\mathrm s\\). Estimate its voltage after \\(2\\,\\mathrm s\\).", "steps": ["The elapsed time is one time constant.", "Multiply final voltage by 0.632: \\(10\\times0.632=6.32\\,\\mathrm V\\)."], "answer": "About \\(6.3\\,\\mathrm V\\). It is not fully charged after one time constant."}, "sources": [{"title": "DC Circuits lecture, RC circuits", "url": "https://docs.google.com/presentation/d/1LsIlbPB-Zec0QCr0VaVEQ5WPNOpM2T7E/edit"}]}, {"title": "Kirchhoff signs and a real battery", "why_it_matters": "Choosing consistent signs is the main skill. A negative current answer tells you the actual direction.", "formulas": ["\\(\\text{current in}=\\text{current out}\\)", "\\(\\sum\\Delta V=0\\)", "\\(V_{\\rm terminal}=\\mathcal E-Ir\\quad\\text{(battery delivering current)}\\)"], "method": ["At a junction, charge does not keep building up: add entering and leaving currents separately.", "Choose a loop direction. Across a resistor, travelling with the assumed current gives \\(-IR\\); travelling against it gives \\(+IR\\).", "Across a battery, going from its negative to positive terminal gives \\(+\\mathcal E\\); the reverse gives \\(-\\mathcal E\\).", "For a battery supplying current, internal resistance \\(r\\) causes the terminal voltage to be less than its emf \\(\\mathcal E\\)."], "check": {"question": "A battery has emf \\(12\\,\\mathrm V\\) and internal resistance \\(1\\,\\Omega\\). It supplies a \\(5\\,\\Omega\\) resistor. Find current and terminal voltage.", "steps": ["Use one loop: \\(12-I(1)-I(5)=0\\).", "Total resistance is \\(6\\,\\Omega\\), so \\(I=12/6=2\\,\\mathrm A\\).", "Terminal voltage is \\(12-(2)(1)=10\\,\\mathrm V\\). Check the external resistor: \\(IR=(2)(5)=10\\,\\mathrm V\\)."], "answer": "Current \\(2\\,\\mathrm A\\); terminal voltage \\(10\\,\\mathrm V\\)."}, "sources": [{"title": "DC Circuits lecture, emf and Kirchhoff rules", "url": "https://docs.google.com/presentation/d/1LsIlbPB-Zec0QCr0VaVEQ5WPNOpM2T7E/edit"}]}]}, {"title": "Magnetic force: direction before calculation", "concept": "A magnetic field exerts force on a moving charge when its motion has a perpendicular component. The force is perpendicular to velocity and therefore does no work on a point charge. It can change direction without changing speed.", "formula": "F=|q|vB\\sin\\theta,\\quad F_{\\rm wire}=BIL\\sin\\theta", "steps": "Use the angle between velocity and field. Use the right-hand rule for a positive charge, then reverse for a negative one. State zero force for parallel motion.", "example": "A positive charge moving perpendicular to a uniform magnetic field follows a circular path if no other force acts. The field supplies the inward force.", "trap": "Do not apply the right-hand direction unchanged to an electron.", "q": "A charge moving parallel to a magnetic field experiences magnetic force:", "options": ["\\(qvB\\)", "Twice \\(qvB\\)", "Opposite its velocity", "Zero"], "answer": 3, "why": "The sine of the angle is zero.", "problem": "A straight 0.50 m wire carries 2 A perpendicular to a 0.30 T field. Find force magnitude.", "solution": "F = BIL = 0.30 times 2 times 0.50 = 0.30 N. Four marks for formula, perpendicular condition, substitution and unit.", "id": "electricity-9", "teaching": {"objectives": ["Determine when magnetic force vanishes or is largest.", "Explain circular motion without a change in kinetic energy."], "prerequisites": "Perpendicular directions; circular acceleration; charge sign.", "symbols": [{"symbol": "q", "meaning": "particle charge", "unit": "C"}, {"symbol": "v", "meaning": "particle speed", "unit": "m/s"}, {"symbol": "B", "meaning": "magnetic field magnitude", "unit": "T"}, {"symbol": "F", "meaning": "magnetic force magnitude", "unit": "N"}, {"symbol": "\\theta", "meaning": "angle between velocity and field", "unit": "degrees or radians"}], "method": ["Decide whether the object is a moving charge or a current-carrying wire.", "Identify the angle to the magnetic field and the perpendicular motion or wire length.", "Use the right-hand rule for positive charge or conventional current; reverse for negative charge.", "Calculate magnitude and check that the force is perpendicular to motion."], "worked": ["For the positive charge in the example, velocity is perpendicular to the uniform field, so the magnetic force magnitude is qvB.", "At each point the force is perpendicular to velocity and turns the particle inward.", "Because the force does no work, speed and kinetic energy remain constant.", "With no other forces, the continual turning gives a circular path in the plane perpendicular to the field."], "selfCheck": {"question": "Does a charge moving exactly along a magnetic field feel magnetic force?", "answer": "No. The angle is 0° or 180°, so its sine is zero."}, "examTip": "A direction answer needs the charge sign; a right-hand-rule result for a positive charge must be reversed for an electron."}, "references": []}, {"title": "Sources of magnetic fields", "concept": "Currents produce magnetic fields. Around a long straight wire the field forms circles. Inside an ideal long solenoid the field is approximately uniform. For two parallel wires, currents in the same direction attract and opposite currents repel.", "formula": "B_{\\rm wire}=\\mu_0 I/(2\\pi r),\\quad B_{\\rm solenoid}=\\mu_0 nI", "steps": "Identify the geometry first. Use a grip rule with the thumb along conventional current. In ratio questions compare current and distance instead of substituting constants.", "example": "Doubling distance from a long wire halves its magnetic field; doubling current doubles the field.", "trap": "The wire field varies as inverse distance, not inverse distance squared.", "q": "Two parallel wires carrying currents in the same direction:", "options": ["Repel", "Attract", "Have no interaction", "Must carry zero field"], "answer": 1, "why": "Each current experiences the magnetic field of the other wire.", "problem": "The field is 30 microtesla at 2 cm from a long straight wire. Find the field at 6 cm at the same current.", "solution": "B is inversely proportional to r, so B = 30 times 2/6 = 10 microtesla. Credit model, ratio, arithmetic and unit.", "id": "electricity-10", "teaching": {"objectives": ["Relate a current to the direction of the magnetic field it produces.", "Use simple distance and current ratios for a long wire."], "prerequisites": "Current; inverse proportionality; circular field-line diagrams.", "symbols": [{"symbol": "B", "meaning": "magnetic field magnitude", "unit": "T"}, {"symbol": "I", "meaning": "wire current", "unit": "A"}, {"symbol": "r", "meaning": "perpendicular distance from wire", "unit": "m"}, {"symbol": "n", "meaning": "solenoid turns per unit length", "unit": "m⁻¹"}], "method": ["Identify whether the source is a straight wire, a solenoid or a pair of wires.", "For a straight wire, use the right-hand grip rule to draw field circles.", "Apply the matching field relation; for ratios hold unstated factors fixed.", "For paired wires determine attraction or repulsion from relative current directions."], "worked": ["For the long wire, B is proportional to I/r.", "Moving from r to 2r at the same current gives half the original field.", "Doubling current at fixed r instead doubles the field.", "If current and distance both double, the two factors cancel and field magnitude stays the same."], "selfCheck": {"question": "A wire gives 30 µT at 2 cm. What field does it give at 6 cm with the same current?", "answer": "10 µT because distance triples."}, "examTip": "Use 1/r for the long-wire field; the 1/r² rule belongs to a different source geometry.", "assumptions": "The wire is sufficiently long and the observation point sufficiently far from its ends for the long-wire approximation."}, "references": []}, {"title": "Induction and Lenz law", "concept": "An induced emf requires a change in magnetic flux, which can arise from changing field, area or orientation. Lenz law sets the direction: the induced effect opposes the change of flux. A static magnet near a stationary loop does not produce a sustained induced current.", "formula": "|\\mathcal E|=N|\\Delta\\Phi_B|/\\Delta t,\\quad \\Phi_B=BA\\cos\\theta", "steps": "Describe whether flux into or out of the loop is increasing or decreasing. Choose the induced field that opposes that change. Only then infer the current direction.", "example": "If outward flux increases, the induced field points inward. The current must therefore circulate clockwise when viewed from that side.", "trap": "Opposes the change is not the same as always opposes the original field.", "q": "Which situation produces an induced emf?", "options": ["No change of area, field or angle", "Changing magnetic flux", "A stationary unchanging field only", "Constant flux"], "answer": 1, "why": "Faraday law depends on the rate of flux change.", "problem": "A 20-turn coil has flux per turn changing by 0.03 Wb in 0.10 s. Find average emf magnitude.", "solution": "Magnitude = 20 times 0.03/0.10 = 6 V. The direction needs the direction of the flux change; it cannot be inferred from these magnitudes alone.", "id": "electricity-11", "teaching": {"objectives": ["Identify which change produces an induced emf.", "Use Lenz law to choose the induced current direction."], "prerequisites": "Magnetic field direction; loop area; clockwise versus counterclockwise viewed from a stated side.", "symbols": [{"symbol": "\\Phi_B", "meaning": "magnetic flux through one turn", "unit": "Wb"}, {"symbol": "N", "meaning": "number of coil turns", "unit": "dimensionless"}, {"symbol": "\\mathcal E", "meaning": "induced emf", "unit": "V"}, {"symbol": "\\Delta t", "meaning": "time interval of flux change", "unit": "s"}], "method": ["State the original flux direction and whether its magnitude increases or decreases.", "Choose an induced field that opposes that change.", "Use the grip rule to convert the required field to current direction, naming the viewing side.", "For magnitude, multiply the flux change per turn by the number of turns and divide by elapsed time."], "worked": ["In the example, outward flux through the loop is increasing.", "The induced effect must oppose the increase, so its own field points inward.", "Viewed from the side toward which the original flux points outward, the inward field requires clockwise current.", "If the outward flux were decreasing instead, the induced field and current direction would both reverse."], "selfCheck": {"question": "Does a stationary loop near an unchanging stationary magnet have a sustained induced emf?", "answer": "No. Its magnetic flux is not changing."}, "examTip": "Say oppose the change in flux, not oppose the flux: a decreasing field produces a reinforcing induced field."}, "references": []}, {"title": "Inductance, AC and electromagnetic waves", "concept": "Course-plan extension: an inductor resists changes of current and stores magnetic energy. AC reverses direction periodically. RMS values describe equivalent heating for resistive loads. In vacuum an EM wave has mutually perpendicular electric field, magnetic field and travel direction.", "formula": "U_L=\\tfrac12LI^2,\\quad V_{\\rm rms}=V_{\\rm peak}/\\sqrt2\\ \\text{(sinusoidal)},\\quad c=f\\lambda\\ \\text{(vacuum)}", "steps": "Distinguish peak from RMS before calculating power. For EM waves use frequency and wavelength in compatible units. Recognize that ideal transformers require changing magnetic flux.", "example": "A sinusoidal supply with peak voltage 141.4 V has RMS voltage 100 V. Light of frequency \\(6\\times10^{14}\\,\\mathrm{Hz}\\) has vacuum wavelength 500 nm.", "trap": "An ideal transformer does not continuously transform steady DC after switching transients.", "q": "In vacuum, electric and magnetic fields of a plane EM wave are:", "options": ["Parallel to each other", "Longitudinal only", "Zero", "Perpendicular to each other and to travel"], "answer": 3, "why": "A plane electromagnetic wave in vacuum is transverse.", "problem": "A sinusoidal voltage has peak value 20 V. Find its RMS value, then the average power in a 10 \\(\\Omega\\) resistor.", "solution": "RMS = 20/square root of 2 = 14.14 V. Average power = RMS squared/10 = 20 W. Two marks per stage.", "id": "electricity-12", "teaching": {"objectives": ["Convert sinusoidal peak voltage to RMS and calculate resistive heating.", "Relate electromagnetic frequency to vacuum wavelength."], "prerequisites": "Square roots; frequency and wavelength; electrical power.", "symbols": [{"symbol": "V_{\\rm peak}", "meaning": "maximum sinusoidal voltage magnitude", "unit": "V"}, {"symbol": "V_{\\rm rms}", "meaning": "root-mean-square voltage", "unit": "V"}, {"symbol": "L", "meaning": "inductance", "unit": "H"}, {"symbol": "f", "meaning": "wave frequency", "unit": "Hz"}, {"symbol": "\\lambda", "meaning": "wavelength", "unit": "m"}], "method": ["Identify whether the question concerns an inductor, sinusoidal AC or an electromagnetic wave.", "For sinusoidal AC divide peak voltage by the square root of two.", "Use RMS values for average power in a pure resistor.", "For vacuum waves calculate wavelength as c divided by frequency and convert metres to the requested unit."], "worked": ["For the stated sinusoidal supply, 141.4 divided by √2 is approximately 100 V RMS.", "This RMS value matches the heating effect of 100 V DC in the same pure resistor.", "For the separate light example, wavelength is 3.00 × 10⁸ divided by 6 × 10¹⁴ = 5 × 10⁻⁷ m.", "Since one nanometre is 10⁻⁹ m, the wavelength is 500 nm."], "selfCheck": {"question": "A 20 V peak sinusoid is applied to 10 Ω. What is the average power?", "answer": "20 W: Vrms²/R = (20²/2)/10."}, "examTip": "Keep this extension conceptual: use RMS for resistor power and c = fλ for waves; do not mix peak and RMS values.", "assumptions": "The peak-to-RMS conversion assumes a sinusoid; the wavelength calculation assumes propagation in vacuum."}, "references": []}], "tests": [{"name": "A", "indices": [0, 1, 2, 3, 4, 5]}, {"name": "B", "indices": [6, 7, 8, 9, 10, 11]}], "figure": {"src": "assets/electricity.svg", "lessonId": "electricity-2", "caption": "At this midpoint, the net field and force on any test charge are zero. Where the net field is nonzero, a negative test charge feels force opposite to it."}}, {"slug": "optics", "title": "Optics and Waves", "scope": "The introduction and four current sections: wave motion; electromagnetic theory, photons and light; geometrical optics; physical optics. Derivations are replaced by plain-language interpretation and short exam calculations.", "source": "1yTommxUFsTybKw7Q1JNYA_Mg0LiViZ3M", "lessons": [{"title": "Wave language and simple harmonic motion", "concept": "A wave carries a disturbance and energy. Mechanical waves need a medium; electromagnetic waves can travel through vacuum. Transverse displacement is perpendicular to travel; longitudinal displacement is parallel. Simple harmonic motion has a restoring acceleration proportional and opposite to displacement.", "formula": "T=1/f,\\quad f=N/t,\\quad a=-\\omega^2x", "steps": "Count complete cycles, not half-swings. Divide total time by cycles for period. Recognize that SHM acceleration points toward equilibrium and speed is largest there.", "example": "If 20 oscillations take 5 s, frequency is 4 Hz and period is 0.25 s. At an extreme of SHM, speed is zero and acceleration magnitude is maximum.", "trap": "The direction of particle motion is not necessarily the direction of wave travel.", "q": "Which wave can propagate through vacuum?", "options": ["A water wave", "Light", "A stretched-string wave", "Sound in air"], "answer": 1, "why": "Light is electromagnetic and does not require a material medium.", "problem": "A source makes 50 complete oscillations in 10 s. Find frequency and period.", "solution": "Frequency = 50/10 = 5 Hz. Period = 1\\(\\frac05\\)0 = 0.20 s. Two marks each.", "id": "optics-1", "teaching": {"objectives": ["Convert an oscillation count into frequency and period.", "Relate displacement, speed and acceleration at key SHM positions."], "prerequisites": "One oscillation is one complete cycle; reciprocal quantities; displacement from equilibrium.", "symbols": [{"symbol": "N", "meaning": "number of complete cycles", "unit": "dimensionless"}, {"symbol": "t", "meaning": "total elapsed time", "unit": "s"}, {"symbol": "f", "meaning": "cycles per second", "unit": "Hz"}, {"symbol": "T", "meaning": "time for one cycle", "unit": "s"}, {"symbol": "\\omega", "meaning": "angular frequency", "unit": "rad/s"}], "method": ["Count complete cycles rather than individual crossings of equilibrium.", "Divide cycle count by total time for frequency.", "Find period as total time per cycle or the reciprocal of frequency.", "For SHM compare the point with equilibrium and use restoring acceleration toward equilibrium."], "worked": ["Twenty complete oscillations in 5 s means 20/5 = 4 cycles per second, so f = 4 Hz.", "One cycle takes 5/20 = 0.25 s, giving T = 0.25 s.", "At an extreme the object must turn around, so its instantaneous speed is zero.", "Its displacement magnitude is largest there; restoring acceleration therefore has maximum magnitude and points toward equilibrium."], "selfCheck": {"question": "At SHM equilibrium is acceleration magnitude maximum?", "answer": "No. Displacement and restoring acceleration are zero; speed is maximum."}, "examTip": "Write f = N/t and T = t/N side by side to prevent interchanging hertz and seconds."}, "references": []}, {"title": "Read a travelling wave without deriving it", "concept": "Amplitude is maximum displacement, wavelength is crest-to-crest separation, and frequency counts cycles per second. Wave speed is the speed of the pattern, not the oscillating particle. In a sine wave, the coefficients of position and time reveal wavelength and period.", "formula": "v=f\\lambda,\\quad k=2\\pi/\\lambda,\\quad \\omega=2\\pi f,\\quad y=A\\sin(kx-\\omega t+\\phi)", "steps": "Read A, k and omega directly. A minus between kx and omega t means travel in positive x for this convention. Obtain speed from omega/k or frequency times wavelength.", "example": "For \\(y=0.02\\sin(4\\pi x-20\\pi t)\\), amplitude is 0.02 m, wavelength is 0.50 m, frequency is 10 Hz and speed is 5 m/s.", "trap": "The coefficient of time is angular frequency, not ordinary frequency.", "q": "With wave speed fixed, doubling frequency makes wavelength:", "options": ["Half as large", "Unchanged", "Four times as large", "Twice as large"], "answer": 0, "why": "Wavelength equals speed divided by frequency.", "problem": "A wave has frequency 8 Hz and wavelength 0.75 m. Find speed. If frequency becomes 12 Hz in the same nondispersive medium, find wavelength.", "solution": "Speed = 8 times 0.75 = 6 m/s. New wavelength = 6/12 = 0.50 m. Two marks each.", "id": "optics-2", "teaching": {"objectives": ["Read amplitude, wavelength and frequency from a travelling-wave expression.", "Use v = fλ and distinguish pattern motion from particle motion."], "prerequisites": "Sine-wave shape; π; coefficients of x and t; SI units.", "symbols": [{"symbol": "A", "meaning": "amplitude or maximum displacement", "unit": "m"}, {"symbol": "k", "meaning": "wave number", "unit": "rad/m"}, {"symbol": "\\omega", "meaning": "angular frequency", "unit": "rad/s"}, {"symbol": "\\lambda", "meaning": "wavelength", "unit": "m"}, {"symbol": "f", "meaning": "frequency", "unit": "Hz"}], "method": ["Match the wave to y = A sin(kx - ωt + φ).", "Read A directly, then divide 2π by k to obtain wavelength.", "Divide ω by 2π to obtain frequency.", "Multiply frequency by wavelength for pattern speed and check the units."], "worked": ["Compare y = 0.02 sin(4πx - 20πt) with the standard form: A = 0.02 m, k = 4π rad/m and ω = 20π rad/s.", "Wavelength is 2π/(4π) = 0.50 m.", "Frequency is 20π/(2π) = 10 Hz.", "Pattern speed is 10 times 0.50 = 5 m/s; this is not the maximum transverse speed of an individual particle."], "selfCheck": {"question": "Is the coefficient 20π in the example the frequency in hertz?", "answer": "No. It is angular frequency; divide it by 2π to get 10 Hz."}, "examTip": "Identify coefficients before calculating; treating k as wavelength or ω as ordinary frequency loses the factor 2π.", "assumptions": "The example takes x and y in metres and t in seconds."}, "references": [{"title": "Phase means position within a cycle", "why_it_matters": "A phase difference tells whether two oscillations are at the same or different stages of a cycle.", "formulas": ["\\(\\Delta\\phi=2\\pi\\dfrac{\\Delta x}{\\lambda}\\quad\\text{(phase-difference magnitude at one time)}\\)", "\\(\\Delta\\phi=2\\pi\\dfrac{\\Delta t}{T}\\quad\\text{(phase-change magnitude at one place)}\\)"], "method": ["One full cycle is \\(2\\pi\\) radians. Half a cycle is \\(\\pi\\) radians.", "At a fixed time, points one wavelength apart are in phase. Points half a wavelength apart are opposite in phase.", "At one place, a full period brings the oscillation back to the same phase.", "These formulas give the size of the phase difference. Its sign depends on the order of comparison and the travelling-wave convention."], "check": {"question": "Two points on a sinusoidal wave are separated by \\(\\lambda/4\\). Find their phase-difference magnitude at the same time.", "steps": ["The separation is one quarter of a full spatial cycle.", "Therefore \\(\\Delta\\phi=2\\pi\\times(1/4)=\\pi/2\\)."], "answer": "\\(\\pi/2\\) radians, or \\(90^\\circ\\). They are neither in phase nor exactly opposite in phase."}, "sources": [{"title": "Optics Section 1, phase and path difference", "url": "https://docs.google.com/presentation/d/1agE3nN_N1rOYxoZ8fKSbgwdTCRxzk7lw/edit"}]}]}, {"title": "Wavefronts, spreading and group velocity", "concept": "A ray indicates propagation direction and is normal to a wavefront. Plane wavefronts are flat, spherical wavefronts spread from a point source, and cylindrical wavefronts spread around a line source. Phase velocity tracks a crest; group velocity tracks the envelope of a narrow wave packet.", "formula": "I\\propto A^2,\\qquad I_{\\rm spherical}\\propto 1/r^2", "steps": "Recognize the source geometry. For spreading comparisons state that absorption is ignored. For wave packets distinguish motion of crests from motion of the envelope.", "example": "For an isotropic point source without absorption, doubling distance reduces intensity to one quarter and amplitude to one half.", "trap": "The ideal plane-wave model does not have spherical inverse-square spreading.", "q": "Group velocity describes the motion of:", "options": ["The wave-packet envelope", "The source itself", "One particle only", "A stationary node"], "answer": 0, "why": "The group is the envelope formed by combining nearby frequencies.", "problem": "At distance r an isotropic source has intensity 18 W per square metre. Find intensity at 3r, ignoring absorption.", "solution": "Inverse-square spreading gives 18/9 = 2 W per square metre. The distance triples, so the area over which power spreads increases ninefold.", "id": "optics-3", "teaching": {"objectives": ["Predict intensity and amplitude changes for spherical spreading.", "Distinguish wavefront, ray, phase velocity and group velocity."], "prerequisites": "Surface area grows with radius squared; square roots; amplitude versus intensity.", "symbols": [{"symbol": "I", "meaning": "energy-transfer rate per unit area", "unit": "W/m²"}, {"symbol": "A", "meaning": "wave amplitude", "unit": "depends on disturbance"}, {"symbol": "r", "meaning": "distance from point source", "unit": "m"}], "method": ["Identify whether the source produces plane, spherical or cylindrical spreading.", "For an isotropic point source use intensity proportional to 1/r².", "Convert an intensity ratio to an amplitude ratio by taking its square root.", "In description questions, identify a crest for phase velocity and the packet envelope for group velocity."], "worked": ["The same source power crosses a sphere around the source at each distance.", "Doubling radius makes the sphere area four times as large.", "The available power per square metre is therefore one quarter as large.", "Because intensity is proportional to amplitude squared, the amplitude ratio is √(1/4) = 1/2."], "selfCheck": {"question": "An intensity of 18 W/m² is measured at r. What is it at 3r?", "answer": "2 W/m²: divide by 3² = 9."}, "examTip": "Do not apply the inverse-square intensity rule automatically to a plane wave or line source.", "assumptions": "The spreading example assumes an isotropic point source, no absorption and unchanged medium properties."}, "references": []}, {"title": "Superposition, standing waves and beats", "concept": "Overlapping disturbances add algebraically. In-phase equal waves reinforce; opposite-phase equal waves cancel. A standing wave forms when matching waves travel in opposite directions. Nodes stay at zero displacement. Beats are slow changes in loudness from nearby frequencies.", "formula": "f_{\\rm beat}=|f_1-f_2|,\\quad \\lambda_n=2L/n\\ \\text{(string fixed at both ends)}", "steps": "Check phase before adding amplitudes. For standing waves sketch the fixed-end nodes and count half-wavelengths. For beats take the positive frequency difference.", "example": "Two tones at 256 and 260 Hz produce 4 beats per second. A fixed string in its fundamental mode contains one half-wavelength.", "trap": "A node is not a point where two travelling waves are individually absent.", "q": "Two tones at 440 and 443 Hz produce a beat frequency of:", "options": ["1320 Hz", "883 Hz", "3 Hz", "441.5 Hz"], "answer": 2, "why": "Beat frequency is the absolute difference.", "problem": "A 1 m string fixed at both ends supports waves at 40 m/s. Find its fundamental frequency and second harmonic.", "solution": "Fundamental wavelength = 2 m; frequency = 40/2 = 20 Hz. Second harmonic = 40 Hz. Two marks per frequency with reasoning.", "id": "optics-4", "teaching": {"objectives": ["Calculate beat frequency from two nearby frequencies.", "Connect fixed-string harmonics with allowed wavelengths."], "prerequisites": "Adding displacements; wavelength; frequency; fixed endpoints.", "symbols": [{"symbol": "f_{\\rm beat}", "meaning": "number of loudness cycles per second", "unit": "Hz"}, {"symbol": "L", "meaning": "vibrating string length", "unit": "m"}, {"symbol": "n", "meaning": "harmonic number, 1, 2, 3, …", "unit": "dimensionless"}, {"symbol": "\\lambda_n", "meaning": "wavelength of harmonic n", "unit": "m"}], "method": ["For superposition add instantaneous signed displacements at the same point.", "For beats take the positive difference of the two nearby frequencies.", "For a string fixed at both ends draw nodes at both ends.", "Fit n half-wavelengths into the length, then use wave speed to find each frequency."], "worked": ["The tones have frequencies 256 Hz and 260 Hz.", "Their frequency difference is 4 Hz, so there are four loudness beats each second.", "For the separate string example, the fundamental has one loop between two end nodes.", "That loop occupies half a wavelength, so λ1 = 2L and f1 = v/(2L)."], "selfCheck": {"question": "For a fixed string, how does the second-harmonic frequency compare with the fundamental?", "answer": "It is twice the fundamental frequency in the ideal uniform-string model."}, "examTip": "A beat frequency is a difference, not the average of the two tone frequencies."}, "references": []}, {"title": "Light, photons and the electromagnetic picture", "concept": "Light behaves as an electromagnetic wave in propagation and exchanges energy in photons. Photon energy increases with frequency. In the photoelectric effect, emission requires enough energy per photon; increasing brightness alone cannot overcome a frequency below threshold.", "formula": "E_\\gamma=hf=hc/\\lambda_0,\\quad \\lambda_0=\\text{vacuum wavelength},\\quad c=3.00\\times10^8\\ {\\rm m/s}", "steps": "Use frequency to compare photon energies. Use intensity to compare photon numbers only when photon frequency is held fixed. Keep the wave and photon descriptions tied to the phenomenon.", "example": "Blue light has shorter wavelength than red light and therefore higher photon energy. A brighter red beam need not have more energetic photons.", "trap": "Higher intensity does not mean higher energy per photon. In E = hc/lambda, use the vacuum wavelength. At an ordinary stationary boundary, frequency and photon energy stay the same even though wavelength in the medium changes.", "q": "At the same medium, which has greater photon energy?", "options": ["Lower-frequency light", "Both always equal", "Higher-frequency light", "Longer-wavelength light"], "answer": 2, "why": "Photon energy is proportional to frequency.", "problem": "Light A has twice the frequency of light B. Compare photon energy and vacuum wavelength.", "solution": "A has twice the photon energy and half the vacuum wavelength. Two marks for each relationship.", "id": "optics-5", "teaching": {"objectives": ["Compare photon energy using frequency or vacuum wavelength.", "Distinguish beam brightness from energy per photon."], "prerequisites": "Direct and inverse proportionality; wave frequency; energy transfer.", "symbols": [{"symbol": "E_\\gamma", "meaning": "energy of one photon", "unit": "J"}, {"symbol": "h", "meaning": "Planck constant", "unit": "J s"}, {"symbol": "f", "meaning": "light frequency", "unit": "Hz"}, {"symbol": "\\lambda", "meaning": "vacuum wavelength", "unit": "m"}], "method": ["Decide whether the question asks about one photon or the whole beam.", "Use Eγ proportional to frequency, or inversely proportional to vacuum wavelength.", "For brightness comparisons separate photon energy from the number arriving each second.", "For photoelectric emission compare energy per photon with the threshold requirement."], "worked": ["Blue light has a shorter vacuum wavelength than red light.", "Since Eγ = hc/λ, the smaller wavelength corresponds to a larger energy per photon.", "Increasing red-beam brightness at the same colour increases the energy arriving per second, usually through more photons.", "Each red photon still has the same lower energy; brightness alone does not change its frequency."], "selfCheck": {"question": "If light A has twice light B frequency, how do photon energy and vacuum wavelength compare?", "answer": "A has twice the photon energy and half the vacuum wavelength."}, "examTip": "Use the phrase energy per photon when discussing threshold effects; total beam energy does not answer the same question."}, "references": []}, {"title": "Reflection, refraction and total internal reflection", "concept": "Angles of incidence, reflection and refraction are measured from the normal. At a stationary interface frequency stays the same, while speed and wavelength may change. When light enters a higher refractive index at a nonzero angle, the ray bends toward the normal. Total internal reflection needs travel from higher to lower index and an incidence angle greater than the critical angle.", "formula": "\\theta_i=\\theta_r,\\quad n=c/v,\\quad n_1\\sin\\theta_1=n_2\\sin\\theta_2,\\quad \\sin\\theta_c=n_2/n_1", "steps": "Draw the normal. Label the two media. Check the direction of bending before calculation. Use the critical-angle expression only when n1 exceeds n2.", "example": "From air into glass with index 1.5, light slows to \\(2\\times10^8\\,\\mathrm{m/s}\\). Its frequency stays fixed and its wavelength decreases.", "trap": "The critical angle is an incidence angle in the higher-index medium.", "q": "Light enters glass from air. Which quantity remains unchanged?", "options": ["Ray direction in every case", "Speed", "Wavelength", "Frequency"], "answer": 3, "why": "The boundary does not change the frequency of the incident oscillation.", "problem": "Find the critical angle for glass of index 1.5 into air of index 1.0.", "solution": "Sine of critical angle = \\(\\frac11\\).5 = 0.6667, so critical angle = 41.8 degrees. Total internal reflection occurs above this angle. Credit condition, equation, value and interpretation.", "id": "optics-6", "teaching": {"objectives": ["Track speed, frequency and wavelength across a refracting boundary.", "Recognize the two conditions for total internal reflection."], "prerequisites": "Normal to a surface; sine; reciprocal refractive index.", "symbols": [{"symbol": "n", "meaning": "refractive index", "unit": "dimensionless"}, {"symbol": "c", "meaning": "vacuum light speed", "unit": "m/s"}, {"symbol": "v", "meaning": "light speed in medium", "unit": "m/s"}, {"symbol": "\\theta_c", "meaning": "critical incidence angle", "unit": "degrees or radians"}], "method": ["Draw the surface normal and measure all ray angles from it.", "Use v = c/n to compare speeds; frequency stays fixed at a stationary boundary.", "Use wavelength = speed/frequency to compare wavelengths.", "For total internal reflection check higher-to-lower index travel, then compare incidence with the critical angle."], "worked": ["Air is approximated by n = 1 and glass has n = 1.5.", "In glass, speed is 3.00 × 10⁸/1.5 = 2.00 × 10⁸ m/s.", "The frequency is set by the source and remains the same across the boundary.", "Because speed drops while frequency stays fixed, wavelength in glass is two thirds of its air value."], "selfCheck": {"question": "Can light travelling from air into glass undergo total internal reflection at that interface?", "answer": "No. Total internal reflection requires travel from higher to lower refractive index."}, "examTip": "At the critical angle the refracted ray runs along the boundary; total internal reflection occurs above that angle.", "assumptions": "The boundary is stationary and the media are treated as uniform; air index is approximated as 1."}, "references": []}, {"title": "Mirrors, lenses and image signs", "concept": "A real image is formed where rays actually meet and can be projected on a screen. A virtual image is where rays appear to originate. Use one sign convention consistently: real object distance positive, real image distance positive; converging focal length positive and diverging focal length negative.", "formula": "1/f=1/d_o+1/d_i,\\qquad m=-d_i/d_o", "steps": "Sketch the principal rays first. Solve for image distance, then magnification. A negative image distance means virtual under this convention; negative magnification means inverted. Translate signs if your lecturer uses a different convention. Use the equation for an ideal thin lens or a spherical mirror with rays close to the principal axis. For mirrors, f = R/2 in this approximation; concave mirrors converge and convex mirrors diverge.", "example": "For a converging lens with focal length 10 cm and object distance 30 cm, image distance is 15 cm and magnification is -0.5: real, inverted, reduced.", "trap": "Do not call every image behind a lens virtual; interpret actual ray convergence and your convention.", "q": "An image with magnification -2 is:", "options": ["Upright and smaller", "Inverted and twice as tall", "Virtual in every case", "Upright and twice as tall"], "answer": 1, "why": "The minus sign indicates inversion and magnitude 2 gives the size ratio.", "problem": "A converging lens has focal length 12 cm and an object at 24 cm. Find image distance, magnification and image type.", "solution": "1/di = \\(\\frac11\\)2 - 1/24 = 1/24, so di = 24 cm. m = -1. Image is real, inverted and equal size. One mark each for distance, magnification, real and inverted/equal size.", "id": "optics-7", "teaching": {"objectives": ["Use the stated image-distance sign convention consistently.", "Infer image reality, orientation and relative size from di and m."], "prerequisites": "Reciprocals; positive and negative numbers; a simple ray sketch.", "symbols": [{"symbol": "f", "meaning": "signed focal length", "unit": "cm or m consistently"}, {"symbol": "d_o", "meaning": "object distance", "unit": "same length unit as f"}, {"symbol": "d_i", "meaning": "signed image distance", "unit": "same length unit as f"}, {"symbol": "m", "meaning": "transverse magnification", "unit": "dimensionless"}], "method": ["Write the sign convention and assign f and do before substitution.", "Rearrange the lens equation to isolate 1/di and then invert.", "Calculate m = -di/do.", "Use di sign for real or virtual, m sign for orientation, and magnitude of m for size."], "worked": ["A converging lens has f = +10 cm and the real object has do = +30 cm.", "Then 1/di = 1/10 - 1/30 = 1/15 per cm, so di = +15 cm.", "Magnification is -15/30 = -0.5.", "Positive image distance means real; negative magnification means inverted; magnitude 0.5 means half the object height."], "selfCheck": {"question": "What does m = +2 tell you about an image?", "answer": "It is upright and twice the object height; the sign convention and lens setup determine its image position."}, "examTip": "After subtraction, invert 1/di to get di; include all three requested image descriptions.", "assumptions": "Use the lesson convention: real object and real image distances positive; converging focal length positive."}, "references": []}, {"title": "Optical systems, prisms and instruments", "concept": "A prism refracts light at two surfaces; dispersion separates colours because refractive index depends on wavelength. In a multi-lens system, the first image becomes the object for the next lens. A microscope and a telescope both use an objective and eyepiece, but they serve different object distances.", "formula": "m_{\\rm total}=m_1m_2,\\qquad |M_{\\rm telescope}|=f_o/f_e\\ \\text{(normal adjustment)}", "steps": "Draw intermediate images in order and measure the next object distance from the next lens. For a basic telescope ratio, identify the long-focus objective and short-focus eyepiece.", "example": "An astronomical telescope with objective focal length 80 cm and eyepiece 4 cm has angular magnification magnitude 20. Its normal image is inverted.", "trap": "Linear image magnification and angular magnification are different quantities.", "q": "In a simple astronomical telescope, the objective usually has:", "options": ["A longer focal length than the eyepiece", "Zero focal length", "The same role as a polarizer", "No effect on the image"], "answer": 0, "why": "The long-focus objective and short-focus eyepiece give a large angular-magnification ratio.", "problem": "A telescope objective has focal length 100 cm and eyepiece 5 cm. Find angular magnification magnitude. What happens if the eyepiece is replaced by 10 cm?", "solution": "Initial magnitude = 10\\(\\frac05\\) = 20. New magnitude = 100/10 = 10. Doubling eyepiece focal length halves angular magnification.", "id": "optics-8", "teaching": {"objectives": ["Explain the different roles of objective and eyepiece.", "Calculate telescope angular magnification for normal adjustment."], "prerequisites": "Focal length; image formation; ratios of lengths.", "symbols": [{"symbol": "f_o", "meaning": "objective focal length", "unit": "cm or m consistently"}, {"symbol": "f_e", "meaning": "eyepiece focal length", "unit": "same length unit as fo"}, {"symbol": "M", "meaning": "angular magnification", "unit": "dimensionless"}, {"symbol": "m_1,m_2", "meaning": "transverse magnifications of successive stages", "unit": "dimensionless"}], "method": ["Identify the instrument and whether it views a distant or nearby object.", "For a normal-adjustment astronomical telescope divide objective focal length by eyepiece focal length for magnification magnitude.", "State image orientation separately.", "For a general multi-lens system locate the first image before using it as the next object."], "worked": ["The telescope objective focal length is 80 cm and the eyepiece focal length is 4 cm.", "Their ratio is 80/4 = 20, so the angular magnification magnitude is 20.", "An astronomical telescope with this usual two-converging-lens arrangement gives an inverted image.", "The ratio needs no length conversion because both focal lengths use the same unit."], "selfCheck": {"question": "Keeping the objective fixed, does doubling the eyepiece focal length increase or decrease telescope magnification?", "answer": "It halves the magnification magnitude."}, "examTip": "Use the telescope focal-length ratio only for the stated telescope model, not as a universal magnification formula.", "assumptions": "The telescope is in normal adjustment, giving the final image at infinity."}, "references": []}, {"title": "Interference and diffraction", "concept": "Interference occurs when overlapping waves combine. A stable visible pattern needs a fixed phase relationship (coherence). Diffraction is spreading associated with an opening or obstacle. Narrower slits spread light more. Young double-slit bright fringes are evenly spaced when the angles are small.", "formula": "\\Delta y=\\lambda L/d,\\quad d\\sin\\theta=m\\lambda\\ \\text{(double-slit bright)},\\quad a\\sin\\theta=m\\lambda\\ \\text{(single-slit dark, }m\\ne0\\text{)}", "steps": "First identify double-slit bright fringes or single-slit dark minima. Use the correct aperture dimension. Predict the trend before inserting numbers.", "example": "Doubling screen distance doubles double-slit fringe spacing. Halving a single-slit width broadens its central diffraction maximum.", "trap": "The double-slit bright condition is not the single-slit bright condition.", "q": "If double-slit separation increases while wavelength and screen distance stay fixed, fringe spacing:", "options": ["Becomes negative", "Increases", "Stays fixed", "Decreases"], "answer": 3, "why": "Fringe spacing is inversely proportional to slit separation.", "problem": "In a double-slit experiment, wavelength is 500 nm, screen distance 2 m and slit separation 0.50 mm. Find fringe spacing.", "solution": "Convert wavelength to 0.0000005 m and separation to 0.0005 m. Spacing = (0.0000005 times 2)/0.0005 = 0.002 m = 2 mm. Credit both conversions, calculation and result.", "id": "optics-9", "teaching": {"objectives": ["Predict how slit geometry changes an interference or diffraction pattern.", "Distinguish double-slit bright fringes from single-slit dark fringes."], "prerequisites": "Wavelength; coherent sources; nanometres and millimetres; small angles.", "symbols": [{"symbol": "\\Delta y", "meaning": "double-slit fringe spacing", "unit": "m"}, {"symbol": "L", "meaning": "slit-to-screen distance", "unit": "m"}, {"symbol": "d", "meaning": "separation of double slits", "unit": "m"}, {"symbol": "a", "meaning": "single-slit width", "unit": "m"}, {"symbol": "\\lambda", "meaning": "wavelength", "unit": "m"}], "method": ["Identify whether the setup is double-slit interference or single-slit diffraction.", "Label d as slit separation and a as slit width; they describe different distances.", "For double-slit spacing use λL/d with all lengths in consistent units.", "For a single slit remember that a smaller width moves the first minima outward and broadens the centre."], "worked": ["Double-slit spacing is proportional to screen distance when wavelength and slit separation stay fixed.", "Replacing L by 2L therefore doubles fringe spacing.", "In the separate single-slit comparison, the first dark direction obeys sin θ = λ/a.", "Halving a makes that angle larger, so the bright central maximum broadens."], "selfCheck": {"question": "If double-slit separation doubles with screen distance and wavelength fixed, what happens to fringe spacing?", "answer": "It halves."}, "examTip": "Label whether you are locating a bright double-slit fringe or a dark single-slit fringe before using the order number.", "assumptions": "Even double-slit spacing uses the small-angle, distant-screen approximation and coherent illumination."}, "references": [{"title": "Recognize gratings, Michelson paths and thin films", "why_it_matters": "All three appear in the physical-optics section. Start by identifying which arrangement the question describes.", "formulas": ["\\(\\Delta\\text{path}=2\\Delta x\\quad\\text{(one Michelson mirror moves)}\\)"], "method": ["A diffraction grating has many equally spaced slits. It makes sharp bright directions that separate wavelengths.", "A Michelson interferometer splits light into two arms. Each beam travels to a mirror and back, so mirror movement changes a round-trip path.", "A thin film produces interference between reflections from its two surfaces. Reflection can add a phase reversal, so do not copy the ordinary double-slit bright rule.", "For fringe counting in a simple Michelson setup, each one-wavelength change in path difference shifts the pattern by one fringe."], "check": {"question": "In a Michelson interferometer using \\(500\\,\\mathrm{nm}\\) light in air, one mirror moves \\(250\\,\\mathrm{nm}\\) along its arm. What path change and fringe shift result?", "steps": ["Round-trip path change: \\(2\\times250=500\\,\\mathrm{nm}\\).", "This equals one wavelength."], "answer": "The path changes by \\(500\\,\\mathrm{nm}\\), so one fringe passes a fixed observation point."}, "sources": [{"title": "Optics Section 4, Michelson, dielectric films and grating", "url": "https://docs.google.com/presentation/d/1NbQWErhV2PZA9mdDPqFDCyGcJ40iQghW/edit"}]}]}, {"title": "Polarization and Malus law", "concept": "Polarization describes the electric-field direction of a transverse light wave. An ideal polarizer transmits half the intensity of unpolarized light. An analyzer then transmits a fraction set by the angle between its axis and the incident polarization. Linear, circular and elliptical polarization describe different field-tip motions.", "formula": "I=I_0\\cos^2\\theta,\\qquad I_{\\rm after\\ first}=I_{\\rm unpolarized}/2", "steps": "Decide whether the entering light is unpolarized or already linearly polarized. Apply the half-intensity rule only for the first ideal polarizer on unpolarized light. Then apply Malus law between axes.", "example": "Unpolarized intensity 100 units passes a polarizer then an analyzer at 60 degrees. After the first: 50; after the second: 50 times 0.25 = 12.5 units.", "trap": "Do not halve already polarized intensity again before applying Malus law.", "q": "Two ideal crossed polarizers transmit from an initially unpolarized beam:", "options": ["One quarter", "Zero", "All its intensity", "Half"], "answer": 1, "why": "Their axes differ by 90 degrees and \\(\\cos^2 90^\\circ\\) is zero.", "problem": "Unpolarized intensity 80 W per square metre passes through a polarizer and an analyzer at 45 degrees. Find the final intensity.", "solution": "First polarizer gives 40. Analyzer gives 40 times cosine squared 45 degrees = 20 W per square metre. Two marks for each stage.", "id": "optics-10", "teaching": {"objectives": ["Apply the initial half-intensity rule to unpolarized light.", "Apply Malus law using the angle between polarization and analyzer axes."], "prerequisites": "Cosine of common angles; intensity versus field amplitude; sequential fractions.", "symbols": [{"symbol": "I_0", "meaning": "intensity incident on the analyzer", "unit": "W/m² or stated units"}, {"symbol": "I", "meaning": "intensity transmitted by analyzer", "unit": "same as I0"}, {"symbol": "\\theta", "meaning": "angle between incident polarization and analyzer axis", "unit": "degrees or radians"}], "method": ["Check whether the first incident beam is unpolarized or already linearly polarized.", "For unpolarized light through an ideal first polarizer divide intensity by two.", "Use that transmitted intensity as I0 for the analyzer.", "Multiply by cos² θ, where θ is between the two relevant axes."], "worked": ["The initial 100 intensity units are unpolarized, so the first ideal polarizer transmits 50 units.", "The analyzer axis is at 60° to the first polarizer axis.", "Cos 60° is 0.5 and its square is 0.25.", "The analyzer therefore transmits 50 times 0.25 = 12.5 units, one eighth of the original intensity."], "selfCheck": {"question": "Two ideal polarizers have perpendicular axes. What does the second transmit from the first?", "answer": "Zero intensity in the ideal model, because cos² 90° = 0."}, "examTip": "Square the cosine, not the angle; and do not apply an extra half factor to an already polarized analyzer input.", "assumptions": "The calculation assumes ideal polarizers and initially unpolarized illumination."}, "references": []}, {"title": "Scattering, apparent depth and lens power", "concept": "Small particles compared with wavelength produce Rayleigh scattering, which favours shorter wavelengths strongly. Droplets comparable to or larger than visible wavelengths can scatter a broad range of colours, helping explain white clouds. Refraction makes a submerged object appear shallower when viewed near the normal from air.", "formula": "I_{\\rm Rayleigh}\\propto1/\\lambda^4,\\quad d_{\\rm apparent}\\approx d_{\\rm real}/n,\\quad P_{\\rm lens}=1/f\\ \\text{(f in metres)}", "steps": "Distinguish scattering from refraction. Use apparent-depth formulas only in their near-normal, flat-interface model. Convert lens focal length to metres before calculating dioptres.", "example": "A pool 2 m deep in water of index 1.33 appears about 1.50 m deep from air near the normal. A converging lens with f=0.25 m has power +4 dioptres.", "trap": "A focal length of 25 cm is not 25 m; using it directly gives the wrong lens power.", "q": "The unit of optical lens power is:", "options": ["Hertz", "Watt", "Dioptre", "Newton"], "answer": 2, "why": "Lens power is inverse focal length in metres, expressed in dioptres.", "problem": "A diverging lens has focal length -50 cm. Find its optical power.", "solution": "Convert to -0.50 m. Power=1/(-0.50)=-2 dioptres. Credit conversion, formula, sign and unit.", "id": "optics-11", "teaching": {"objectives": ["Calculate apparent depth near normal viewing and signed lens power.", "Explain why small-particle scattering favours shorter wavelengths."], "prerequisites": "Refraction; inverse relationships; centimetres-to-metres conversion.", "symbols": [{"symbol": "d_{\\rm real}", "meaning": "actual depth", "unit": "m"}, {"symbol": "d_{\\rm apparent}", "meaning": "apparent depth", "unit": "m"}, {"symbol": "n", "meaning": "liquid refractive index relative to air approximation", "unit": "dimensionless"}, {"symbol": "P", "meaning": "lens optical power", "unit": "D = m⁻¹"}, {"symbol": "f", "meaning": "signed focal length", "unit": "m"}], "method": ["Select the relevant model: small-particle scattering, near-normal depth or lens power.", "For depth viewed from air divide real depth by the liquid index.", "For power convert focal length to metres before taking its reciprocal.", "Retain the focal-length sign so converging power is positive and diverging power negative."], "worked": ["For the pool, near-normal apparent depth is 2/1.33 ≈ 1.50 m, so the bottom appears shallower.", "The index does not change the real 2 m depth; it changes the directions of the emerging rays.", "For the separate converging lens, f = +0.25 m.", "Its power is 1/0.25 = +4 m⁻¹, written +4 dioptres."], "selfCheck": {"question": "A diverging lens has focal length -50 cm. What is its power?", "answer": "-2 D, since -50 cm = -0.50 m."}, "examTip": "A reciprocal of a focal length in centimetres does not directly give dioptres; convert to metres first.", "assumptions": "The apparent-depth approximation assumes viewing from air near the normal; the Rayleigh rule applies to particles much smaller than wavelength."}, "references": []}, {"title": "Recognize advanced optics without long derivations", "concept": "The wave equation describes a disturbance propagating in space and time. Complex notation is a bookkeeping method for amplitude and phase; the measured field is real. Maxwell laws connect electric and magnetic fields. Birefringent materials have different refractive behaviour for different polarizations. At Brewster incidence the reflected component can be linearly polarized.", "formula": "\\tan\\theta_B=n_2/n_1,\\quad E=cB\\ \\text{(plane wave in vacuum)}", "steps": "For a conceptual question name the physical meaning before manipulating symbols. Distinguish phase from group velocity, absorption from refraction and polarization from interference. Recognize wavefront splitting versus amplitude splitting as ways to create coherent paths.", "example": "A quarter-wave plate can turn suitable linearly polarized light into circular polarization by introducing a quarter-cycle phase difference between equal orthogonal components. Unequal components generally give elliptical polarization.", "trap": "These recognition notes do not replace a lecturer-assigned derivation; return to the source if such derivations are explicitly assessed.", "q": "A quarter-wave plate acts primarily by changing the relative:", "options": ["Charge of light", "Speed of the source", "Mass of photons", "Phase of orthogonal components"], "answer": 3, "why": "A controlled phase delay changes the polarization state.", "problem": "For light from air into glass of index 1.5, estimate Brewster angle.", "solution": "Tangent of Brewster angle=1.5/1.0. The angle is arctan(1.5)=56.3 degrees. Credit correct ratio, inverse tangent, result and interpretation as incidence angle.", "id": "optics-12", "teaching": {"objectives": ["Recognize what a quarter-wave plate changes about polarized light.", "Use Brewster angle and plane-wave relations at recognition level."], "prerequisites": "Linear and circular polarization; phase as position within an oscillation cycle; refractive index.", "symbols": [{"symbol": "\\theta_B", "meaning": "Brewster incidence angle from the normal", "unit": "degrees or radians"}, {"symbol": "n_1,n_2", "meaning": "incident and transmitted medium indices", "unit": "dimensionless"}, {"symbol": "E", "meaning": "plane-wave electric-field magnitude", "unit": "V/m"}, {"symbol": "B", "meaning": "plane-wave magnetic-field magnitude", "unit": "T"}], "method": ["Identify whether the question concerns phase delay, interface polarization or vacuum wave fields.", "For a quarter-wave plate, compare the two orthogonal component amplitudes and their phase difference.", "For Brewster incidence use the index ratio with inverse tangent.", "For a plane vacuum wave connect field magnitudes using E = cB without a long derivation."], "worked": ["Resolve suitable incident linear polarization along the plate principal axes.", "Equal component amplitudes are required for the stated circular-polarization result.", "A quarter-wave plate adds a quarter-cycle, or π/2, relative phase delay.", "Equal amplitudes with this delay give circular polarization; unequal amplitudes generally give elliptical polarization."], "selfCheck": {"question": "Is a quarter-cycle phase delay alone enough to guarantee circular polarization?", "answer": "No. The two orthogonal components must also have equal amplitudes."}, "examTip": "For a recognition answer name the condition and consequence; deriving Maxwell equations is unnecessary for these exercises.", "assumptions": "The wave plate is operating at its intended wavelength; Brewster law here uses ordinary transparent nonmagnetic media."}, "references": []}], "tests": [{"name": "A", "indices": [0, 1, 2, 3, 4, 5]}, {"name": "B", "indices": [6, 7, 8, 9, 10, 11]}], "figure": {"src": "assets/optics.svg", "lessonId": "optics-6", "caption": "A ray entering glass from air bends toward the normal at oblique incidence. The ray sketch is qualitative; frequency is unchanged while speed and wavelength decrease."}}, {"slug": "calculus", "title": "Calculus I", "scope": "MATH 203: derivative rules, implicit/logarithmic/exponential derivatives, L Hopital, graphing and extrema, optimization, Rolle and mean-value theorems, integration and the fundamental theorem. The full lecture syllabus is the main source.", "source": "1-7b0x3wJFKUVyHG6EaPVwSCRwZsGFrLD", "lessons": [{"title": "Limits, continuity and the derivative definition", "concept": "A limit describes nearby values, not necessarily the function value at the point. Continuity requires the function value and the two-sided limit to exist and agree. The derivative is the limiting slope of secant lines and gives instantaneous rate of change.", "formula": "f'(x)=\\lim_{h\\to0}\\frac{f(x+h)-f(x)}{h}", "steps": "Try substitution first. If \\(\\frac00\\) appears, simplify by factoring or rationalizing before taking the limit. For the derivative definition expand the entire \\(f(x+h)\\), subtract f(x), and cancel h before setting h to zero.", "example": "For \\(f(x)=x^2\\), the difference quotient becomes \\(\\frac{2xh+h^2}{h}=2x+h\\). Letting h approach zero gives derivative 2x.", "trap": "Zero over zero is an indeterminate form, not a final answer of zero.", "q": "The derivative of \\(x^2\\) at \\(x=3\\) is:", "options": ["3", "6", "9", "0"], "answer": 1, "why": "The derivative is 2x, so its value at 3 is 6.", "problem": "Use the definition to find the derivative of f(x)=3\\(x^2\\).", "solution": "[3(x+h) squared -3\\(x^2\\)]/h = [6xh+3h squared]/h = 6x+3h. Taking the limit gives 6x. One mark each for setup, expansion, cancellation and limit.", "id": "calculus-1", "teaching": {"objectives": ["Distinguish a limit from a value at the point.", "Find a polynomial derivative from the difference quotient."], "prerequisites": "Expanding a square; factoring and cancelling a nonzero common factor.", "symbols": [{"symbol": "h", "meaning": "small nonzero input increment before the limit", "unit": "same unit as x"}, {"symbol": "f'(x)", "meaning": "instantaneous rate of change", "unit": "output unit per input unit"}], "method": ["Write f(x+h) and subtract the complete original f(x).", "Expand brackets carefully and collect terms.", "Factor out h and cancel only while h is nonzero.", "Take the limit h approaching zero in the simplified expression."], "worked": ["For f(x) = x², the incremented value is (x+h)² = x² + 2xh + h².", "Subtracting f(x) leaves 2xh + h².", "Dividing by nonzero h gives 2x + h.", "As h approaches zero, the secant slope approaches 2x, so f′(x) = 2x."], "selfCheck": {"question": "Why should h not be set to zero before simplifying the difference quotient?", "answer": "It would produce division by zero; the limit concerns nonzero h approaching zero."}, "examTip": "Place brackets around f(x+h) and f(x) before subtraction, especially when either contains negative terms."}, "references": []}, {"title": "Basic derivatives and tangent lines", "concept": "Differentiate a sum term by term. Constants disappear. The derivative gives the slope at a point, but the tangent line must also pass through the point on the original function. Rewrite roots and reciprocal powers before applying the power rule.", "formula": "\\frac{d}{dx}x^n=nx^{n-1},\\qquad y-f(a)=f'(a)(x-a)", "steps": "Simplify powers. Differentiate. Evaluate the derivative at a for the slope and the original function at a for the point. Substitute both into point-slope form.", "example": "For \\(f(x)=x^2+1\\) at \\(x=2\\), the point is (2,5) and slope is 4. The tangent is \\(y-5=4(x-2)\\), or \\(y=4x-3\\).", "trap": "Do not use \\(f'\\)(a) as the y-coordinate.", "q": "The derivative of a constant 7 is:", "options": ["7", "1", "x", "0"], "answer": 3, "why": "A constant function has zero rate of change.", "problem": "Find the tangent to f(x)=x cubed at \\(x=2\\).", "solution": "f(2)=8; derivative=3\\(x^2\\); slope at 2 is 12. Tangent y-8=12(x-2), equivalently y=12x-16. One mark per step.", "id": "calculus-2", "teaching": {"objectives": ["Differentiate sums and powers correctly.", "Build a tangent line from the original point and derivative slope."], "prerequisites": "Power rule; substituting an x value; point-slope form of a line.", "symbols": [{"symbol": "a", "meaning": "input coordinate of tangent point", "unit": "input unit"}, {"symbol": "f(a)", "meaning": "output coordinate of tangent point", "unit": "output unit"}, {"symbol": "f'(a)", "meaning": "tangent slope", "unit": "output unit per input unit"}], "method": ["Differentiate the original function term by term.", "Substitute x = a into the derivative for the slope.", "Substitute x = a into the original function for the point.", "Use y - f(a) = f′(a)(x-a), then simplify only if requested."], "worked": ["For f(x) = x² + 1, f′(x) = 2x because the constant contributes zero.", "At x = 2 the slope is 4, while the original function gives y = 5.", "The tangent must therefore pass through (2,5) with slope 4.", "Its equation is y - 5 = 4(x-2), which expands to y = 4x - 3."], "selfCheck": {"question": "Does substituting x = 2 into f′ give the y coordinate of the tangent point?", "answer": "No. It gives the slope; use f(2) for the y coordinate."}, "examTip": "Keep the unsimplified point-slope equation visible: it shows both required ingredients for method marks."}, "references": []}, {"title": "Product and quotient rules", "concept": "A product has two changing factors, so both contribute to the derivative. A quotient rule numerator must preserve its order; reversing it changes the sign. Do not differentiate numerator and denominator separately to differentiate a fraction.", "formula": "(uv)'=u' v+uv',\\qquad (u/v)'=(u' v-uv')/v^2", "steps": "Label u and v and calculate their derivatives in a small side list. Substitute without expanding first. Simplify only after the rule is complete.", "example": "For \\(y=x^2\\sin x\\), derivative is \\(2x\\sin x+x^2\\cos x\\). Both terms are needed.", "trap": "The quotient denominator is the square of the original denominator.", "q": "The derivative of \\(x e^x\\) is:", "options": ["\\(e^x(1+x)\\)", "0", "\\(e^x\\)", "\\(x e^x\\)"], "answer": 0, "why": "The product rule differentiates each factor in turn.", "problem": "Differentiate y=(x+1)/(x-1), for x not equal to 1.", "solution": "Derivative = [(x-1)-(x+1)]/(x-1) squared = -2/(x-1) squared. Award marks for quotient rule, numerator order, denominator square and simplification.", "id": "calculus-3", "teaching": {"objectives": ["Differentiate a product using both changing factors.", "Preserve term order and the squared denominator in the quotient rule."], "prerequisites": "Basic polynomial and sine derivatives; multiplication and fractions.", "symbols": [{"symbol": "u,v", "meaning": "the two factor functions", "unit": "problem dependent"}, {"symbol": "u',v'", "meaning": "their derivatives with respect to x", "unit": "corresponding output per input unit"}], "method": ["Identify whether the expression is a product or quotient at the outermost level.", "Name the component functions u and v and calculate their derivatives.", "Insert all terms into the appropriate rule before simplifying.", "For a quotient retain the original domain restriction and check the numerator subtraction order."], "worked": ["For y = x² sin x, choose u = x² and v = sin x.", "Their derivatives are u′ = 2x and v′ = cos x.", "The product rule keeps each factor once unchanged: u′v + uv′.", "Thus y′ = 2x sin x + x² cos x; multiplying the two derivatives alone would miss both contributions."], "selfCheck": {"question": "For y = (x+1)/(x-1), what is the derivative for x ≠ 1?", "answer": "-2/(x-1)²: the numerator is (x-1) - (x+1) = -2."}, "examTip": "Write the entire quotient-rule numerator in brackets before expanding; the minus sign applies to the whole second product."}, "references": []}, {"title": "Chain rule and trigonometric functions", "concept": "A composite function has an outer operation acting on an inner expression. Differentiate the outside while preserving the inside, then multiply by the derivative of the inside. Trigonometric derivative formulas use radians.", "formula": "\\frac{d}{dx}f(g(x))=f'(g(x))g'(x),\\quad (\\sin x)'=\\cos x,\\quad (\\cos x)'=-\\sin x", "steps": "Name the inner expression u. Differentiate the outside with respect to u. Multiply by du/dx. Repeat for nested layers.", "example": "For \\(y=(3x+1)^4\\), derivative = \\(4(3x+1)^3\\cdot3=12(3x+1)^3\\).", "trap": "Forgetting the inner derivative is the most common lost mark.", "q": "The derivative of \\(\\sin(5x)\\) is:", "options": ["\\(-5\\sin(5x)\\)", "\\(\\sin(5)\\)", "\\(\\cos(5x)\\)", "\\(5\\cos(5x)\\)"], "answer": 3, "why": "The inner derivative contributes a factor of 5.", "problem": "Differentiate y=cos(\\(x^2\\)).", "solution": "Outer derivative is -sin(\\(x^2\\)); inner derivative is 2x. Multiply to obtain -2x sin(\\(x^2\\)). Credit both layers, sign and product.", "id": "calculus-4", "teaching": {"objectives": ["Identify inner and outer operations in a composite function.", "Include the inner derivative in trigonometric and power derivatives."], "prerequisites": "Power rule; sine and cosine derivatives; radians.", "symbols": [{"symbol": "u=g(x)", "meaning": "inner expression", "unit": "problem dependent"}, {"symbol": "g'(x)", "meaning": "inner derivative", "unit": "inner-expression unit per input unit"}], "method": ["Identify the last operation applied to the expression: this is the outer function.", "Differentiate that outer function while leaving the inner expression in place.", "Multiply by the derivative of the inner expression.", "Check the sign for cosine derivatives and use radians for trigonometric rules."], "worked": ["In y = (3x+1)⁴, the inner expression is 3x+1 and the outer operation is raising to the fourth power.", "The outer derivative gives 4(3x+1)³.", "The inner derivative is 3, so it must multiply the outer result.", "Combining the constants gives y′ = 12(3x+1)³."], "selfCheck": {"question": "What is the derivative of cos(x²)?", "answer": "-2x sin(x²), combining the cosine derivative with the inner derivative 2x."}, "examTip": "Before finishing, circle the inner expression and verify that its derivative appears as a factor."}, "references": [{"title": "Four more trigonometric derivatives", "why_it_matters": "The supplied final asks for a cotangent derivative. Learn these rules together with sine, cosine and the chain rule.", "formulas": ["\\(\\dfrac{d}{dx}\\tan u=\\sec^2u\\,u'\\)", "\\(\\dfrac{d}{dx}\\cot u=-\\csc^2u\\,u'\\)", "\\(\\dfrac{d}{dx}\\sec u=\\sec u\\tan u\\,u'\\)", "\\(\\dfrac{d}{dx}\\csc u=-\\csc u\\cot u\\,u'\\)"], "method": ["Use radians. Here \\(u\\) is a function of \\(x\\), and \\(u'\\) means its derivative.", "Apply the outside rule, then multiply by the inside derivative.", "Use a rule only where the original function is defined. Remember: \\(\\sec u=1/\\cos u\\), \\(\\csc u=1/\\sin u\\), and \\(\\cot u=\\cos u/\\sin u\\)."], "check": {"question": "Differentiate \\(y=\\cot(5x)\\).", "steps": ["The inside is \\(u=5x\\), so \\(u'=5\\).", "The cotangent rule gives \\(y'=-\\csc^2(5x)\\times5\\)."], "answer": "\\(y'=-5\\csc^2(5x)\\). The minus sign and the factor 5 both matter."}, "sources": [{"title": "Supplied MATH 203 final, question 13", "url": "https://drive.google.com/file/d/1yIMCx2yZjWM-wPGwweW2UaAticYL2pQS/view"}, {"title": "Calculus lecture, section 2.5", "url": "https://drive.google.com/file/d/1JMwPD91GtEVFZHzDfR4JJzDZ_RmGlDZZ/view"}]}]}, {"title": "Implicit differentiation", "concept": "When x and y appear in one equation, y is treated as a function of x. Differentiating a y term therefore introduces \\(y'\\). Collect all y-prime terms and solve algebraically. This can describe curves that are not single-valued functions globally.", "formula": "\\frac{d}{dx}(y^2)=2yy',\\quad \\frac{d}{dx}(xy)=y+xy'", "steps": "Differentiate both sides with respect to x. Apply product and chain rules. Collect terms containing \\(y'\\) and divide by their coefficient.", "example": "From \\(x^2+y^2=25\\), differentiation gives \\(2x+2yy'=0\\). Thus \\(y'=-\\frac{x}{y}\\) wherever y is nonzero.", "trap": "Do not treat y as a constant or omit the product rule on xy.", "q": "For \\(x^2+y^2=25\\), the slope at (3,4) is:", "options": ["0", "\\(\\frac34\\)", "\\(-\\frac34\\)", "\\(\\frac43\\)"], "answer": 2, "why": "Implicit differentiation gives slope \\(-\\frac{x}{y}\\).", "problem": "Find dy/dx for xy+y squared=6.", "solution": "Differentiate: y+x \\(y'\\)+2y \\(y'\\)=0. Collect: (x+2y)\\(y'\\)=-y. Hence \\(y'\\)=-y/(x+2y), where the denominator is nonzero. Four marks across these steps.", "id": "calculus-5", "teaching": {"objectives": ["Differentiate y terms while treating y as a function of x.", "Collect and isolate all terms containing y′."], "prerequisites": "Chain and product rules; algebraic rearrangement.", "symbols": [{"symbol": "y'", "meaning": "dy/dx, the local slope of the curve", "unit": "y unit per x unit"}], "method": ["Differentiate both sides with respect to x.", "Attach y′ when differentiating a function of y, and use the product rule for xy.", "Move all terms containing y′ to one side.", "Factor out y′, divide by its coefficient and state where that division is valid."], "worked": ["The curve x² + y² = 25 need not be solved globally for a single y value.", "Differentiating x² gives 2x; differentiating y² gives 2y y′ by the chain rule.", "The constant 25 differentiates to zero, so 2x + 2y y′ = 0.", "Rearranging gives y′ = -x/y wherever y ≠ 0; division by y requires this restriction."], "selfCheck": {"question": "Why does the derivative of y² contain y′?", "answer": "Because y depends on x; the chain rule multiplies 2y by dy/dx."}, "examTip": "For an xy term write y + xy′, not simply y or xy′; both factors depend on x."}, "references": []}, {"title": "Logarithmic, exponential and inverse-trig derivatives", "concept": "Exponential functions reproduce themselves up to an inner derivative. Natural logarithms give a reciprocal factor. Logarithmic differentiation helps when variable powers or products are awkward. Inverse-trigonometric functions are different from reciprocal trigonometric functions.", "formula": "(e^u)'=e^u u',\\quad (\\ln|u|)'=u'/u,\\quad (\\arctan x)'=1/(1+x^2)", "steps": "Identify the function family and its domain. Apply the correct outer derivative and multiply by the inner derivative. For a variable power take logarithms before differentiating.", "example": "For \\(y=\\ln(x^2+1)\\), derivative is \\(\\frac{2x}{x^2+1}\\). For y=\\(e^{3x}\\), derivative is \\(3e^{3x}\\).", "trap": "The derivative of ln u is u prime/u, not 1/ln u.", "q": "The derivative of \\(\\arctan x\\) is:", "options": ["\\(\\arctan(1)\\)", "\\(\\frac{1}{1+x^2}\\)", "\\(\\frac{1}{\\cos^2 x}\\)", "\\(-\\frac{1}{1+x^2}\\)"], "answer": 1, "why": "This is the standard inverse-tangent derivative.", "problem": "Differentiate y=x to the power x for x greater than zero.", "solution": "Take logarithms: ln y=x ln x. Differentiate: \\(y'\\)/y=ln x+1. Multiply by y: \\(y'\\)=x to the x times (ln x+1). Four marks for these stages.", "id": "calculus-6", "teaching": {"objectives": ["Differentiate exponential and logarithmic composites.", "Use logarithmic differentiation for a positive variable base and exponent."], "prerequisites": "Chain rule; natural logarithms; product rule; positive-domain restrictions.", "symbols": [{"symbol": "e", "meaning": "base of the natural exponential", "unit": "dimensionless"}, {"symbol": "\\ln u", "meaning": "natural logarithm of a positive dimensionless argument", "unit": "dimensionless"}], "method": ["Identify the outer function and check its real domain.", "For a logarithm use inner derivative divided by the inner expression.", "For an exponential retain the exponential and multiply by the inner derivative.", "For y = x^x with x > 0, take logs first, differentiate implicitly, then restore y."], "worked": ["For ln(x²+1), the inner derivative is 2x and the inner expression is always positive.", "The logarithmic chain rule therefore gives 2x/(x²+1).", "For the separate function e^(3x), the exponential is retained unchanged.", "Multiplication by the inner derivative 3 gives 3e^(3x)."], "selfCheck": {"question": "For x > 0, what is d(x^x)/dx?", "answer": "x^x(ln x + 1). Take ln y = x ln x, then y′/y = ln x + 1."}, "examTip": "The power rule nx^(n-1) assumes a constant exponent; x^x needs another method."}, "references": [{"title": "Other exponential, logarithm and inverse-trig rules", "why_it_matters": "The supplied final includes \\(3^x\\) and \\(\\log_3x\\). Their derivatives need a factor involving \\(\\ln3\\).", "formulas": ["\\(\\dfrac{d}{dx}a^u=a^u\\ln(a)\\,u'\\)", "\\(\\dfrac{d}{dx}\\log_a u=\\dfrac{u'}{u\\ln a}\\)", "\\(\\dfrac{d}{dx}\\arcsin u=\\dfrac{u'}{\\sqrt{1-u^2}}\\)", "\\(\\dfrac{d}{dx}\\arccos u=-\\dfrac{u'}{\\sqrt{1-u^2}}\\)"], "method": ["The base \\(a\\) is a fixed positive number, with \\(a\\ne1\\). For the logarithm, require \\(u>0\\).", "For the displayed arcsine and arccosine derivatives, require \\(|u|<1\\). Angles are in radians.", "Find the inside derivative \\(u'\\) first. Inverse sine means \\(\\arcsin\\); it is different from \\(1/\\sin\\)."], "check": {"question": "Differentiate \\(3^x\\) and \\(\\log_3x\\).", "steps": ["In both cases the inside expression is \\(u=x\\), so \\(u'=1\\).", "For the exponential, multiply by \\(\\ln3\\). For the logarithm, divide by \\(\\ln3\\)."], "answer": "\\((3^x)'=3^x\\ln3\\), and \\((\\log_3x)'=1/(x\\ln3)\\) for \\(x>0\\)."}, "sources": [{"title": "Supplied MATH 203 final, questions 10 and 12", "url": "https://drive.google.com/file/d/1yIMCx2yZjWM-wPGwweW2UaAticYL2pQS/view"}, {"title": "Calculus lecture, sections 3.2–3.3", "url": "https://drive.google.com/file/d/1JMwPD91GtEVFZHzDfR4JJzDZ_RmGlDZZ/view"}]}]}, {"title": "L Hopital and indeterminate forms", "concept": "L Hopital rule can evaluate a quotient limit with the form \\(\\frac{0}{0}\\text{ or }\\frac{\\infty}{\\infty}\\) under its differentiability and limit conditions. Differentiate numerator and denominator separately for this limit procedure; this is not the quotient rule. Other indeterminate forms must first be rewritten.", "formula": "\\lim\\frac{f(x)}{g(x)}=\\lim\\frac{f'(x)}{g'(x)}\\quad\\text{when the rule applies}", "steps": "Check the form by substitution. State the qualifying form. Differentiate top and bottom separately, then reassess the new limit. Stop when ordinary evaluation works.", "example": "As x approaches zero, \\(\\frac{e^x-1}{x}\\) has form \\(\\frac00\\). The derivative quotient is \\(\\frac{e^x}{1}\\), giving limit 1.", "trap": "Do not use the rule on a quotient whose substitution gives an ordinary finite value.", "q": "Before applying L Hopital directly, the quotient should have form:", "options": ["\\(\\frac{0}{0}\\text{ or }\\frac{\\infty}{\\infty}\\)", "\\(\\frac11\\) only", "\\(\\frac05\\) only", "Any fraction"], "answer": 0, "why": "The rule concerns specified indeterminate quotient forms.", "problem": "Evaluate the limit of sin(3x)/x as x approaches zero.", "solution": "The form is \\(\\frac00\\). L Hopital gives limit 3 cos(3x)/1 = 3. Alternatively use the standard sine limit. Credit form, derivative, evaluation and answer.", "id": "calculus-7", "teaching": {"objectives": ["Check for a permitted indeterminate quotient before using L Hopital.", "Evaluate a simple limit by differentiating numerator and denominator."], "prerequisites": "Limits; exponential and trigonometric derivatives; chain rule.", "symbols": [{"symbol": "0/0", "meaning": "indeterminate limiting form, not an arithmetic value", "unit": "not a measured quantity"}, {"symbol": "\\infty/\\infty", "meaning": "indeterminate quotient form", "unit": "not a measured quantity"}], "method": ["Substitute the limiting input to identify the quotient form.", "Confirm 0/0 or infinity/infinity and the rule conditions before differentiating.", "Differentiate numerator and denominator separately, not with the quotient rule.", "Evaluate the new limit; if still indeterminate, check conditions again before repeating."], "worked": ["As x approaches zero, e^x - 1 approaches zero and x approaches zero.", "The quotient therefore has the required 0/0 form.", "Differentiate numerator and denominator separately to obtain e^x/1.", "Its limit is e^0 = 1, so the original limit is 1."], "selfCheck": {"question": "What is the limit of sin(3x)/x as x approaches zero?", "answer": "3, since the derivative quotient is 3 cos(3x)/1 and cos 0 = 1."}, "examTip": "Show the initial indeterminate form; applying the rule without checking its conditions can invalidate the method.", "assumptions": "The numerator and denominator satisfy the differentiability and denominator-derivative conditions near the limiting point."}, "references": []}, {"title": "Increasing, decreasing and concavity", "concept": "The sign of the first derivative controls increasing and decreasing intervals. The sign of the second controls concavity. A critical number lies in the domain where the first derivative is zero or undefined. An inflection point requires a concavity change, not merely a zero second derivative.", "formula": "f'>0:\\ \\text{increasing};\\quad f''>0:\\ \\text{concave up}", "steps": "Find critical numbers and split the domain into intervals. Test one value in each interval for the derivative sign. Repeat with the second derivative for concavity.", "example": "For \\(f=x^3-3x\\), derivative is \\(3(x-1)(x+1)\\). The function increases outside \\([-1,1]\\) and decreases between -1 and 1.", "trap": "A derivative equal to zero does not automatically mean a maximum.", "q": "If \\(f'\\) is negative on an interval, f is:", "options": ["Decreasing", "Constant", "Always concave down", "Increasing"], "answer": 0, "why": "Negative slope means the function decreases as x increases.", "problem": "For \\(f(x)=x^2\\)-4x, find increasing and decreasing intervals and the minimum point.", "solution": "Derivative = 2x-4, zero at 2. It is negative for x<2 and positive for x>2. Minimum is (2,-4). One mark each for derivative, intervals and point.", "id": "calculus-8", "teaching": {"objectives": ["Use a first-derivative sign chart to find monotonic intervals.", "Distinguish a stationary point from a proven extremum or inflection."], "prerequisites": "Factoring quadratics; sign tests; first and second derivatives.", "symbols": [{"symbol": "f'", "meaning": "first derivative, controlling increase or decrease", "unit": "output per input unit"}, {"symbol": "f''", "meaning": "second derivative, controlling concavity", "unit": "output per input unit squared"}], "method": ["Find where f′ is zero or undefined within the original domain.", "Split the domain at those critical numbers and test the sign on each interval.", "Use sign changes to classify local maxima and minima.", "Use f″ signs separately for concavity and require a concavity change for an inflection point."], "worked": ["For f(x) = x³ - 3x, f′ = 3x² - 3 = 3(x-1)(x+1).", "The critical numbers are -1 and 1.", "Testing x = -2, 0 and 2 gives derivative signs positive, negative and positive.", "The function increases on (-∞,-1) and (1,∞), and decreases on (-1,1); the sign changes identify a local maximum at -1 and minimum at 1."], "selfCheck": {"question": "Is f″(c) = 0 alone enough to prove an inflection point?", "answer": "No. Concavity must change across c."}, "examTip": "Give open intervals for increasing and decreasing behaviour, then state extrema as points if asked."}, "references": []}, {"title": "Graphing, asymptotes and absolute extrema", "concept": "Graphing combines domain, intercepts, derivative signs and limiting behaviour. A cancelled factor can create a hole rather than an asymptote. On a closed interval a continuous function attains absolute extrema; compare endpoint and interior critical values.", "formula": "\\text{Candidates} = \\text{endpoints plus interior critical numbers}", "steps": "State the domain first. For rational functions factor before classifying discontinuities. For absolute extrema evaluate the original function at every candidate and compare actual values.", "example": "For \\(x^2\\) on \\([-1,2]\\), candidates are -1,0,2. Values are 1,0,4, so the absolute minimum is 0 and maximum is 4.", "trap": "Do not omit endpoints or compare derivative values instead of function values.", "q": "To find absolute extrema on a closed interval, check:", "options": ["Only where \\(f'\\) is zero", "Only endpoints", "Endpoints and interior critical numbers", "Only where f is zero"], "answer": 2, "why": "The largest or smallest value may occur at either kind of candidate.", "problem": "Find absolute maximum and minimum of \\(f(x)=x^2\\)-2x on [0,3].", "solution": "Critical point x=1. Values: f(0)=0, f(1)=-1, f(3)=3. Minimum -1 at x=1; maximum 3 at \\(x=3\\). Credit candidates, evaluations and both extrema.", "id": "calculus-9", "teaching": {"objectives": ["Find absolute extrema by comparing all candidates on a closed interval.", "Distinguish a removable hole from a vertical asymptote."], "prerequisites": "Domain restrictions; critical numbers; evaluating a function at endpoints.", "symbols": [{"symbol": "[a,b]", "meaning": "closed interval including both endpoints", "unit": "input unit"}, {"symbol": "f(c)", "meaning": "function value at a candidate point", "unit": "output unit"}], "method": ["Check the domain and whether the function is continuous on the stated closed interval.", "Find all interior critical numbers.", "Evaluate the original function at those numbers and at both endpoints.", "Compare the values and report each extremum value together with where it occurs."], "worked": ["For f(x) = x² on [-1,2], the derivative 2x is zero at x = 0.", "The candidate inputs are the two endpoints -1 and 2 and the interior critical number 0.", "The original function values are f(-1)=1, f(0)=0 and f(2)=4.", "The smallest is 0 at x=0; the largest is 4 at x=2."], "selfCheck": {"question": "Can an endpoint be the absolute maximum even when its derivative is not zero?", "answer": "Yes. Absolute extrema on a closed interval must include endpoint checks."}, "examTip": "Use the original function for the comparison table; comparing derivative values does not locate the highest graph point."}, "references": []}, {"title": "Optimization and mean-value theorems", "concept": "Optimization translates a word problem into a one-variable function and an allowed domain. Rolle theorem requires equal endpoint values as well as continuity and interior differentiability. The mean-value theorem matches some instantaneous slope to the average slope.", "formula": "f'(c)=\\frac{f(b)-f(a)}{b-a},\\quad a<c<b", "steps": "For optimization write the constraint, eliminate a variable, differentiate and verify the candidate gives the requested extremum. For a theorem question state every hypothesis before solving for c.", "example": "A rectangle with perimeter 20 has area \\(x(10-x)\\). Its derivative is \\(10-2x\\), so maximum area occurs at \\(x=5\\): a square of area 25.", "trap": "A candidate outside the physical domain is not a valid optimization answer.", "q": "Rolle theorem additionally requires:", "options": ["An infinite interval", "Equal endpoint function values", "A discontinuity", "A nonzero derivative everywhere"], "answer": 1, "why": "Equal endpoint heights make the average slope zero.", "problem": "Use the mean-value theorem for \\(f(x)=x^2\\) on [1,3] to find c.", "solution": "The polynomial is continuous and differentiable. Average slope = (9-1)/(3-1)=4. Solve 2c=4 to get c=2, which is inside (1,3). Four marks for hypotheses, slope, solution and interval check.", "id": "calculus-10", "teaching": {"objectives": ["Translate a simple optimization constraint into one variable.", "Check mean-value-theorem assumptions and solve for the interior input."], "prerequisites": "Area and perimeter; derivatives; continuity and differentiability.", "symbols": [{"symbol": "x", "meaning": "one rectangle side length", "unit": "length unit"}, {"symbol": "A", "meaning": "rectangle area", "unit": "square length unit"}, {"symbol": "c", "meaning": "interior input guaranteed by the mean-value theorem", "unit": "input unit"}], "method": ["For optimization name the objective, write the constraint and identify the feasible domain.", "Eliminate one variable, differentiate and find interior critical candidates.", "Check endpoints or derivative signs to justify the optimum.", "For a theorem question verify its assumptions before setting instantaneous slope equal to average slope."], "worked": ["Perimeter 20 gives 2x + 2y = 20, so the other side is y = 10 - x.", "Area becomes A(x) = x(10-x) with 0 < x < 10 for a nondegenerate rectangle.", "Its derivative is 10 - 2x, which vanishes at x = 5.", "The second derivative is -2, confirming a maximum; both sides are 5 and area is 25 square units."], "selfCheck": {"question": "For f(x)=x² on [1,3], what c satisfies the mean-value theorem?", "answer": "c=2: the average slope is (9-1)/(3-1)=4 and f′(c)=2c=4."}, "examTip": "A critical number alone is not a maximum proof; include a sign change, second derivative or candidate comparison."}, "references": []}, {"title": "Antiderivatives and substitution", "concept": "An indefinite integral represents a family of antiderivatives, so include an arbitrary constant. Substitution reverses the chain rule: select an inner expression whose derivative is present. Differentiate your answer as a fast correctness check.", "formula": "\\int x^n\\,dx=x^{n+1}/(n+1)+C\\ (n\\ne-1),\\quad \\int dx/x=\\ln|x|+C", "steps": "Choose u and calculate du. Rewrite the entire integral in u, including dx factors. Integrate, substitute back and add C.", "example": "For the integral of \\(2x(x^2+1)^3\\), set \\(u=x^2+1\\) and \\(du=2x\\,dx\\). Answer is \\(\\frac{(x^2+1)^4}{4}+C\\).", "trap": "The power rule exception is n=-1; do not divide by zero.", "q": "An indefinite integral must generally include:", "options": ["Only a numerical answer", "A fixed upper limit", "No variable", "An arbitrary constant"], "answer": 3, "why": "Differentiation loses constants, so all antiderivatives differ by a constant on an interval.", "problem": "Evaluate the integral of 6x(\\(x^2\\)+2) squared with respect to x.", "solution": "Set u=\\(x^2\\)+2, \\(du=2x\\,dx\\). Integral becomes 3 times integral u squared du = u cubed+C = (\\(x^2\\)+2) cubed+C. Credit substitution, factor, integration and constant.", "id": "calculus-11", "teaching": {"objectives": ["Choose a substitution whose differential matches the integrand.", "Return the antiderivative to x and include the integration constant."], "prerequisites": "Chain rule; power integration; constant factors.", "symbols": [{"symbol": "u", "meaning": "chosen inner expression", "unit": "problem dependent"}, {"symbol": "du", "meaning": "differential of the inner expression", "unit": "same unit as u"}, {"symbol": "C", "meaning": "arbitrary additive integration constant", "unit": "antiderivative unit"}], "method": ["Choose an inner expression whose derivative is also present as a factor.", "Write u and du and replace every part of the integral consistently.", "Integrate in u, preserving any numerical factors.", "Substitute back to x, add C and differentiate once to check."], "worked": ["For the integral of 2x(x²+1)³, choose u = x²+1.", "Then du = 2x dx, so the complete integral becomes the integral of u³ du.", "The antiderivative is u⁴/4 + C.", "Substitute back to get (x²+1)⁴/4 + C; differentiation restores 2x(x²+1)³."], "selfCheck": {"question": "What is the integral of 6x(x²+2)² dx?", "answer": "(x²+2)³ + C. With u=x²+2, the integral becomes 3 times the integral of u² du."}, "examTip": "Do not leave a mixture of u and x in the substituted integral; it hides missing differential factors."}, "references": [{"title": "Integrate sine, cosine and an exponential", "why_it_matters": "These short rules reverse the chain rule. A sine integral appears in the supplied final.", "formulas": ["\\(\\int\\sin(ax+b)\\,dx=-\\dfrac{\\cos(ax+b)}{a}+C\\)", "\\(\\int\\cos(ax+b)\\,dx=\\dfrac{\\sin(ax+b)}{a}+C\\)", "\\(\\int e^{ax+b}\\,dx=\\dfrac{e^{ax+b}}{a}+C\\)"], "method": ["Here \\(a\\) and \\(b\\) are constants and \\(a\\ne0\\). Trigonometric angles use radians.", "Divide by the coefficient \\(a\\); differentiation would multiply by it.", "Add \\(C\\) for an indefinite integral. Differentiate your answer to check it."], "check": {"question": "Find \\(\\int\\sin(3x)\\,dx\\).", "steps": ["The sine antiderivative is negative cosine.", "The inside derivative is 3, so divide by 3.", "Check: \\(\\dfrac{d}{dx}[-\\cos(3x)/3]=\\sin(3x)\\)."], "answer": "\\(-\\dfrac13\\cos(3x)+C\\)."}, "sources": [{"title": "Supplied MATH 203 final, question 2", "url": "https://drive.google.com/file/d/1yIMCx2yZjWM-wPGwweW2UaAticYL2pQS/view"}, {"title": "Calculus lecture, sections 5.2–5.3", "url": "https://drive.google.com/file/d/1JMwPD91GtEVFZHzDfR4JJzDZ_RmGlDZZ/view"}]}]}, {"title": "Definite integrals, signed area and the fundamental theorem", "concept": "A definite integral gives signed accumulation: contributions below the axis are negative. Geometrical area requires positive contributions from each region. The fundamental theorem connects integration and differentiation; for a variable upper limit, include its derivative.", "formula": "\\int_a^b f(x)\\,dx=F(b)-F(a),\\quad \\frac{d}{dx}\\int_a^{g(x)}f(t)\\,dt=f(g(x))g'(x)", "steps": "Find an antiderivative, evaluate upper minus lower and omit C from the final definite value. For substitution either change the limits to u or return to x before applying original limits.", "example": "The \\(\\int_{-1}^{1}x\\,dx\\) is zero by cancellation, but total geometrical area is 1. These answer different questions.", "trap": "Never keep x-limits on an integral that has been fully changed to u.", "q": "The \\(\\int_{-2}^{2}x\\,dx\\) equals:", "options": ["8", "-4", "0", "4"], "answer": 2, "why": "The odd integrand has equal and opposite signed areas.", "problem": "Evaluate the integral from 0 to 1 of 2x(\\(x^2\\)+1) dx.", "solution": "Set \\(u=x^2+1\\); limits become 1 and 2. Integral of u du from 1 to 2 = (4-1)/2 = 3/2. Credit substitution, new limits, antiderivative and subtraction.", "id": "calculus-12", "teaching": {"objectives": ["Distinguish signed integral from total geometrical area.", "Apply the fundamental theorem, including a variable-upper-limit chain factor."], "prerequisites": "Antiderivatives; positive and negative regions; substituting bounds.", "symbols": [{"symbol": "a,b", "meaning": "lower and upper integration bounds", "unit": "input unit"}, {"symbol": "F", "meaning": "an antiderivative of f", "unit": "f unit times input unit"}, {"symbol": "t", "meaning": "dummy integration variable", "unit": "input unit"}], "method": ["Identify whether the question asks for signed accumulation or total area.", "Find an antiderivative and calculate upper value minus lower value.", "For total area split at sign changes and make each region contribution positive.", "For differentiation with upper bound g(x), evaluate f at g(x) and multiply by g′(x)."], "worked": ["For y = x from -1 to 1, the region below the axis contributes negative signed area.", "An antiderivative is x²/2; evaluation at 1 and -1 gives 1/2 - 1/2 = 0.", "Geometrically each half is a triangle with area 1/2.", "Total geometrical area is 1/2 + 1/2 = 1, while the signed integral remains zero."], "selfCheck": {"question": "Does a zero definite integral prove the function is zero throughout the interval?", "answer": "No. Positive and negative contributions can cancel."}, "examTip": "For a definite integral evaluate both bounds; no arbitrary +C is needed in the final numerical answer."}, "references": [{"title": "Read a Riemann sum as rectangles", "why_it_matters": "The course syllabus includes sigma notation and area as a limit. The symbol \\(\\sum\\) simply means add the terms.", "formulas": ["\\(\\Delta x=\\dfrac{b-a}{n}\\)", "\\(\\text{rectangle sum}=\\sum_{i=1}^{n}f(x_i^*)\\,\\Delta x\\)"], "method": ["Split the interval from \\(a\\) to \\(b\\) into \\(n\\) equal widths.", "Choose a sample point \\(x_i^*\\) in each small interval. Its function value is that rectangle's signed height.", "Add height times width. More, narrower rectangles approach the definite integral when the function is continuous.", "Below-axis heights contribute negative signed area."], "check": {"question": "Use two right-end rectangles to estimate \\(\\int_0^1x\\,dx\\).", "steps": ["Each width is \\(\\Delta x=(1-0)/2=1/2\\).", "The right endpoints are \\(1/2\\) and \\(1\\), giving heights \\(1/2\\) and \\(1\\).", "The estimate is \\((1/2)(1/2)+(1)(1/2)=3/4\\)."], "answer": "Estimate: \\(3/4\\). Exact integral: \\(1/2\\). The right-end estimate is too large because the function increases."}, "sources": [{"title": "Calculus lecture syllabus, area and definite-integral topics", "url": "https://drive.google.com/file/d/1JMwPD91GtEVFZHzDfR4JJzDZ_RmGlDZZ/view"}]}]}], "tests": [{"name": "A", "indices": [0, 1, 2, 3, 4, 5]}, {"name": "B", "indices": [6, 7, 8, 9, 10, 11]}], "figure": {"src": "assets/calculus.svg", "lessonId": "calculus-2", "caption": "The tangent to y = x² at (2,4) has slope 4. The axes use different display scales; slope is calculated from coordinate values, not from the visual angle."}}, {"slug": "laboratory", "title": "Mechanics and Heat Lab", "scope": "All distinct experiments in the folder: pendulum, free fall, static and dynamic springs, force table, cooling, Boyle law, expansion, specific heat, latent heat and Joule equivalent. Duplicate versions are consolidated.", "source": "1CSfN0ePLYoBsj8WGnm8FxlJXpSxoFgl2", "lessons": [{"title": "Earn marks from tables, graphs and uncertainty", "concept": "A lab result is a measured quantity with units and a justified method. Record raw observations before calculating derived columns. A slope is change in the vertical variable divided by change in the horizontal variable. Its units are essential and determine how to recover the desired constant.", "formula": "m=\\Delta y/\\Delta x,\\quad \\%\\text{ error}=100|x_{\\rm measured}-x_{\\rm reference}|/|x_{\\rm reference}|", "steps": "Write the aim, controlled variables and measurement method. Label every table column and graph axis with units. Use well-separated points on a best-fit line for slope, rather than one noisy pair of raw observations.", "example": "A fitted line rises by 0.8 square seconds over 0.2 m. Its slope is 4 square seconds per metre. It is not 0.25 m per square second unless the axes are reversed.", "trap": "Do not force a line through the origin unless the model and measurement offsets justify it.", "q": "If y is force in N and x is extension in m, slope units are:", "options": ["N/m", "m/N", "N times m", "No units"], "answer": 0, "why": "Slope units are vertical units divided by horizontal units.", "problem": "A measured g is 9.6 \\(\\mathrm{m/s^2}\\) and reference g is 9.8 \\(\\mathrm{m/s^2}\\). Calculate percentage error and name one possible systematic error.", "solution": "Percentage error = 100 times 0.2/9.8 = 2.04 percent. A consistent height-scale zero offset is one possible systematic error. Two marks for the calculation and two for a specific error with its consistency explained.", "id": "laboratory-1", "teaching": {"objectives": ["Calculate a fitted-line slope with the correct axis units.", "Distinguish percentage error from measurement uncertainty."], "prerequisites": "Coordinate differences; division; raw and derived measurements.", "symbols": [{"symbol": "m", "meaning": "slope of the selected vertical variable against horizontal variable", "unit": "vertical unit / horizontal unit"}, {"symbol": "x_{\\rm measured}", "meaning": "experimental estimate", "unit": "same as reference"}, {"symbol": "x_{\\rm reference}", "meaning": "accepted comparison value", "unit": "same as measurement"}], "method": ["Record raw readings with units before calculating derived quantities.", "Label axes with quantities and units and draw a suitable best-fit line.", "Choose two widely separated points on that fitted line and calculate rise over run.", "Use axis units to interpret the slope; compare with a reference using the stated percentage-error formula."], "worked": ["The example has vertical change 0.8 s² and horizontal change 0.2 m.", "Slope is rise over run: 0.8/0.2 = 4 s²/m.", "The reciprocal, 0.25 m/s², belongs to a graph with reversed axes and is a different slope.", "A slope should come from the fitted line, not necessarily from two adjacent raw observations."], "selfCheck": {"question": "Can percentage error alone describe repeatability of a measurement?", "answer": "No. It compares with a reference; repeated-reading spread or an uncertainty estimate is needed to discuss repeatability."}, "examTip": "Write slope units next to the numerical calculation; they help reveal an inverted axis choice."}, "references": [{"title": "Uncertainty is different from percentage error", "why_it_matters": "An uncertainty describes measurement quality. Percentage error compares a result with a reference value.", "formulas": ["\\(\\text{reported result}=\\text{value}\\pm\\text{uncertainty}\\)", "\\(\\%\\text{ error}=100\\dfrac{|x_{\\rm measured}-x_{\\rm reference}|}{|x_{\\rm reference}|}\\)"], "method": ["Use the uncertainty method specified by your experiment or instrument; do not invent a precision from extra calculator digits.", "Give the uncertainty the same unit as the value. Round the value to the same decimal place as the reported uncertainty.", "Repeated measurements help estimate and reduce the effect of random scatter. They do not remove a consistent zero offset.", "An uncertainty range is not a guarantee that every possible error is inside it."], "check": {"question": "A result is \\((9.6\\pm0.2)\\,\\mathrm{m/s^2}\\), and the reference is \\(9.8\\,\\mathrm{m/s^2}\\). State the given uncertainty and calculate percentage error.", "steps": ["The stated uncertainty is \\(0.2\\,\\mathrm{m/s^2}\\).", "Percentage error is \\(100|9.6-9.8|/9.8\\approx2.04\\%\\)."], "answer": "Uncertainty: \\(\\pm0.2\\,\\mathrm{m/s^2}\\). Percentage error: about \\(2.04\\%\\). They answer different questions."}, "sources": [{"title": "Extension supporting the existing laboratory measurement lesson", "url": null}]}]}, {"title": "Simple pendulum", "concept": "For small angles a pendulum period depends mainly on length and gravity, not bob mass. Measure length from pivot to the centre of the bob. Timing several complete oscillations reduces the relative impact of reaction time. Keep the starting angle small and avoid pushing the bob.", "formula": "T=t/N,\\quad T^2=(4\\pi^2/g)L,\\quad g=4\\pi^2/m\\ \\text{for }T^2\\text{ versus }L", "steps": "Measure L, time N complete cycles, calculate T and \\(T^2\\), and plot \\(T^2\\) vertically against L horizontally. Obtain g from the fitted slope.", "example": "For L=1 m and T=2 s, g = \\(4\\pi^2\\) times 1/4 = 9.87 \\(\\mathrm{m/s^2}\\).", "trap": "Using total timing t instead of the single-cycle period T makes g dramatically wrong.", "q": "Pendulum length should be measured to:", "options": ["The top of the table", "The lowest swing point", "The bottom of the bob", "The centre of the bob"], "answer": 3, "why": "The ideal mass is represented at the bob centre.", "problem": "A pendulum takes 30 s for 15 cycles at length 0.99 m. Calculate period and g.", "solution": "T=30/15=2 s. g=\\(4\\pi^2\\) times 0.99/4=9.77 \\(\\mathrm{m/s^2}\\). Two marks per calculation.", "id": "laboratory-2", "teaching": {"objectives": ["Measure pendulum length and period consistently.", "Recover g from one trial or a T²-versus-L graph."], "prerequisites": "Complete oscillation; squaring; slope interpretation.", "symbols": [{"symbol": "L", "meaning": "pivot-to-bob-centre length", "unit": "m"}, {"symbol": "t", "meaning": "time for N complete oscillations", "unit": "s"}, {"symbol": "T", "meaning": "period of one oscillation", "unit": "s"}, {"symbol": "g", "meaning": "gravitational acceleration", "unit": "m/s²"}], "method": ["Measure length from pivot to the bob centre and release from a small angle without a push.", "Time several complete oscillations and divide total time by their count.", "Calculate T² and repeat at several lengths if graphing.", "For T² on the vertical axis and L horizontally, use g = 4π²/slope."], "worked": ["For the example L = 1 m and T = 2 s.", "Square the measured period: T² = 4 s².", "Rearranging T² = 4π²L/g gives g = 4π²L/T².", "Substitution gives g = 4π² times 1/4 ≈ 9.87 m/s²."], "selfCheck": {"question": "A bob crosses equilibrium twice in one full cycle. Should each crossing be counted as a cycle?", "answer": "No. Count a return to the same position moving in the same direction as one full cycle."}, "examTip": "State which variables are on which axes before converting a slope into g.", "assumptions": "The simple model assumes small angular displacement, negligible damping and a light inextensible suspension."}, "references": []}, {"title": "Free fall and axis choice", "concept": "For release from rest with negligible air drag, fall distance grows with time squared. The course sheets mention both graph orientations; the equation must decide the slope conversion. A light sensor or electronic timer avoids large manual timing errors.", "formula": "h=\\tfrac12gt^2;\\quad m_{h\\text{ vs }t^2}=g/2;\\quad m_{t^2\\text{ vs }h}=2/g", "steps": "Record height and fall time. Square each time. Label the selected axes clearly and rearrange the physical law into vertical variable = slope times horizontal variable.", "example": "A plot of h against \\(t^2\\) has slope 4.9 m per square second, so g=9.8 \\(\\mathrm{m/s^2}\\). Reversing axes gives slope about 0.204 square seconds per metre.", "trap": "Do not use g=2 times slope for a t-squared-versus-height graph.", "q": "For \\(t^2\\) vertically versus h horizontally, g equals:", "options": ["Slope squared", "Slope/2", "2 times slope", "2/slope"], "answer": 3, "why": "Rearranging h = g\\(t^2\\)/2 gives \\(t^2\\) = (2/g)h.", "problem": "The slope of \\(t^2\\) against height is 0.20 square seconds per metre. Find g.", "solution": "g = 2/0.20 = 10 \\(\\mathrm{m/s^2}\\). Four marks for axis identification, rearrangement, substitution and unit.", "id": "laboratory-3", "teaching": {"objectives": ["Linearize free fall with a time-squared graph.", "Select the correct g conversion for either axis orientation."], "prerequisites": "Constant acceleration from rest; square of time; fitted-line slope.", "symbols": [{"symbol": "h", "meaning": "vertical fall distance", "unit": "m"}, {"symbol": "t", "meaning": "fall time", "unit": "s"}, {"symbol": "g", "meaning": "gravitational acceleration", "unit": "m/s²"}, {"symbol": "m", "meaning": "graph slope", "unit": "depends on axes"}], "method": ["Release from rest and measure fall time with the stated apparatus.", "Calculate t² for each height.", "State the graph axes and compare h = (g/2)t² with y = mx.", "For h against t² use g = 2m; for t² against h use g = 2/m."], "worked": ["With h on the vertical axis, the fitted slope is 4.9 m/s².", "The equation h = (g/2)t² shows this slope is half g, so g = 9.8 m/s².", "Reversing the axes makes slope 2/g, about 0.204 s²/m.", "The reciprocal slopes describe the same ideal relationship; neither slope can be interpreted without its axes."], "selfCheck": {"question": "A t²-versus-h slope is 0.20 s²/m. What is g?", "answer": "10 m/s², using g = 2/0.20."}, "examTip": "Do not memorize slope = g/2 without the graph orientation; use the displayed equation to decide.", "assumptions": "The object starts from rest and air resistance is negligible over the measured fall."}, "references": []}, {"title": "Static Hooke law", "concept": "Within the proportional range, spring extension is proportional to the applied load. Extension is loaded length minus unloaded length. The restoring spring force points opposite the extension, while the applied load magnitude is k times extension. An elastic spring returns to its original length after unloading, but that alone does not prove a straight-line force-extension relation.", "formula": "F=k\\Delta L,\\quad F=mg,\\quad k=m_{F\\text{ vs }\\Delta L}", "steps": "Measure the unloaded length once, then calculate each extension. Include the hanger mass when it contributes to load. Plot force against extension and obtain k from the slope.", "example": "A 2 N load produces 0.04 m extension, so k=50 N/m. A permanent change of unloaded length signals the elastic model may no longer apply.", "trap": "Centimetres must be converted to metres before reporting k in N/m.", "q": "The spring constant is the slope of:", "options": ["Time versus temperature", "Extension versus force", "Force versus extension", "Mass versus time"], "answer": 2, "why": "Force = k times extension matches y = mx.", "problem": "A 0.30 kg mass extends a spring by 6 cm. Use g=10 \\(\\mathrm{m/s^2}\\). Find k.", "solution": "Force = 3 N; extension = 0.06 m; k=3/0.06=50 N/m. Award marks for force, conversion, ratio and unit.", "id": "laboratory-4", "teaching": {"objectives": ["Distinguish spring extension from loaded length.", "Find spring stiffness from a load or a force-extension slope."], "prerequisites": "Weight mg; length differences; centimetres to metres.", "symbols": [{"symbol": "F", "meaning": "applied load magnitude", "unit": "N"}, {"symbol": "\\Delta L", "meaning": "loaded minus unloaded spring length", "unit": "m"}, {"symbol": "k", "meaning": "spring stiffness", "unit": "N/m"}, {"symbol": "m", "meaning": "total suspended mass", "unit": "kg"}], "method": ["Record the unloaded spring length first.", "Add the load safely and calculate extension as loaded minus unloaded length.", "Convert extension to metres and load mass to force using mg.", "Find k from F/ΔL or the slope of F against ΔL; check the graph remains linear."], "worked": ["The applied load is 2 N and the extension is 0.04 m, not the total spring length.", "Using F = kΔL gives k = 2/0.04 = 50 N/m.", "This means an additional 1 m extension would require 50 N only if the same linear model remained valid.", "If unloading leaves a changed length, the spring has not returned elastically; avoid extrapolating the original model."], "selfCheck": {"question": "A 0.30 kg total load extends the spring 6 cm with g = 10 m/s². What is k?", "answer": "50 N/m: the force is 3 N and extension is 0.06 m."}, "examTip": "Include the hanger in total suspended mass if the apparatus instructions require it; otherwise the force scale can acquire an offset.", "assumptions": "Use Hooke law only over the proportional linear range; elastic recovery alone does not guarantee strict proportionality."}, "references": []}, {"title": "Dynamic spring and gravity", "concept": "An oscillating mass-spring system has a period that increases with mass and decreases with stiffness. Combining static extension with dynamic period allows gravity to be estimated. Small oscillations and the same effective load model are needed for consistency.", "formula": "T^2=4\\pi^2m/k,\\quad T^2=(4\\pi^2/g)\\Delta L", "steps": "Measure static extension relative to natural length, then time small oscillations about equilibrium. Plot \\(T^2\\) against extension for g, or \\(T^2\\) against mass for k. State which experiment you performed.", "example": "A T-squared-versus-extension slope of 4.0 square seconds per metre gives g=\\(4\\pi^2\\)/4.0=9.87 \\(\\mathrm{m/s^2}\\).", "trap": "The symbols for mass and graph slope can both be m; label them explicitly to avoid confusion.", "q": "For fixed k, multiplying the oscillating mass by four makes the period:", "options": ["Four times", "Half", "Twice", "Unchanged"], "answer": 2, "why": "Period is proportional to the square root of mass.", "problem": "A T-squared-versus-mass graph has slope 0.80 square seconds per kg. Find spring constant.", "solution": "Slope = \\(4\\pi^2\\)/k, so k=\\(4\\pi^2\\)/0.80=49.35 N/m. Credit the selected axes, rearrangement, numerical value and units.", "id": "laboratory-5", "teaching": {"objectives": ["Relate mass-spring period to load and spring stiffness.", "Use graph axes to distinguish a k experiment from a g experiment."], "prerequisites": "Static spring extension; period measurement; slope units.", "symbols": [{"symbol": "T", "meaning": "oscillation period", "unit": "s"}, {"symbol": "m", "meaning": "oscillating mass in the stated model", "unit": "kg"}, {"symbol": "k", "meaning": "spring stiffness", "unit": "N/m"}, {"symbol": "\\Delta L", "meaning": "static equilibrium extension", "unit": "m"}, {"symbol": "g", "meaning": "gravitational acceleration", "unit": "m/s²"}], "method": ["Measure small vertical oscillations about equilibrium and obtain period from several cycles.", "For T² against mass compare the slope with 4π²/k.", "For T² against static extension compare the slope with 4π²/g.", "Apply the matching rearrangement and retain the effective-mass assumptions used by the apparatus."], "worked": ["The example plots T² vertically against static extension horizontally.", "Its slope is 4.0 s²/m, corresponding to 4π²/g.", "Rearrangement gives g = 4π²/4.0 ≈ 9.87 m/s².", "A T²-versus-mass slope would instead determine k; substituting it here would mix two different experiments."], "selfCheck": {"question": "A T²-versus-mass slope is 0.80 s²/kg. What is k?", "answer": "About 49.35 N/m, from 4π²/0.80."}, "examTip": "Use slope units to identify the requested constant: s²/kg for stiffness, s²/m for gravity in these two plots.", "assumptions": "Small oscillations stay in the spring proportional range; the static and dynamic models must treat hanger and effective spring mass consistently."}, "references": []}, {"title": "Force table and equilibrium", "concept": "The force table demonstrates vector addition. The resultant of two forces is their vector sum. The equilibrant has equal magnitude and opposite direction. A centred ring that does not press on the pin indicates approximate balance, subject to pulley friction.", "formula": "\\sum F_x=0,\\quad \\sum F_y=0,\\quad F_i=m_i g", "steps": "Include hanger masses, convert all loads to forces, resolve each force using the marked angles, then add components. Compare the calculated equilibrant with the experimental third force.", "example": "For 3 N east and 4 N north, the resultant is 5 N northeast. The equilibrant is 5 N southwest.", "trap": "The equilibrant is not the resultant in the same direction.", "q": "The equilibrant of a 7 N eastward resultant is:", "options": ["7 N east", "14 N west", "Zero", "7 N west"], "answer": 3, "why": "Equal magnitude and opposite direction produce zero net force.", "problem": "Two forces are 6 N east and 8 N north. Find equilibrant magnitude and direction.", "solution": "Resultant magnitude is 10 N at 53.1 degrees north of east. Equilibrant is 10 N at 233.1 degrees from positive x, or 53.1 degrees south of west. Two marks for magnitude and two for direction.", "id": "laboratory-6", "teaching": {"objectives": ["Calculate the equilibrant from perpendicular forces.", "Explain how the force-table ring indicates approximate equilibrium."], "prerequisites": "Vector components; Pythagoras; angles from positive x.", "symbols": [{"symbol": "F_i", "meaning": "tension force from hanging mass in the ideal setup", "unit": "N"}, {"symbol": "m_i", "meaning": "total hanging mass for a string", "unit": "kg"}, {"symbol": "R", "meaning": "resultant force magnitude", "unit": "N"}], "method": ["Convert each hanging mass to a force using the chosen g.", "Resolve all forces into signed horizontal and vertical components.", "Find the resultant, then reverse both components for the equilibrant.", "Adjust the balancing force and check the ring is centred without pressing on the pin."], "worked": ["The 3 N east and 4 N north forces give resultant components (+3,+4) N.", "Its magnitude is √(3²+4²) = 5 N.", "Its precise direction is 53.1° north of east; northeast here describes its quadrant.", "The equilibrant has components (-3,-4) N and magnitude 5 N, directed 53.1° south of west."], "selfCheck": {"question": "Does the equilibrant have the same direction as the resultant?", "answer": "No. It has equal magnitude and opposite direction."}, "examTip": "If an angle is requested, northeast alone is insufficient; give a numerical angle and reference axis.", "assumptions": "Mass-to-tension conversion neglects pulley friction and string mass; actual balance is approximate."}, "references": []}, {"title": "Newton cooling law", "concept": "A hot object approaches room temperature as its temperature excess decays. The simple model assumes approximately constant surroundings and an effective cooling constant over the measured range. The temperature excess, not the absolute temperature, is the decaying quantity.", "formula": "T-T_r=(T_0-T_r)e^{-kt},\\quad \\ln[(T-T_r)/(T_0-T_r)]=-kt", "steps": "Measure room temperature. Record object temperature at regular times. Calculate temperature excess. A log plot of the normalized excess against time has slope -k.", "example": "If room temperature is 20 degrees C and the object cools from 80 to 50, the excess falls from 60 to 30 degrees, so it halves.", "trap": "The object approaches room temperature, not zero degrees C.", "q": "In the simple cooling model, the cooling rate is proportional to:", "options": ["Mass only", "Zero", "Temperature excess above surroundings", "Absolute time only"], "answer": 2, "why": "Newton cooling uses the difference between object and surrounding temperatures.", "problem": "Room temperature is 25 degrees C. A body starts at 85 degrees C and its temperature excess halves in 5 minutes. What is its temperature then?", "solution": "Initial excess = 60 degrees C. Halved excess = 30 degrees C. Add room temperature: 25+30=55 degrees C. Credit both differences and final interpretation.", "id": "laboratory-7", "teaching": {"objectives": ["Calculate temperature excess above the surroundings.", "Interpret an exponential cooling trend without confusing it with Celsius temperature."], "prerequisites": "Subtracting temperatures; halving; logarithm recognition.", "symbols": [{"symbol": "T", "meaning": "object temperature", "unit": "°C or K consistently"}, {"symbol": "T_r", "meaning": "room temperature", "unit": "same unit as T"}, {"symbol": "k", "meaning": "effective cooling constant", "unit": "inverse time"}, {"symbol": "t", "meaning": "elapsed time", "unit": "s or min consistently with k"}], "method": ["Measure room temperature and record it as the reference.", "Subtract room temperature from each object temperature.", "Compare excesses over time or use the stated logarithmic plot.", "Add the room temperature back when converting a final excess into an object temperature."], "worked": ["The room is at 20°C, so the initial 80°C object has excess 80 - 20 = 60°C.", "At 50°C its excess is 50 - 20 = 30°C.", "The excess has halved, even though 50 is not half of 80.", "This distinction explains why the model approaches room temperature rather than cooling toward 0°C."], "selfCheck": {"question": "At room temperature 25°C, an object starts at 85°C and its excess halves. What is its new temperature?", "answer": "55°C: initial excess 60°C becomes 30°C, then add 25°C."}, "examTip": "When logging data, use a dimensionless excess ratio such as (T-Tr)/(T0-Tr), with temperatures consistently measured.", "assumptions": "Room temperature is approximately constant and the effective cooling constant applies over the measured range."}, "references": []}, {"title": "Boyle law", "concept": "At fixed temperature and fixed amount of gas, absolute pressure is inversely proportional to volume. A narrow uniform tube may use gas-column length as a proxy for volume. Let the gas settle thermally after changing pressure.", "formula": "P_1V_1=P_2V_2,\\quad P\\propto1/V", "steps": "Check temperature and gas amount are controlled. Use absolute pressure, not gauge pressure unless corrected. Test whether PV is approximately constant or plot P against 1/V.", "example": "A gas at 100 kPa and 60 cubic centimetres has volume 30 cubic centimetres at 200 kPa, if temperature stays fixed.", "trap": "Compressing quickly can warm the gas and violate the constant-temperature assumption.", "q": "Boyle law requires:", "options": ["Fixed temperature and gas amount", "Changing gas amount", "Fixed pressure", "Fixed volume"], "answer": 0, "why": "Only pressure and volume are varied in the ideal Boyle experiment.", "problem": "A trapped gas has volume 40 cubic centimetres at absolute pressure 120 kPa. Find its volume at 160 kPa at the same temperature.", "solution": "V2 = 120 times 40/160 = 30 cubic centimetres. Credit controlled conditions, equation, rearrangement and unit.", "id": "laboratory-8", "teaching": {"objectives": ["Use absolute pressure in a fixed-temperature gas comparison.", "Predict the inverse pressure-volume trend and check thermal settling."], "prerequisites": "Inverse proportion; multiplying and dividing; consistent pressure and volume units.", "symbols": [{"symbol": "P", "meaning": "absolute gas pressure", "unit": "Pa or consistent pressure unit"}, {"symbol": "V", "meaning": "gas volume", "unit": "m³ or consistent volume unit"}], "method": ["Confirm the gas amount stays fixed and readings are taken at the same temperature.", "Use absolute pressure rather than gauge pressure.", "Write P1V1 = P2V2 and isolate the requested volume or pressure.", "Check that larger pressure gives smaller volume and allow time for thermal settling between trials."], "worked": ["Initially the gas has pressure 100 kPa and volume 60 cm³.", "At fixed temperature and amount, their product stays constant.", "Doubling pressure to 200 kPa requires half the volume: V2 = 100 times 60/200 = 30 cm³.", "Keeping kPa and cm³ is valid for this ratio because the corresponding units match on both sides."], "selfCheck": {"question": "If volume is compressed quickly, why wait before recording a Boyle-law reading?", "answer": "Compression can change temperature; waiting helps the gas return to the intended common temperature."}, "examTip": "Do not convert a gauge reading to absolute pressure by ignoring atmospheric pressure; use the apparatus definition.", "assumptions": "Gas amount and temperature remain constant; the ideal Boyle-law approximation is suitable for the measured range."}, "references": []}, {"title": "Linear thermal expansion", "concept": "Heating changes the length of a rod slightly. The coefficient of expansion describes fractional length change per degree. A dial gauge often reads millimetres while the rod length is recorded in metres, so consistent units are critical.", "formula": "\\Delta L=\\alpha L_0\\Delta T,\\quad \\alpha=m_{\\Delta L\\text{ vs }\\Delta T}/L_0", "steps": "Measure initial length and temperature, warm the rod according to the supervised procedure, then record length changes. Plot change of length against change of temperature. Divide the slope by initial length.", "example": "A 1 m rod expands 0.5 mm over 50 K, giving alpha = 0.0005/(1 times 50)=0.00001 per K.", "trap": "A graph against absolute temperature may have an intercept; do not confuse it with a change-of-temperature plot.", "q": "Two rods are made of the same material and have the same temperature rise. A rod twice as long has expansion:", "options": ["Twice as large", "Unchanged", "Four times as large", "Half as large"], "answer": 0, "why": "Expansion is proportional to original length.", "problem": "A 0.50 m rod expands 0.30 mm after warming by 40 K. Find its expansion coefficient.", "solution": "Convert expansion to 0.00030 m. Alpha=0.00030/(0.50 times 40)=0.000015 per K. Credit conversion, formula, substitution and result.", "id": "laboratory-9", "teaching": {"objectives": ["Calculate a linear expansion coefficient with compatible length units.", "Extract the coefficient from a length-change-versus-temperature graph."], "prerequisites": "Small length changes; temperature differences; mm-to-m conversion.", "symbols": [{"symbol": "\\alpha", "meaning": "linear expansion coefficient", "unit": "K⁻¹"}, {"symbol": "L_0", "meaning": "initial rod length", "unit": "m"}, {"symbol": "\\Delta L", "meaning": "length increase", "unit": "m"}, {"symbol": "\\Delta T", "meaning": "temperature increase", "unit": "K"}], "method": ["Record original rod length and the initial and final temperatures.", "Convert gauge displacement to the same length unit as the rod.", "Rearrange ΔL = αL0ΔT to solve for α.", "For a graph of ΔL against ΔT divide its slope by L0."], "worked": ["The 1 m rod expands by 0.5 mm, which is 0.0005 m.", "The temperature rise is 50 K.", "Divide extension by original length and temperature rise: α = 0.0005/(1 times 50).", "The result is 0.00001 K⁻¹, or 1.0 × 10⁻⁵ K⁻¹."], "selfCheck": {"question": "What conversion error occurs if 0.5 mm is entered as 0.5 m?", "answer": "The calculated expansion coefficient becomes 1000 times too large."}, "examTip": "Write the displacement conversion explicitly; the small numerical size of α is physically expected.", "assumptions": "The temperature range is small enough to treat α as approximately constant and the rod temperature as sufficiently uniform."}, "references": []}, {"title": "Specific heat, latent heat and Joule equivalent", "concept": "Mixing calorimetry balances heat lost by the hot sample against heat gained by water and calorimeter. Latent heat accounts for a phase change. Electrical heating provides IVt joules; comparing it with heat measured in calories gives joules per calorie, not a dimensionless ratio.", "formula": "m_sc_s(T_s-T_f)=(m_wc_w+C_{\\rm cal})(T_f-T_w),\\quad Q=mL,\\quad E=IVt", "steps": "Write every energy store that changes, including the calorimeter when its heat capacity is given. For ice experiments include warming of melted ice as needed. For Joule equivalent label which energy is in joules and which is in calories.", "example": "If 500 J melts 0.002 kg at its melting point with no other heating, latent heat is 250000 J/kg. If 418.4 J corresponds to 100 cal, the conversion is 4.184 J/cal.", "trap": "Ignoring calorimeter heat capacity or heat loss can bias the inferred material property.", "q": "Electrical energy supplied by constant voltage and current for time t is:", "options": ["V/I", "IVt", "I/t", "Vt/I"], "answer": 1, "why": "Electrical power is VI; multiplying by time gives energy.", "problem": "A heater at 6 V carries 2 A for 100 s. If all energy melts a sample already at its melting point and the melted mass is 0.004 kg, find supplied energy and latent heat.", "solution": "Energy=6 times 2 times 100=1200 J. Latent heat=120\\(\\frac00\\).004=300000 J/kg. Two marks per calculation; the no-loss and initial-phase-temperature assumptions matter.", "id": "laboratory-10", "teaching": {"objectives": ["Separate sensible heating, phase-change energy and electrical input.", "Keep the joule-per-calorie conversion dimensional."], "prerequisites": "Energy balance; electrical power; grams-to-kilograms conversion.", "symbols": [{"symbol": "Q", "meaning": "thermal energy transferred", "unit": "J"}, {"symbol": "L", "meaning": "specific latent heat", "unit": "J/kg"}, {"symbol": "I", "meaning": "heater current", "unit": "A"}, {"symbol": "V", "meaning": "heater voltage", "unit": "V"}, {"symbol": "t", "meaning": "heating duration", "unit": "s"}], "method": ["Identify whether temperature changes, phase changes or both occur.", "Calculate electrical input as IVt when heater readings are supplied.", "Use mcΔT for temperature change and mL for a phase change.", "If comparing joules with calories, divide joules by calories and state J/cal."], "worked": ["The sample receives 500 J only for melting and the melted mass is 0.002 kg.", "Rearranging Q = mL gives L = 500/0.002 = 250000 J/kg.", "In the separate conversion example, 418.4 J is compared with 100 cal.", "Their ratio is 418.4/100 = 4.184 J/cal; the unit is essential because the two energy scales differ."], "selfCheck": {"question": "If both electrical input and thermal gain are already in joules, is their ratio a J/cal conversion?", "answer": "No. It is dimensionless and tests energy accounting or an efficiency interpretation under the model."}, "examTip": "State where the energy goes before dividing by mass; not all heating energy necessarily produces the phase change.", "assumptions": "The latent-heat example assumes the sample starts at its melting point and all stated energy is used for melting."}, "references": []}, {"title": "Calorimetry: determine a solid specific heat", "concept": "A hot solid placed in cooler water transfers energy to the water and calorimeter. At equilibrium they share a final temperature. The ideal model assumes negligible heat loss to surroundings and no phase change. The calorimeter contribution must be included if it is specified.", "formula": "c_s=\\frac{(m_wc_w+C_{\\rm cal})(T_f-T_w)}{m_s(T_s-T_f)}", "steps": "Separate the hot solid temperature drop from the water temperature rise. Write the heat balance before rearranging. Check that the final temperature lies between the starting temperatures.", "example": "With a negligible calorimeter, 0.10 kg solid cooling from 80 to 30 degrees C heats 0.20 kg water from 25 to 30 degrees C. Taking water c=4200 gives solid c=840 J/(kg K).", "trap": "Using the same temperature change for hot solid and water is generally wrong.", "q": "In an ideal mixing experiment, the final equilibrium temperature lies:", "options": ["Below both", "Between the initial temperatures", "Always at zero", "Above both initial temperatures"], "answer": 1, "why": "Energy flows from the hotter body to the cooler one until equilibrium.", "problem": "A 0.20 kg solid cools from 90 to 40 degrees C and warms 0.10 kg water from 30 to 40 degrees C. Ignore calorimeter heat capacity and losses; use water c=4200 J/(kg K). Find the solid specific heat.", "solution": "Water gains 0.10 times 4200 times 10=4200 J. Solid loses 0.20 times cs times 50=10cs. Thus cs=420 J/(kg K). Two marks for each side and result.", "id": "laboratory-11", "teaching": {"objectives": ["Balance heat lost by a solid against heat gained by water and calorimeter.", "Solve for specific heat while using the correct temperature changes."], "prerequisites": "Heat capacity; mass in kg; a common final equilibrium temperature.", "symbols": [{"symbol": "c_s", "meaning": "solid specific heat capacity", "unit": "J/(kg K)"}, {"symbol": "m_s,m_w", "meaning": "solid and water masses", "unit": "kg"}, {"symbol": "C_{\\rm cal}", "meaning": "calorimeter heat capacity", "unit": "J/K"}, {"symbol": "T_f", "meaning": "final equilibrium temperature", "unit": "°C or K"}], "method": ["Identify the initially hot body, initially cold water and common final temperature.", "Write heat lost by the solid equal to heat gained by water plus calorimeter.", "Use positive temperature drops and rises on opposite sides.", "Solve for cs and state the heat-loss and calorimeter assumptions."], "worked": ["Water warms from 25°C to 30°C, a rise of 5 K.", "Its heat gain is 0.20 times 4200 times 5 = 4200 J.", "The 0.10 kg solid cools from 80°C to 30°C, a drop of 50 K.", "With negligible calorimeter heat capacity and losses, 0.10 times cs times 50 = 4200, giving cs = 840 J/(kg K)."], "selfCheck": {"question": "Why is the solid temperature change not the same as the water temperature change?", "answer": "They have different starting temperatures, though they reach the same final equilibrium temperature."}, "examTip": "Use the calorimeter heat-capacity term when supplied; discarding it undercounts heat gained by the cold side.", "assumptions": "The example neglects surroundings losses and calorimeter heat capacity and assumes no phase change."}, "references": []}, {"title": "Latent heat and electrical-to-thermal conversion", "concept": "A phase-change experiment separates melting from subsequent warming of the melted material. In the Joule-equivalent experiment electrical energy is compared with heat gained by water and calorimeter. If both quantities are already in joules, their ratio tests energy accounting; it is not a joule-per-calorie conversion.", "formula": "Q_{\\rm ice}=mL_f+mc_w(T_f-0^\\circ{\\rm C}),\\quad J_{\\rm eq}=E_{\\rm joules}/Q_{\\rm calories}", "steps": "Identify the initial phase and temperature. Include every warming or melting stage. Label energy units explicitly before calculating a conversion factor. Discuss loss to surroundings as a source of systematic bias.", "example": "If ice begins below zero degrees C, an additional warming-of-ice term is required before melting. If it begins at zero, that term is absent.", "trap": "Do not divide joules by joules and label the dimensionless answer J/cal.", "q": "To determine joules per calorie, divide electrical energy in joules by heat measured in:", "options": ["Watts", "Calories", "Kelvin", "Joules"], "answer": 1, "why": "The denominator determines the per-calorie unit.", "problem": "An electrical experiment supplies 836.8 J and records heat gain of 200 cal. Find the conversion factor. If unaccounted heat escapes, does E/Q measured tend to be too high or too low?", "solution": "Factor=836.8/200=4.184 J/cal. Heat escaping reduces measured Q for the supplied E, tending to make the ratio too high. Two marks for each part.", "id": "laboratory-12", "teaching": {"objectives": ["List all energy stages for ice melting and subsequent warming.", "Interpret how lost heat biases a measured electrical-to-calorie ratio."], "prerequisites": "Specific heat versus latent heat; phase-change temperatures; units of energy.", "symbols": [{"symbol": "m", "meaning": "ice mass", "unit": "kg"}, {"symbol": "L_f", "meaning": "specific latent heat of fusion", "unit": "J/kg"}, {"symbol": "c_w", "meaning": "liquid water specific heat", "unit": "J/(kg K)"}, {"symbol": "J_{\\rm eq}", "meaning": "joules per calorie conversion estimate", "unit": "J/cal"}], "method": ["Identify whether ice starts below or at its melting point.", "Include warming of ice if needed, then melting, then warming of meltwater to the final temperature.", "For conversion, keep electrical energy in joules and measured thermal gain in calories.", "Assess a loss by asking whether the recorded heat gain is too small or too large for the supplied energy."], "worked": ["Ice below 0°C first needs energy to warm to 0°C; that stage uses ice specific heat.", "At 0°C, energy mLf melts it without a temperature rise in the ideal fixed-pressure model.", "If the final state is liquid above 0°C, add mcw(Tf - 0°C) for the meltwater.", "When ice already starts at 0°C the first stage is absent; the melting and later warming stages remain if required."], "selfCheck": {"question": "If 836.8 J supplies a recorded heat gain of 200 cal, what is E/Q, and how would unrecorded heat loss bias it?", "answer": "4.184 J/cal. If heat escapes and measured Q is too small, E/Q tends to be too high."}, "examTip": "Do not use the water specific heat for warming solid ice; the two phases have different heat capacities.", "assumptions": "The ice formulas use an ordinary-pressure melting point of approximately 0°C and account for the stated final phase."}, "references": []}], "tests": [{"name": "A", "indices": [0, 1, 2, 3, 4, 5]}, {"name": "B", "indices": [6, 7, 8, 9, 10, 11]}], "figure": {"src": "assets/laboratory.svg", "lessonId": "laboratory-2", "caption": "Plot period squared vertically against pendulum length horizontally. The theoretical slope is 4π²/g. Illustrated points are ideal model values, not experimental observations."}}, {"slug": "safety", "title": "Instruments and Lab Safety", "scope": "SCI 101 lecture chapters 1-3: accident prevention, chemical hazards, laboratory techniques, emergency principles and biosafety. This is exam study material; real laboratory work follows the current instructor procedure and chemical-specific safety information.", "source": "10DAt1gREZwe8ILnlvS4JMAW8eMVOqtQs", "lessons": [{"title": "Hazard, risk and prevention", "concept": "A hazard is a source of possible harm. Risk depends on exposure and the chance and severity of harm. Accident prevention is shared: prepare, follow approved procedures and report unsafe conditions. A familiar chemical or routine experiment can still present hazards.", "formula": "\\text{Good answer: hazard }\\to\\text{ exposure route }\\to\\text{ control}", "steps": "For a scenario, name the specific hazard, explain how exposure could occur, then select a control that interrupts that route. Prefer preventing exposure rather than relying only on PPE.", "example": "A volatile harmful liquid on an open bench creates an inhalation hazard. Using the approved fume-hood procedure reduces exposure; goggles alone do not control vapour inhalation.", "trap": "Do not write only be careful; name a concrete control.", "q": "Which best describes risk?", "options": ["The mass of any bottle", "The same as smell", "The label colour alone", "The chance and severity of harm under the exposure conditions"], "answer": 3, "why": "Risk depends on both the hazard and how people are exposed.", "problem": "A student uses an unfamiliar reagent without reading its safety information. Identify the problem and two appropriate preparatory actions.", "solution": "Problem: unassessed chemical hazards. Actions: consult the reagent SDS and approved procedure; clarify required controls and waste handling with the instructor before use. One mark for hazard, one for exposure reasoning and one per specific action.", "id": "safety-1", "teaching": {"objectives": ["Distinguish a hazard from the risk of harm in a particular situation.", "Choose a control that interrupts the actual exposure route."], "prerequisites": "Hazard means potential for harm; exposure means contact with the harmful agent.", "symbols": [], "method": ["Name the harmful property and the activity creating exposure.", "Identify who could be exposed, by which route and under what conditions.", "Select a control that reduces the source or interrupts the route.", "Explain the remaining need for the approved procedure and required personal protection."], "worked": ["The example liquid is volatile and harmful, so vapour can leave an open container.", "A person nearby may inhale that vapour; this connects the chemical hazard to an exposure route.", "An approved fume-hood procedure controls vapour at its source when suitable for that substance and operation.", "Goggles protect eyes from appropriate hazards but do not remove vapour from inhaled air."], "selfCheck": {"question": "Why is naming only a hazardous chemical insufficient to describe a risk scenario?", "answer": "Risk also depends on how exposure can occur, how likely it is and how serious its consequences could be."}, "examTip": "For a scenario answer write a linked chain: hazard, exposure route, suitable control and reason."}, "references": []}, {"title": "Personal protective equipment and contamination", "concept": "Splash goggles protect against chemical splashes; ordinary spectacles do not provide equivalent coverage. Gloves must be compatible with the chemical and inspected. No glove protects indefinitely. Contaminated gloves can carry chemicals to phones, door handles and notebooks.", "formula": "\\text{Select PPE for the specific hazard and task}", "steps": "Match the protection to eyes, skin and clothing exposure. Identify limitations: a face shield supplements appropriate eye protection, and gloves do not replace careful handling or handwashing.", "example": "A student touches a phone with contaminated gloves. The issue is transfer of contamination to a surface later touched without gloves. Remove gloves correctly before touching clean shared items.", "trap": "More layers of unsuitable gloves do not establish chemical compatibility.", "q": "Which is appropriate before touching a clean door handle?", "options": ["Keep contaminated gloves on", "Wipe gloves on clothing", "Remove contaminated gloves correctly", "Smell the gloves"], "answer": 2, "why": "This prevents spreading contamination outside the work area.", "problem": "Explain why ordinary prescription glasses and a lab coat alone are insufficient for a splash-risk task.", "solution": "Prescription glasses do not seal against splashes; appropriate splash goggles are needed. A coat does not protect hands, so compatible gloves may be required by the assessed procedure. Award one mark per protection gap and suitable control.", "id": "safety-2", "teaching": {"objectives": ["Trace how contaminated gloves transfer material to clean surfaces.", "Select PPE for the task and remove it without spreading contamination."], "prerequisites": "Contamination transfer; clean and contaminated work zones; task-specific protection.", "symbols": [], "method": ["Identify the contaminant and which surfaces or body areas need protection.", "Use PPE specified for the material and task rather than assuming one glove type protects against everything.", "Keep contaminated gloves away from phones, door handles and other clean shared items.", "Remove and dispose of PPE according to the approved procedure, then perform required hand hygiene."], "worked": ["The student glove is already contaminated before touching the phone.", "Contact transfers material from glove to phone, creating a new contaminated surface.", "Later bare-hand contact can move that material to skin, food or the face.", "Removing gloves correctly before touching clean items breaks that transfer chain; the phone may still need the approved decontamination procedure."], "selfCheck": {"question": "Do gloves make it acceptable to touch your face during laboratory work?", "answer": "No. Gloves can carry contamination directly to the face."}, "examTip": "Explain what is transferred and to where; simply saying wear gloves does not solve a contamination scenario."}, "references": []}, {"title": "Exposure routes and toxic effects", "concept": "Chemicals can enter by inhalation, ingestion, skin or eye absorption, or injection through contaminated sharps. Acute exposure is short-term; chronic exposure is repeated or long-term. Effects can be local or systemic, immediate or delayed, reversible or irreversible.", "formula": "\\text{Dose, duration, route and substance all influence harm}", "steps": "Identify the route from the scenario rather than guessing from the chemical name. Distinguish duration of exposure from timing of symptoms: a short exposure can still have delayed effects.", "example": "Eating in a laboratory can lead to ingestion of contamination. A contaminated needle can create injection exposure even without visible vapour.", "trap": "A lack of smell does not prove safety.", "q": "Eating with contaminated hands is mainly which exposure route?", "options": ["Inhalation", "Injection", "Noise exposure", "Ingestion"], "answer": 3, "why": "Material can pass from the hands to food and the digestive system.", "problem": "Classify inhaling vapour and a contaminated needle puncture by exposure route. Explain why no smell does not prove no hazard.", "solution": "Vapour: inhalation. Needle: injection. Some harmful substances are odourless, or odour detection is unreliable. One mark per route and two for the explanation.", "id": "safety-3", "teaching": {"objectives": ["Identify inhalation, ingestion, skin or eye contact and injection exposures.", "Distinguish route of exposure from the timing of a toxic effect."], "prerequisites": "Contact with an agent can occur by several routes; visible vapour is not required.", "symbols": [], "method": ["Read the activity and locate the point where the agent could enter or contact the body.", "Name the route using the specific evidence in the scenario.", "Distinguish a rapid acute effect from an effect associated with longer or repeated exposure.", "Match prevention to the identified route and follow the material-specific procedure."], "worked": ["Eating in the laboratory can move contamination from hands or surfaces to food.", "Swallowing that material is ingestion, even when the contaminant is not visible.", "A contaminated needle can breach the skin and introduce material directly: this is injection exposure.", "The absence of visible vapour does not remove either risk because neither route depends on inhalation."], "selfCheck": {"question": "A droplet splashes into an eye. Is the route inhalation?", "answer": "No. It is eye or mucous-membrane contact."}, "examTip": "Name both the route and the evidence, for example ingestion because contaminated food is swallowed."}, "references": []}, {"title": "Labels, SDS and chemical properties", "concept": "Read the identity and hazard information before use. Safety data sheets describe hazards, handling, storage, exposure controls, first aid and other substance-specific information. Flammable, oxidizing, corrosive and toxic refer to different hazards and can apply to one substance simultaneously.", "formula": "\\text{Identity }+\\text{ hazard }+\\text{ controls }+\\text{ incompatibilities}", "steps": "For an MCQ, identify the defining property. A flame indicates a fire-related hazard; corrosion indicates corrosive effects; an oxidizer can intensify combustion. Look up incompatible substances rather than grouping bottles only alphabetically.", "example": "A corrosive liquid can damage tissue, while an oxidizer may intensify fire even when it is not itself a fuel. These require different control reasoning.", "trap": "Do not infer that all colourless liquids are harmless or that one symbol captures every hazard.", "q": "An oxidizer is especially associated with:", "options": ["Intensifying combustion", "Preventing all fires", "Measuring temperature", "Making all chemicals inert"], "answer": 0, "why": "Oxidizers can support or intensify combustion.", "problem": "A bottle has both flammable and corrosive hazards. State two distinct risks and a control principle for each.", "solution": "Fire risk: control ignition sources using the approved setup. Tissue damage from splashes: prevent contact using appropriate containment and compatible protection. One mark per risk and per linked control.", "id": "safety-4", "teaching": {"objectives": ["Use a label and SDS to connect chemical properties with controls.", "Distinguish corrosive and oxidizing hazards in an explanation."], "prerequisites": "Chemical identity; label symbols; an SDS gives substance-specific hazard and handling information.", "symbols": [], "method": ["Confirm the chemical identity from its label before selecting a procedure.", "Read relevant SDS information for hazards, incompatibilities and required handling controls.", "Explain how the named property causes harm in the scenario.", "Use the approved storage or handling arrangement rather than inferring compatibility from appearance."], "worked": ["A corrosive liquid can damage living tissue or certain materials by contact.", "An oxidizer can support or intensify combustion even when it is not itself the fuel.", "The mechanisms differ, so the same general statement handle carefully does not explain either control.", "A good answer links splash/contact controls to corrosivity and incompatibility or fire-prevention controls to oxidizing behaviour as specified by the SDS."], "selfCheck": {"question": "Does a chemical being nonflammable prove it cannot intensify a fire?", "answer": "No. An oxidizer may intensify combustion without being a fuel."}, "examTip": "Pair each property with its consequence; listing pictogram names alone gives less evidence of understanding."}, "references": []}, {"title": "Glassware, measurement and safe apparatus", "concept": "Inspect glassware for chips and cracks and apparatus for damaged wiring before use. A beaker is useful for holding and mixing; a graduated cylinder gives more useful volume estimates; a volumetric pipette or flask is designed for a specified accurate volume. Read liquid levels at eye height using the appropriate meniscus.", "formula": "\\text{Choose the instrument for required precision, not convenience}", "steps": "State the instrument function and the measurement requirement. Secure apparatus, keep it away from bench edges and allow appropriate capacity. Use a pipette aid rather than mouth pipetting.", "example": "A volumetric flask prepares a solution to its marked final volume. It is not the appropriate vessel for directly heating a reaction.", "trap": "Extra decimal places do not make an imprecise instrument accurate.", "q": "Which is designed to prepare one accurately specified solution volume?", "options": ["A beaker", "A watch glass", "A volumetric flask", "A test-tube rack"], "answer": 2, "why": "The calibration mark defines the specified contained volume under its calibration conditions.", "problem": "Name a suitable device to transfer an accurate fixed 10 mL volume and explain two good practices.", "solution": "Use an appropriate 10 mL volumetric pipette with a pipette aid. Read the meniscus at eye level and follow the calibrated delivery procedure. Credit device, aid and two measurement practices.", "id": "safety-5", "teaching": {"objectives": ["Select apparatus according to measurement purpose and safe operating limits.", "Explain why volumetric preparation and heating require different vessels."], "prerequisites": "Volume; calibration mark; damaged glassware can fail during use.", "symbols": [], "method": ["State whether the task requires approximate volume, accurate delivery or preparation to a final volume.", "Choose the apparatus designed for that purpose and check its condition.", "Follow the specified filling, meniscus and operating procedure.", "Before heating, verify that the vessel and setup are approved for the process."], "worked": ["The volumetric flask is calibrated to contain a stated final volume at its reference conditions.", "The solution is brought to the mark as part of an approved preparation procedure.", "Its main role is volume accuracy, not serving as a directly heated reaction vessel.", "For heating a reaction, use the vessel and support specified by the laboratory method rather than substituting the flask."], "selfCheck": {"question": "Does having a calibration mark mean a flask is suitable for direct heating?", "answer": "No. Calibration and suitability for heating are different design requirements."}, "examTip": "In apparatus questions state the purpose and limitation together: prepares final volume, unsuitable for directly heating the reaction."}, "references": []}, {"title": "Hoods, heating, cooling and pressure", "concept": "A fume hood controls airborne chemical exposure when used correctly. It is not a storage cabinet or a waste-evaporation device. Heating and cooling systems can introduce burns, pressure changes and material failure. Approved setups account for both temperature and pressure.", "formula": "\\text{Control vapour, ignition, pressure and thermal contact separately}", "steps": "Identify the hazard created by the operation. Keep the face outside the hood, maintain the required sash position and use the verified operating procedure. Do not assume a sealed vessel is safe to heat.", "example": "A volatile solvent warmed in an unsuitable sealed container can build pressure. The correct response is to stop and consult the approved setup rather than improvise a vent.", "trap": "A hood does not remove every fire, pressure or contact hazard.", "q": "A fume hood should be used as:", "options": ["Permanent chemical storage", "A controlled work enclosure for appropriate vapour hazards", "A way to evaporate all waste", "A food cupboard"], "answer": 1, "why": "It is an engineering control for relevant airborne exposures.", "problem": "Give two reasons why heating a tightly sealed vessel containing a volatile liquid is hazardous.", "solution": "Vapour generation can raise pressure, and thermal expansion can further stress the vessel. Rupture can release hot liquid or vapour. Credit two mechanisms and their resulting consequences.", "id": "safety-6", "teaching": {"objectives": ["Explain why heating a closed unsuitable vessel can create a pressure hazard.", "Recognize when an apparatus setup requires instructor review."], "prerequisites": "Heating can increase vapour production and gas pressure; equipment has specific operating limits.", "symbols": [], "method": ["Identify heat source, volatile materials and any sealed volume.", "Check the approved procedure and apparatus pressure and temperature limits.", "Use the specified containment, heating and ventilation arrangements.", "If the setup differs or becomes unsafe, stop and alert the responsible instructor instead of modifying it ad hoc."], "worked": ["Warming the volatile solvent increases vapour formation.", "In an unsuitable sealed container, expanding gas and vapour can increase internal pressure.", "The container or closure may fail because it was not designed for that operation.", "The example therefore calls for stopping and consulting the approved setup; improvising a vent is not a validated correction."], "selfCheck": {"question": "Does placing an unsuitable sealed heated vessel in a fume hood solve its pressure hazard?", "answer": "No. A hood does not make a vessel pressure-rated or validate an unsafe heating setup."}, "examTip": "Explain the mechanism, pressure buildup from heating, before giving the required stop-and-consult response."}, "references": []}, {"title": "Waste, housekeeping and emergency priorities", "concept": "Waste must follow the laboratory segregation and disposal procedure. Broken glass, sharps and chemical waste are different streams. Good housekeeping keeps exits and emergency equipment accessible. In an incident, alert others and follow the established response; do not improvise a hazardous cleanup.", "formula": "\\text{Recognize }\\to\\text{ alert }\\to\\text{ follow trained response}", "steps": "In scenario answers, identify the immediate exposure and prevent additional people from being exposed. Know the location of eyewash, safety shower and exits before starting. Describe instructor notification and the relevant local procedure.", "example": "An unknown spill is not an invitation to mix in a neutralizer. Alert the instructor, keep others clear and follow the spill response appropriate to the identified material.", "trap": "Do not recommend that an untrained student fight every fire or clean every spill.", "q": "An unknown chemical spill should first prompt a student to:", "options": ["Alert the instructor and keep people clear", "Mix it with another chemical", "Ignore it", "Taste it"], "answer": 0, "why": "Unknown hazards require assessment and the established response.", "problem": "A box blocks access to the eyewash station. Explain the risk and an appropriate preventive action.", "solution": "It can delay emergency irrigation after exposure. Keep access clear and report the obstruction so it is corrected promptly under laboratory procedures. Credit emergency delay, possible worsening of injury, removal/reporting and prevention.", "id": "safety-7", "teaching": {"objectives": ["Use identification and approved procedures to choose a waste or spill response.", "State safe priorities when a spill material is unknown."], "prerequisites": "Chemical incompatibility; designated waste streams; laboratory emergency instructions.", "symbols": [], "method": ["Identify the material only if that can be done safely from available records or labels.", "Keep others clear and alert the instructor or responsible responder.", "Use the laboratory response plan for the identified hazard and your training level.", "For routine waste, use the designated compatible container and labelling procedure."], "worked": ["An unknown spill has uncertain properties, so an assumed neutralizer may be incompatible.", "Adding another chemical could cause heat, gas formation or another hazardous reaction.", "Alerting the instructor and keeping people clear limits exposure while the material and response are assessed.", "Cleanup then follows the approved spill procedure for the identified material and trained personnel."], "selfCheck": {"question": "Should an unknown laboratory liquid automatically be washed into a sink?", "answer": "No. Its identity, compatibility and approved disposal route must be established."}, "examTip": "In an emergency scenario prioritize alerting and exposure prevention; do not invent a chemical cleanup recipe."}, "references": []}, {"title": "Biosafety and the control hierarchy", "concept": "Biosafety aims to prevent unintended exposure to biological agents and their release. The general control hierarchy prefers removing a hazard, then using a safer substitute, then engineering controls, administrative controls and work practices, and PPE. The suitable controls depend on the task: removing or replacing the biological material may not be possible. Training and procedures are administrative controls; suitable containment equipment is an engineering control. Safe work practices include hand hygiene and avoiding aerosol generation.", "formula": "\\text{Eliminate }\\to\\text{ substitute }\\to\\text{ engineering }\\to\\text{ administrative/work practices }\\to\\text{ PPE}", "steps": "Classify each control by what it changes: rules and training, equipment, behaviour or worn protection. Do not confuse a chemical fume hood with a biological safety cabinet; equipment must match the assessed hazard.", "example": "Training is administrative. A suitable biological safety cabinet is engineering containment. Gloves are PPE. A safe handling technique is a work practice.", "trap": "A device with airflow is not automatically suitable for every chemical or biological hazard.", "q": "Which is an administrative control?", "options": ["Gloves", "Training and written procedures", "A sealed rotor", "Splash goggles"], "answer": 1, "why": "Administrative controls organize how work is authorized and performed.", "problem": "Classify goggles, safety training, a suitable containment cabinet and correct handwashing.", "solution": "Goggles: PPE. Training: administrative control. Suitable containment cabinet: engineering control. Correct handwashing: safe work practice (often grouped with administrative controls). One mark each.", "id": "safety-8", "teaching": {"objectives": ["Classify controls within the hazard-control hierarchy.", "Distinguish engineering containment from training, work practices and PPE."], "prerequisites": "A biological hazard may be spread through aerosols, contact or sharps depending on the activity.", "symbols": [], "method": ["Identify the biological material and activity-specific exposure route.", "Consider elimination or substitution where feasible before downstream controls.", "Classify equipment containment as engineering, training and procedures as administrative or work-practice controls, and worn barriers as PPE.", "Explain how the selected combination addresses the task and follows institutional biosafety procedures."], "worked": ["Training changes how people work, so it is an administrative control.", "A suitable biological safety cabinet provides engineering containment for its approved uses.", "Gloves form a worn barrier and are PPE.", "A safe handling technique is a work practice, generally grouped with administrative controls; the categories describe different protective mechanisms."], "selfCheck": {"question": "What is the general hierarchy from source-focused to last-line protection?", "answer": "Elimination, substitution, engineering controls, administrative controls and work practices, then PPE."}, "examTip": "Do not label every cabinet or hood as interchangeable containment; state suitable equipment for the defined biological task."}, "references": [{"title": "The control hierarchy in the correct order", "why_it_matters": "The hierarchy ranks ways to control a hazard. A list of control types is not automatically in the preferred order.", "formulas": [], "method": ["Eliminate: remove the hazard.", "Substitute: use a safer alternative after checking its risks.", "Engineering controls: separate people from the hazard using suitable equipment or containment.", "Administrative controls and work practices: use training, procedures and safe methods.", "PPE: use suitable worn protection. It adds protection but depends on correct selection and use.", "In a laboratory, eliminating or replacing the material may not be possible. The assessed task determines the suitable combination of controls."], "check": {"question": "Classify a suitable containment cabinet, safety training, gloves and correct handwashing.", "steps": ["The cabinet is an engineering control.", "Training is administrative; gloves are PPE.", "Handwashing is a safe work practice, often grouped with administrative controls."], "answer": "Engineering; administrative; PPE; work practice, respectively. Engineering controls come before administrative controls and PPE in the general hierarchy."}, "sources": [{"title": "NIOSH hierarchy of controls", "url": "https://www.cdc.gov/niosh/hierarchy-of-controls/about/"}]}]}], "tests": [{"name": "A", "indices": [0, 1, 2, 3]}, {"name": "B", "indices": [4, 5, 6, 7]}], "figure": {"src": "assets/safety.svg", "lessonId": "safety-1", "caption": "Link the hazard to a specific exposure route and suitable controls. Eye protection is one layer, not a substitute for eliminating or reducing the hazard."}}, {"slug": "environment", "title": "Humans and the Environment", "scope": "ENV101 elective: ecosystems, relationships among organisms, pollution, ecological footprint, waste management and sustainable development. The Arabic source lectures are explained here in English.", "source": "1E-rpjn51_P9VxUCK6dOcupvGsPN2qnR2", "lessons": [{"title": "Environment and ecosystem components", "concept": "An ecosystem combines organisms with the physical and chemical surroundings with which they interact. Biotic factors are living components; abiotic factors include light, temperature, water and minerals. A population is one species in an area; a community includes interacting populations.", "formula": "\\text{Organism }\\to\\text{ population }\\to\\text{ community }\\to\\text{ ecosystem}", "steps": "Identify the level named in the question. Classify examples by whether they are organisms or physical conditions. Use both living and nonliving interactions when defining an ecosystem.", "example": "Fish, algae and bacteria are biotic components of a pond. Water temperature and dissolved oxygen are abiotic factors affecting them.", "trap": "A habitat is where an organism lives; an ecosystem includes the interacting system.", "q": "Which is an abiotic factor?", "options": ["Algae", "Bacteria", "Water temperature", "Fish"], "answer": 2, "why": "Temperature is a physical condition rather than a living organism.", "problem": "Classify sunlight, grass, soil mineral content and a rabbit as biotic or abiotic.", "solution": "Sunlight and mineral content are abiotic. Grass and rabbit are biotic. One mark each.", "id": "environment-1", "teaching": {"objectives": ["Classify living and nonliving ecosystem components.", "Explain one interaction linking an organism with an abiotic factor."], "prerequisites": "An ecosystem includes organisms and the physical conditions around them.", "symbols": [], "method": ["Name the ecosystem and define the area being considered.", "Sort its organisms as biotic and its physical or chemical conditions as abiotic.", "Choose one organism and explain how a named abiotic factor affects it.", "Use a causal sentence rather than an unconnected list of examples."], "worked": ["Fish, algae and bacteria are organisms, so they are biotic pond components.", "Water temperature and dissolved oxygen are abiotic conditions even though living things can affect them.", "Fish depend on sufficient dissolved oxygen for respiration.", "The example therefore shows both a classification and an interaction between the living community and its physical environment."], "selfCheck": {"question": "Are bacteria abiotic because they are microscopic?", "answer": "No. Bacteria are living organisms and therefore biotic components."}, "examTip": "For explain questions add an interaction after classifying: name the factor, the organism and the effect."}, "references": []}, {"title": "Energy flow, food chains and decomposers", "concept": "Producers use light or chemical energy to make organic material from inorganic substances. Consumers obtain organic material by feeding. Decomposers break down dead material and help recycle nutrients. Energy passes through feeding levels and much becomes dispersed heat. Nutrients cycle, but usable energy is not recycled in the same way.", "formula": "\\text{Producer }\\to\\text{ primary consumer }\\to\\text{ secondary consumer}", "steps": "Read food-chain arrows as energy transfer from food to feeder. Distinguish a linear food chain from an interconnected food web. When calculating transfer, use the efficiency stated in the question rather than assuming one universal percentage.", "example": "In grass to grasshopper to frog, grass is the producer, grasshopper the primary consumer and frog the secondary consumer.", "trap": "The 10 percent rule is a rough teaching approximation, not a universal exact constant.", "q": "Decomposers mainly help by:", "options": ["Recycling nutrients from dead matter", "Creating sunlight", "Stopping all energy loss", "Removing all producers"], "answer": 0, "why": "They break down organic matter and return nutrients to the system.", "problem": "A question specifies 10 percent transfer efficiency at each step. Producers have 10000 energy units. Find energy available to primary and secondary consumers.", "solution": "Primary consumers receive 1000 units; secondary consumers receive 100 units. Two marks for each transfer. These values depend on the stated efficiency.", "id": "environment-2", "teaching": {"objectives": ["Assign producer and consumer roles within a stated food chain.", "Distinguish energy flow from nutrient cycling."], "prerequisites": "Producers capture energy; consumers obtain energy by feeding; decomposers break down organic material.", "symbols": [], "method": ["Start the chain with its producer and draw arrows in the direction of food-energy transfer.", "Assign each consumer level from what that organism eats in the stated chain.", "Explain that energy is used and dissipated at each transfer.", "Describe decomposers returning nutrients to the environment without claiming energy is recycled."], "worked": ["Grass captures light energy and makes organic material, so it is the producer.", "The grasshopper eats the producer and is the primary consumer.", "The frog eats that consumer and is the secondary consumer.", "The arrows grass → grasshopper → frog show transfer toward the eater; dead material from all levels can enter decomposer pathways."], "selfCheck": {"question": "Does energy cycle back through the ecosystem in the same way as mineral nutrients?", "answer": "No. Energy flows through and is eventually dissipated as heat; nutrients can be recycled."}, "examTip": "Consumer levels are roles in the specified chain; do not assign a permanent level without looking at the feeding relationship."}, "references": []}, {"title": "Population growth and limiting factors", "concept": "Population size changes through births, deaths, immigration and emigration. Rapid exponential growth can occur when resources are abundant. Limited food, space and other conditions constrain growth. Carrying capacity describes a population size an environment can sustain under specified conditions.", "formula": "\\Delta N=\\text{births}+\\text{immigration}-\\text{deaths}-\\text{emigration}", "steps": "Identify the cause of change and whether it increases or decreases population. In growth curves distinguish unrestricted growth from growth slowed by limited resources.", "example": "If births are 30, deaths 10, immigration 5 and emigration 8, the population increases by 17.", "trap": "Carrying capacity is not an unchanging property independent of habitat conditions.", "q": "Which directly reduces a local population?", "options": ["Reproduction", "Births", "Immigration", "Emigration"], "answer": 3, "why": "Emigration removes individuals from the local population.", "problem": "A population begins with 200 individuals. During a period there are 25 births, 12 deaths, 8 immigrants and 6 emigrants. Find the final size.", "solution": "Net change =25-12+8-6=15. Final size=215. Credit signs of all four processes and final total.", "id": "environment-3", "teaching": {"objectives": ["Calculate net population change from four demographic processes.", "Explain how a limiting factor can constrain population growth."], "prerequisites": "Population means members of one species in a defined area and period; basic signed addition.", "symbols": [], "method": ["Set the population boundary and time interval.", "Treat births and immigration as additions and deaths and emigration as removals.", "Add the gains and subtract the losses to obtain net change.", "If explaining growth limits, link a specific resource or condition to survival or reproduction."], "worked": ["The example gives 30 births and 5 immigrants, so total additions are 35.", "It gives 10 deaths and 8 emigrants, so total removals are 18.", "Net change is 35 - 18 = +17 individuals.", "This is the increase during the interval, not the final population; a starting population would be needed to calculate the latter."], "selfCheck": {"question": "If births equal deaths, must population size stay unchanged?", "answer": "No. Immigration and emigration can still produce a net change."}, "examTip": "Label a positive result increase and a negative result decrease; do not report net change as the final population size."}, "references": []}, {"title": "Relationships among organisms", "concept": "Competition occurs when organisms use a limited shared resource. Predation involves one organism consuming another. In mutualism both benefit; in commensalism one benefits without a substantial effect on the other; in parasitism one benefits at the host expense.", "formula": "\\text{Mutualism }(+,+),\\quad\\text{commensalism }(+,0),\\quad\\text{parasitism }(+,-)", "steps": "Determine the effect on each organism before choosing the relationship. Avoid classifying every close association as mutualism. Use the described effect rather than the species names alone.", "example": "A parasite obtaining nutrients while harming its host is a plus-minus interaction. Two plants competing for limited light are both constrained by competition.", "trap": "A relationship may be context-dependent; answer using the effects given in the question.", "q": "Both organisms benefit in:", "options": ["Parasitism", "Mutualism", "Predation", "Competition"], "answer": 1, "why": "Mutualism is defined by benefits to both participants.", "problem": "Identify a relationship where both benefit and another where one benefits while the other is harmed. Explain the signs.", "solution": "Mutualism is (+,+): both gain a benefit. Parasitism is (+,-): parasite benefits and host is harmed. One mark for each name and each explanation.", "id": "environment-4", "teaching": {"objectives": ["Identify ecological interactions from their effects on each partner.", "Support an interaction label with scenario evidence."], "prerequisites": "Benefit, harm and little measurable effect are relative to the organisms in the interaction.", "symbols": [], "method": ["Identify the two organisms and the resource or activity linking them.", "Describe the effect on the first organism and on the second separately.", "Match the two effects to the appropriate interaction category.", "Use evidence from the case rather than assuming all close associations are mutualistic."], "worked": ["The parasite obtains nutrients, so it benefits from the interaction.", "The host is harmed, giving the benefit/harm pattern commonly written plus/minus.", "The two competing plants both face restricted access to limited light.", "Competition is therefore a minus/minus interaction in the comparison with unrestricted resource access, even if one competitor does better than the other."], "selfCheck": {"question": "Does one competitor winning mean competition is automatically a benefit/harm interaction?", "answer": "No. Both incur the effects of competing for a limited resource; one may still outperform the other."}, "examTip": "Write the effect on each partner before naming the interaction; this makes similar scenarios easier to distinguish."}, "references": []}, {"title": "Pollution: sources, pathways and effects", "concept": "Pollution changes environmental conditions in ways that can cause harm or reduce usefulness. Sources can be natural or human-made. Air, water and soil pollution are connected through transport and deposition. A useful answer links a source to a pathway, an effect and a control.", "formula": "\\text{Source }\\to\\text{ pathway }\\to\\text{ receptor }\\to\\text{ effect}", "steps": "Distinguish source reduction from cleaning up after release. Name the pollutant or process when possible. Do not confuse all air-pollution phenomena with one mechanism.", "example": "Nutrient-rich runoff can stimulate excessive algal growth. Subsequent decomposition can consume dissolved oxygen and harm aquatic organisms.", "trap": "Do not say algae always produce an immediate oxygen shortage without explaining decomposition and conditions.", "q": "Excess nutrient input into water is most closely associated with:", "options": ["Eutrophication", "Lens refraction", "Sterilization", "No biological change"], "answer": 0, "why": "Nutrient enrichment can drive excessive growth and subsequent oxygen depletion.", "problem": "Explain a three-step route from excess fertilizer use to fish harm and name one preventive measure.", "solution": "Runoff carries nutrients to water; algal growth increases; decomposition can lower dissolved oxygen and harm fish. Reduce excess nutrient application or intercept runoff. One mark for each causal step and one for prevention.", "id": "environment-5", "teaching": {"objectives": ["Build a source-pathway-receptor explanation of pollution harm.", "Select prevention that interrupts a stated nutrient-runoff pathway."], "prerequisites": "Nutrients support growth; decomposition can consume dissolved oxygen.", "symbols": [], "method": ["Name the pollution source and the released material.", "Trace how the material reaches the affected ecosystem.", "Explain the intermediate process connecting exposure to the final effect.", "Choose a preventive measure and state which link it reduces."], "worked": ["Excess nutrients from fertilizer can be carried by runoff into a water body.", "Nutrient enrichment can stimulate excessive algal growth.", "When organic material is decomposed, microbial respiration can consume dissolved oxygen.", "Low oxygen can harm fish; reducing excess fertilizer or intercepting runoff addresses the source or pathway before that effect occurs."], "selfCheck": {"question": "Why is algae cause fish death an incomplete explanation?", "answer": "It omits the conditions and intermediate processes, especially decomposition and dissolved-oxygen depletion."}, "examTip": "Use connecting verbs such as carries, stimulates and consumes to make every step in the causal chain explicit."}, "references": []}, {"title": "Ecological footprint and biocapacity", "concept": "Ecological footprint estimates demand for biologically productive area needed to support consumption and absorb certain wastes. Biocapacity represents available biological production capacity. A deficit occurs when demand exceeds capacity. A global hectare is a productivity-adjusted unit, not simply any local hectare.", "formula": "\\text{Ecological deficit}=\\text{footprint}-\\text{biocapacity}\\quad\\text{if positive}", "steps": "Identify whether a quantity describes demand or supply. Use the same population basis and units before comparing. Explain changes through consumption, resource productivity and waste rather than treating the indicator as a complete measure of every environmental impact.", "example": "A population with footprint 3 global hectares per person and biocapacity 2 has a deficit of 1 per person.", "trap": "Ecological footprint and carbon footprint are related but not identical measures.", "q": "A footprint larger than biocapacity indicates:", "options": ["Unlimited sustainability", "An ecological reserve", "An ecological deficit", "Zero resource use"], "answer": 2, "why": "Demand exceeds the available biological capacity under the accounting model.", "problem": "A region has footprint 4.5 and biocapacity 2.8 global hectares per person. Identify and calculate the balance.", "solution": "It has an ecological deficit of 4.5-2.8=1.7 global hectares per person. Credit comparison, subtraction, units and deficit interpretation.", "id": "environment-6", "teaching": {"objectives": ["Compare ecological demand with biocapacity on a common basis.", "Interpret a numerical balance as a deficit or reserve."], "prerequisites": "Demand versus available capacity; subtraction; per-person and total quantities must not be mixed.", "symbols": [], "method": ["Identify footprint as demand and biocapacity as available biological production capacity.", "Check that both figures use the same units, time basis and population basis.", "Subtract biocapacity from footprint to test for a deficit.", "Explain the result within the indicator scope rather than treating it as every environmental impact."], "worked": ["The example footprint is 3 global hectares per person, describing demand.", "Biocapacity is 2 global hectares per person, describing available capacity on the same basis.", "Demand exceeds capacity by 3 - 2 = 1 global hectare per person.", "The result is an ecological deficit, not an area measured in ordinary unadjusted local hectares."], "selfCheck": {"question": "Can a region total footprint be compared directly with biocapacity per person?", "answer": "No. Convert both to totals or both to per-person values first."}, "examTip": "Write global hectares per person in a per-person result; omitting the population basis changes its meaning."}, "references": []}, {"title": "Waste management and the hierarchy", "concept": "Waste management involves preventing, collecting, sorting, treating and disposing of waste. Prevention and reduction usually come before reuse, recycling, recovery and final disposal. Hazardous items require appropriate separate handling; not every household discard belongs in an ordinary bin.", "formula": "\\text{Prevent/reduce }\\to\\text{ reuse }\\to\\text{ recycle }\\to\\text{ recover }\\to\\text{ dispose}", "steps": "Distinguish avoiding an item from reusing it and from processing it into new material. For a scenario identify the material and its hazards before choosing the local disposal stream.", "example": "Refilling a reusable bottle is reuse. Turning sorted used glass into new glass is recycling. Avoiding unnecessary packaging is prevention.", "trap": "Recycling does not erase all upstream resource use or justify unlimited consumption.", "q": "Which is highest in the general waste hierarchy?", "options": ["Disposal after mixing", "Landfill", "Uncontrolled burning", "Waste prevention"], "answer": 3, "why": "Avoiding waste reduces the need for later treatment and disposal.", "problem": "Classify avoiding excess packaging, reusing a jar, reprocessing aluminium cans and placing residual waste in an approved landfill.", "solution": "Prevention, reuse, recycling and disposal, respectively. One mark for each classification.", "id": "environment-7", "teaching": {"objectives": ["Distinguish prevention, reuse, recycling, recovery and disposal.", "Apply the waste hierarchy to a concrete material scenario."], "prerequisites": "Reuse keeps an item in service; recycling reprocesses its material.", "symbols": [], "method": ["Identify whether the action avoids waste, keeps the item in use or processes discarded material.", "Classify the action using the general hierarchy.", "For a proposed choice consider prevention or reduction first where feasible.", "Check material hazards and the approved local collection stream before actual disposal."], "worked": ["Refilling a durable bottle keeps the same item in service, so it is reuse.", "Processing separated used glass into new glass changes the material into a new product, so it is recycling.", "Avoiding unnecessary packaging prevents that material becoming waste at all.", "These actions belong at different stages of the hierarchy and should not all be labelled recycling."], "selfCheck": {"question": "Is using a clean jar again to store suitable items recycling?", "answer": "It is reuse, because the same item is used again without material reprocessing."}, "examTip": "Use the action in the scenario as evidence: avoid means prevention, use again means reuse, reprocess means recycling."}, "references": []}, {"title": "Sustainable development and integrated decisions", "concept": "Sustainable development addresses present needs while preserving future ability to meet needs. Environmental, social and economic dimensions interact. A project can improve one dimension while creating costs in another, so evaluation should consider benefits, trade-offs and long-term effects.", "formula": "\\text{Environment }+\\text{ society }+\\text{ economy}", "steps": "For an essay define the term, give one measure in each dimension, then explain how they connect. Use indicators rather than vague claims that a project is green.", "example": "A public-transport project can reduce emissions, improve access and lower travel costs, but its construction and operation also require resources and funding.", "trap": "Do not equate sustainable development with only economic growth or only nature protection.", "q": "A complete sustainability assessment considers:", "options": ["Only this month", "Environmental, social and economic effects", "Only profit", "Only tree numbers"], "answer": 1, "why": "The concept integrates all three dimensions and future consequences.", "problem": "Give one environmental, one social and one economic indicator for a campus energy-efficiency project, plus one trade-off to evaluate.", "solution": "Examples: electricity use/emissions; comfort or accessibility; cost savings/payback; upfront cost versus long-term savings. One mark for each relevant, measurable item.", "id": "environment-8", "teaching": {"objectives": ["Assess a project across environmental, social and economic dimensions.", "State measurable indicators and a trade-off for a sustainability decision."], "prerequisites": "Present and future needs; a benefit in one dimension can have costs in another.", "symbols": [], "method": ["Define the project and the needs it is intended to meet.", "Give one environmental, one social and one economic effect.", "Select an indicator that could test each effect.", "Explain one trade-off over the project life rather than declaring the project sustainable from a single benefit."], "worked": ["The public-transport example can reduce transport emissions if its use changes travel patterns.", "Improved access to education or work is a social benefit to evaluate.", "Travel costs, operating costs and funding provide economic questions.", "Construction also consumes resources and money, so a full assessment compares these costs with benefits over time."], "selfCheck": {"question": "Is lower operating energy alone enough to prove a project is sustainable?", "answer": "No. Social access, economic viability, construction impacts and long-term effects also require assessment."}, "examTip": "Replace vague words such as greener with a measurable indicator such as electricity use, emissions, access or cost over a stated period."}, "references": []}], "tests": [{"name": "A", "indices": [0, 1, 2, 3]}, {"name": "B", "indices": [4, 5, 6, 7]}], "figure": {"src": "assets/environment.svg", "lessonId": "environment-2", "caption": "Arrows point from food to consumer. This is a simplified food chain; real ecosystems contain food webs. Nutrients cycle, while energy flows through the system."}}, {"slug": "professional", "title": "Professional Development Seminar", "scope": "Elective lecture themes: teaching as a profession, teacher formation, professional learning, portfolios, standards and educational technology. This follows the teacher-development focus of the supplied file; it is not a generic career-skills course.", "source": "1E-rpjn51_P9VxUCK6dOcupvGsPN2qnR2", "lessons": [{"title": "Teaching as a profession", "concept": "The source distinguishes a profession through specialized knowledge, extended preparation, social purpose, ethical responsibilities and organized practice. Teaching is more than delivering facts: it develops learners and contributes to society. A strong exam response connects each professional criterion to a teaching example.", "formula": "\\text{Criterion }+\\text{ explanation }+\\text{ teaching example}", "steps": "Define profession, select distinct criteria, and show how each appears in teaching. Avoid repeating the same idea with different words.", "example": "Specialized knowledge includes subject expertise and pedagogy; ethical responsibility includes fair assessment and respect for learners.", "trap": "Do not assume being paid alone makes an activity a profession.", "q": "Which is a professional criterion emphasized in the lecture?", "options": ["No responsibility to society", "Learning stops at graduation", "No preparation", "Specialized knowledge and ethical standards"], "answer": 3, "why": "Professional practice combines expertise, preparation and ethical obligations.", "problem": "Give two reasons teaching is considered a profession, each with an example.", "solution": "Specialized preparation: teachers study subject knowledge and pedagogy. Ethical duty: teachers assess fairly and protect learner dignity. Two marks for each criterion-example pair.", "id": "professional-1", "teaching": {"objectives": ["Explain two criteria that make teaching a profession.", "Support each criterion with a distinct classroom example."], "prerequisites": "A professional criterion is a defining feature, not simply an employment benefit.", "symbols": [], "method": ["Define profession using expertise, preparation, social purpose and ethical responsibility.", "Select two distinct criteria relevant to the question.", "Explain each criterion in plain language.", "Attach a concrete teaching example to each explanation."], "worked": ["Subject expertise concerns what is taught; pedagogy concerns how learners are helped to understand it.", "Together they illustrate specialized professional knowledge rather than information delivery alone.", "Fair assessment and respect for learners illustrate ethical responsibility.", "The examples support two different criteria, so they provide more evidence than repeating expertise in several forms."], "selfCheck": {"question": "Does being paid alone establish that an activity is a profession?", "answer": "No. Professional status also involves specialized preparation, knowledge, responsibility and organized standards of practice."}, "examTip": "Use two complete criterion-explanation-example pairs when four marks are available, rather than a long unsupported list."}, "references": []}, {"title": "Professionalization and the teacher role", "concept": "The lecture describes development from pre-professional through semi-professional toward growing professionalization. Teacher roles extend from presenting knowledge to guiding learning, assessing progress, modelling values and supporting society. Historical labels describe development, not a reason to dismiss present expertise.", "formula": "\\text{Role }\\to\\text{ observable professional action}", "steps": "For comparisons state how preparation, knowledge and professional organization change. For role questions give an action showing the role rather than a title alone.", "example": "A teacher acting as an assessor uses evidence from student work to adapt instruction. Acting as a guide, the teacher helps learners reason rather than supplying every answer.", "trap": "A list of role names without explanation earns less evidence of understanding.", "q": "Using student work to improve instruction best illustrates the teacher as:", "options": ["A storage clerk only", "An assessor and learning guide", "A person who never changes plans", "A passive spectator"], "answer": 1, "why": "Assessment information guides the next teaching decision.", "problem": "Describe two teacher roles beyond explaining subject content.", "solution": "Assessor: identifies learning gaps using evidence and feedback. Learning guide: supports students in choosing strategies and solving problems. Two marks per role with a concrete action.", "id": "professional-2", "teaching": {"objectives": ["Describe teacher roles through observable professional actions.", "Explain how assessment evidence guides subsequent instruction."], "prerequisites": "A role describes a function; an action shows how that function appears in practice.", "symbols": [], "method": ["Identify the role asked about, such as assessor or learning guide.", "Describe a specific action the teacher takes in that role.", "Explain how the action supports learners.", "For historical comparisons, discuss changes in preparation or organization rather than dismissing current expertise."], "worked": ["As an assessor, the teacher examines student work to identify what learners understand.", "If several answers show the same error, that evidence indicates a learning gap.", "Adapting instruction in response connects the assessor role to better teaching decisions.", "As a guide, the teacher supports reasoning through questions or strategies instead of supplying every answer."], "selfCheck": {"question": "Why is gives a test alone a weak explanation of the assessor role?", "answer": "It names an activity but does not explain how evidence is interpreted or used to support learning."}, "examTip": "After every role name add a verb and object: diagnoses a misconception, gives targeted feedback or guides strategy choice."}, "references": []}, {"title": "Teacher formation: before and during service", "concept": "Teacher formation is a continuing process. Pre-service preparation establishes knowledge and skills; induction supports entry to actual teaching; continuing professional development addresses changing needs and improves practice. Training is one method of development, not the whole process.", "formula": "\\text{Pre-service }\\to\\text{ induction }\\to\\text{ continuing development}", "steps": "Match the scenario to the career stage. Explain the purpose of support at that stage. Distinguish attending a training session from evidence that practice has improved.", "example": "A mentor supporting a newly appointed teacher belongs to induction. Later peer observation and inquiry can support continuing development.", "trap": "Graduation marks an entry point, not the end of professional learning.", "q": "Support during a teacher first years of practice is mainly:", "options": ["Only pre-service admission", "Induction", "Retirement", "Waste management"], "answer": 1, "why": "Induction bridges initial preparation and independent professional practice.", "problem": "Compare pre-service preparation with induction in two clear points.", "solution": "Pre-service occurs before entry and develops foundational subject and pedagogical knowledge. Induction occurs during early practice and provides mentoring and support in the real workplace. One mark each for stage and purpose in both cases.", "id": "professional-3", "teaching": {"objectives": ["Distinguish pre-service preparation, induction and continuing development.", "Match a support activity to its career stage and purpose."], "prerequisites": "Teachers develop before entering practice and throughout their careers.", "symbols": [], "method": ["Locate the person before employment, in early practice or in established service.", "Name the matching formation stage.", "Explain the specific knowledge or support needed at that stage.", "Describe how the activity supports practice rather than treating attendance as proof of improvement."], "worked": ["The example teacher is newly appointed and is entering real classroom practice.", "Mentor support at this point is induction, bridging initial preparation and workplace demands.", "Later peer observation and inquiry are examples of continuing development.", "The method may look similar across stages, but the career context and purpose determine the classification."], "selfCheck": {"question": "Is every teacher workshop automatically pre-service preparation?", "answer": "No. A workshop during employment may be induction support or continuing development, depending on career stage and purpose."}, "examTip": "In a comparison give both timing and purpose for each stage; stating before and after alone is incomplete."}, "references": []}, {"title": "Preparation, practice and professional standards", "concept": "Teacher preparation combines subject knowledge, pedagogical understanding and supervised practice. Field experience connects theory with real learners and classroom decisions. Professional standards make expectations explicit and support self-evaluation. Licensing is a recognition process whose current requirements must be checked with the responsible body.", "formula": "\\text{Knowledge }\\to\\text{ supervised application }\\to\\text{ feedback }\\to\\text{ improvement}", "steps": "Describe what is learned, where it is applied and how feedback improves the next attempt. When discussing standards, connect an expectation to evidence rather than quoting a slogan.", "example": "After teaching a supervised lesson, a trainee reviews observations and student work, then revises the next lesson. This is a feedback cycle.", "trap": "Do not invent current licence requirements from an older lecture.", "q": "The central value of supervised field experience is:", "options": ["Eliminating evaluation", "Replacing all theory", "Connecting theory to practice with feedback", "Avoiding learners"], "answer": 2, "why": "Practice tests and develops professional knowledge in authentic settings.", "problem": "Give a four-step improvement cycle for a trainee after an observed lesson.", "solution": "Review evidence; identify one specific weakness; plan and apply a targeted change; evaluate the next lesson using evidence. One mark per coherent step.", "id": "professional-4", "teaching": {"objectives": ["Explain how supervised field experience links theory with practice.", "Construct a feedback cycle using observable evidence."], "prerequisites": "Preparation includes subject knowledge, pedagogy and supervised teaching; standards describe expected practice.", "symbols": [], "method": ["Identify the teaching expectation or intended learner outcome.", "Collect relevant evidence from observation and student work.", "Choose one specific change suggested by that evidence.", "Apply the change and evaluate the next attempt against the same expectation."], "worked": ["The trainee first teaches a supervised lesson, putting planned ideas into practice.", "Observation notes and student work show what occurred and what learners achieved.", "The trainee compares that evidence with the intended learning and revises the next lesson.", "The cycle is completed by checking whether the revision improves the next observed outcome."], "selfCheck": {"question": "Why does feedback without a subsequent change and evaluation leave the cycle incomplete?", "answer": "It identifies an issue but does not show whether the teacher acted on it or improved practice."}, "examTip": "When standards are mentioned, link one expectation to evidence; do not invent current licensing rules from a lecture."}, "references": []}, {"title": "Plan continuing professional development", "concept": "Professional development is purposeful and sustained. It begins with a learning need, sets a clear goal, chooses suitable activities and evaluates effects on practice and learners. Workshops, peer observation, professional reading and collaborative inquiry can all contribute.", "formula": "\\text{Need }\\to\\text{ goal }\\to\\text{ activity }\\to\\text{ evidence of impact}", "steps": "State a specific need instead of improve everything. Choose an activity that addresses it. Set a time frame and a way to judge the result.", "example": "A teacher notices weak student explanations, studies questioning strategies, tries them for four weeks and compares the quality of student responses.", "trap": "Attendance certificates show participation, not necessarily improved teaching.", "q": "Which is the strongest development goal?", "options": ["Improve one identified practice and evaluate its effect", "Collect the most certificates", "Become better somehow", "Attend anything"], "answer": 0, "why": "A focused goal connects action to measurable change.", "problem": "Write a short development plan for a teacher whose students struggle to explain answers.", "solution": "Need: weak explanations. Goal: improve evidence-based responses. Activity: learn and apply structured questioning. Evidence: compare student response samples before and after a defined period. One mark per linked component.", "id": "professional-5", "teaching": {"objectives": ["Write a professional-development plan linking need, goal, activity and evidence.", "Distinguish participation evidence from evidence of impact."], "prerequisites": "A development goal should address an identified teaching or learning need.", "symbols": [], "method": ["Use classroom evidence to name one specific development need.", "Write a focused goal and a realistic review period.", "Choose a learning activity and classroom application that address the goal.", "Compare relevant evidence before and after the application to judge progress."], "worked": ["The teacher notices weak student explanations, identifying a specific need.", "Studying questioning strategies is the development activity, but study alone does not show impact.", "Trying the strategies for four weeks puts the learning into classroom practice.", "Comparing response samples before and after can reveal whether explanations became clearer and better supported."], "selfCheck": {"question": "What does a workshop attendance certificate demonstrate directly?", "answer": "Participation. Improved teaching or learning needs additional evidence from practice and outcomes."}, "examTip": "Keep all four plan parts linked to the same need; an unrelated workshop does not satisfy a coherent development plan."}, "references": []}, {"title": "Portfolios and reflective evaluation", "concept": "A professional portfolio is a purposeful selection of evidence linked to goals and standards, with reflection on what the evidence demonstrates. It can include plans, student work, feedback and records of improvement. A large unorganized collection is less useful than a selective, explained one.", "formula": "\\text{Evidence }+\\text{ reflection }+\\text{ link to a goal}", "steps": "Define the portfolio purpose, select relevant evidence, organize it clearly and explain its significance. Evaluate gaps and decide what evidence or improvement is needed next.", "example": "A lesson plan paired with student work and a reflection on changes shows more than a lesson plan alone. It connects intention, outcome and learning.", "trap": "Do not include identifiable student information unnecessarily; follow the institution privacy rules.", "q": "What makes a portfolio stronger?", "options": ["No evaluation", "More unrelated documents", "Evidence linked to goals and reflection", "Only decorative pages"], "answer": 2, "why": "The reader can see what the evidence proves and how practice developed.", "problem": "Name two portfolio items and explain what each can demonstrate.", "solution": "A lesson plan can demonstrate planning and alignment. An anonymized student-work sample with commentary can demonstrate learning and the effect of feedback. Two marks per item and explanation.", "id": "professional-6", "teaching": {"objectives": ["Select portfolio evidence for a defined goal or standard.", "Explain how reflection turns an artifact into evidence of development."], "prerequisites": "An artifact is a document or sample; evidence requires an explanation of what it demonstrates.", "symbols": [], "method": ["State the portfolio purpose or professional goal.", "Select a small number of relevant artifacts and organize them clearly.", "Explain what each artifact shows and what its limitations are.", "Reflect on the outcome and identify a next improvement, protecting learner privacy."], "worked": ["The lesson plan shows what the teacher intended learners to do.", "Student work shows something about the resulting learning and where difficulties remained.", "A reflection compares the plan with that outcome and explains why a change was made.", "The three pieces together support a development claim more clearly than an unexplained plan alone."], "selfCheck": {"question": "Does adding more unrelated documents necessarily make a portfolio stronger?", "answer": "No. Relevance, clear organization and reflection matter more than volume alone."}, "examTip": "For each item finish the sentence this demonstrates… and connect it to a goal or standard; anonymize learner material as required."}, "references": []}, {"title": "Ethics, collaboration and learning communities", "concept": "Professional learning can be collaborative: colleagues discuss evidence, share practice and solve problems. Ethical practice includes respect, fairness, honesty and responsibility. Feedback should focus on observable practice and improvement, rather than personal attacks.", "formula": "\\text{Observation }+\\text{ effect }+\\text{ constructive next step}", "steps": "In a scenario identify the professional value at stake. Recommend an action that protects learners and supports improvement. Distinguish respectful confidentiality from hiding a problem that must be reported under policy.", "example": "A colleague gives feedback that a task confused learners and suggests clearer success criteria, rather than calling the teacher incompetent.", "trap": "Collaboration is not simply agreeing with everyone or sharing private student details.", "q": "Constructive professional feedback should be:", "options": ["Only praise regardless of evidence", "Unrelated to teaching", "Personal and humiliating", "Based on observation and useful next steps"], "answer": 3, "why": "Evidence-based feedback supports improvement while respecting the colleague.", "problem": "Rewrite this feedback constructively: Your lesson was bad.", "solution": "Example: Several students could not identify the task goal; stating the success criteria and checking one example before independent work may help. Credit observable evidence, effect, actionable suggestion and respectful language.", "id": "professional-7", "teaching": {"objectives": ["Rewrite personal criticism as evidence-based constructive feedback.", "Connect ethical collaboration with learner respect and improvement."], "prerequisites": "Observation is what can be seen or recorded; interpretation and personal judgement are different.", "symbols": [], "method": ["Identify an observable feature of teaching rather than a personal label.", "Describe its apparent effect on learners with available evidence.", "Suggest one feasible next step connected to that effect.", "Use respectful language and follow confidentiality and reporting responsibilities."], "worked": ["Calling a teacher incompetent attacks the person and gives no specific route to improvement.", "The example instead identifies that the task confused learners.", "Suggesting clearer success criteria connects the feedback to a teaching action the colleague can try.", "A later check of learner understanding can show whether that change helped, completing the improvement conversation."], "selfCheck": {"question": "Is constructive feedback the same as agreeing with every colleague decision?", "answer": "No. It can challenge practice, but uses evidence, respect and actionable suggestions."}, "examTip": "Structure scenario answers as observation, learner effect and next step; avoid unsupported claims about personal character."}, "references": []}, {"title": "Educational technology and evaluation of impact", "concept": "Educational technology should serve a learning goal. Teachers need to select suitable tools, design learning activities, assess outcomes and consider access and ethical use. Technical operation alone does not establish teaching value. The seminar mentions digital competencies; programming instruction is excluded from this pack as requested.", "formula": "\\text{Learning need }\\to\\text{ tool choice }\\to\\text{ activity }\\to\\text{ evaluation}", "steps": "Start from the learner task, not the novelty of the tool. Explain accessibility and how the tool supports the objective. Compare learning evidence before deciding whether it helped.", "example": "A short digital quiz can reveal misconceptions immediately, but the teacher must use the results to adapt instruction for it to support learning.", "trap": "More screen time is not itself evidence of better learning.", "q": "The best reason to choose an educational tool is:", "options": ["It supports a defined learning objective", "It has the most animations", "Everyone must use the same tool", "It is newest"], "answer": 0, "why": "Pedagogical purpose should guide selection.", "problem": "Propose a simple technology use to diagnose misconceptions, and state how you would evaluate its value.", "solution": "Use a brief concept quiz with plausible distractors. Review response patterns, reteach the misconception and check with a new question. Evaluate whether explanations or transfer improve, not only whether students clicked. One mark each for tool, diagnosis, response and evaluation.", "id": "professional-8", "teaching": {"objectives": ["Choose an educational tool to serve a specific learning objective.", "Evaluate technology through diagnosis, teacher response and learner evidence."], "prerequisites": "A tool supports an activity; learning depends on how the activity and follow-up are designed.", "symbols": [], "method": ["Name the learner objective and the misconception or difficulty to investigate.", "Choose a suitable accessible tool and design questions that reveal reasoning.", "Inspect response patterns and adapt teaching accordingly.", "Use a new question or response sample to judge whether understanding improved."], "worked": ["The brief digital quiz can make response patterns visible quickly.", "Plausible incorrect options help reveal which misconception may be present.", "The teacher must interpret those results and respond, for example with targeted explanation or discussion.", "A fresh question then checks learning; the number of clicks or time on screen alone does not establish educational value."], "selfCheck": {"question": "What is missing if a teacher runs a digital quiz but never uses its results?", "answer": "The evidence-to-action step: diagnosis has not been used to adapt instruction or check improvement."}, "examTip": "State the learning goal before the tool name and finish with evidence of learning; programming content is outside this course pack."}, "references": []}], "tests": [{"name": "A", "indices": [0, 1, 2, 3]}, {"name": "B", "indices": [4, 5, 6, 7]}], "figure": {"src": "assets/professional.svg", "lessonId": "professional-6", "caption": "A useful portfolio explains the meaning of selected evidence and identifies a next action. Collecting many documents without reflection is not enough."}}];
